INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歧视性", "is_correct": true, "explanation": "正确。「这种……的玩笑」指带有不公平区别对待内容的玩笑，「歧视性」正合语境。"}, {"text": "幽默性", "is_correct": false, "explanation": "语义：幽默性是积极的特点，与「不好笑」的评价相互矛盾。"}, {"text": "严肃性", "is_correct": false, "explanation": "语域：「严肃性」是书面正式的词，与「玩笑」的口语语域不协调。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：偶然性指事情不由确定原因决定，与玩笑内容的性质无关。"}], "explanations": {"歧视性": "正确。「这种……的玩笑」指带有不公平区别对待内容的玩笑，「歧视性」正合语境。", "幽默性": "语义：幽默性是积极的特点，与「不好笑」的评价相互矛盾。", "严肃性": "语域：「严肃性」是书面正式的词，与「玩笑」的口语语域不协调。", "偶然性": "语义：偶然性指事情不由确定原因决定，与玩笑内容的性质无关。"}, "sentence_index": 6, "correct_answer": "歧视性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家享有歧视性的权利。", "explanation": "这里应该用〈同样〉。「同样的权利」可以说；「歧视性」描述区别对待，不能用来说明权利的内容。"}, {"text": "这首歌的节奏很有歧视性。", "explanation": "这里应该用〈快〉。「节奏很快」形容音乐的速度；「歧视性」指对人的不公平区别对待，不能形容节奏。"}, {"text": "老师的板书很有歧视性。", "explanation": "这里应该用〈工整〉。「板书很工整」评价字迹是否整齐；「歧视性」不能用来形容板书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条规定带有歧视性的。", "corrected_sentence": "这条规定带有歧视性。", "error_description": "错误形式是「歧视性的」，正确形式是「歧视性」。句末作谓语的形容词后不加「的」，「的」后面没有中心语，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法有很歧视性。", "corrected_sentence": "这种做法很有歧视性。", "error_description": "错误形式是「有很歧视性」，正确形式是「很有歧视性」。程度副词「很」应放在「有」之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
