INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物或事件的发展趋势、结果能够被提前预见或推断的性质。", "primary_collocate": null, "pronunciation": "kě yù cè xìng", "ipa": "kʰɤ˨˩˦ y˥˩ tsʰɤ˥˩ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种透明应具备功能性，即足以支持外部对算法公平性、非歧视性及结果可预测性的合理评估。", "target_word": "可预测性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学实验要求结果有很高的可预测性。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统的可预测性很差，我们很难提前做计划。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律的可预测性让企业敢长期投资。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变化的可预测性比较低。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场的可预测性越高，风险越小。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想提高机器行为的可预测性。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价缺乏可预测性，投资者很难判断。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告分析了算法结果的可预测性。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清楚的规则能提高制度的可预测性。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可預測性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可预测性|事物发展趋势或结果能被提前预见的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美观性", "is_correct": false, "explanation": "语义：句中列举的是算法公平性、非歧视性等评估标准，结果美观与此无关。"}, {"text": "可预测性", "is_correct": true, "explanation": "正确：指结果能被提前推断的性质，与前面的公平性、非歧视性并列，符合评估的语境。"}, {"text": "娱乐性", "is_correct": false, "explanation": "搭配：“娱乐性”多用于节目、游戏，不能用来修饰算法结果的合理评估。"}, {"text": "趣味性", "is_correct": false, "explanation": "语义：句中列举的是公平性、非歧视性等评估标准，与趣味性无关。"}], "explanations": {"美观性": "语义：句中列举的是算法公平性、非歧视性等评估标准，结果美观与此无关。", "可预测性": "正确：指结果能被提前推断的性质，与前面的公平性、非歧视性并列，符合评估的语境。", "娱乐性": "搭配：“娱乐性”多用于节目、游戏，不能用来修饰算法结果的合理评估。", "趣味性": "语义：句中列举的是公平性、非歧视性等评估标准，与趣味性无关。"}, "sentence_index": 0, "correct_answer": "可预测性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告的可预测性很准，大家都相信它。", "explanation": "这里应该用〈预报〉。“准”用于预报的结果，说报告准不准要用〈预报〉；可预测性指事情能否被提前推断，不能说“准”。"}, {"text": "这座城市的可预测性很著名，每年都有很多游客。", "explanation": "这里应该用〈景点〉。“著名”形容景点有名气，说景点出名要用〈著名〉；可预测性指事情能否被提前推断，不能指景点。"}, {"text": "他的可预测性很强，能说十种语言。", "explanation": "这里应该用〈能力〉。〈能力〉指做事的本领，说人会说多种语言的本事要用〈能力〉；可预测性指事情能否被提前推断，不能形容人的本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地域性", "is_correct": false, "explanation": "语义：“机器行为”不具有地域属性，“提高地域性”没有意义。"}, {"text": "文学性", "is_correct": false, "explanation": "语义：工程师讨论的是机器行为的可预测性，与文学性无关。"}, {"text": "历史性", "is_correct": false, "explanation": "搭配：“历史性”多用于事件或时代，不能说机器行为的历史性。"}, {"text": "可预测性", "is_correct": true, "explanation": "正确：指机器行为能被提前推断的性质，与“提高”搭配，符合工程语境。"}], "explanations": {"地域性": "语义：“机器行为”不具有地域属性，“提高地域性”没有意义。", "文学性": "语义：工程师讨论的是机器行为的可预测性，与文学性无关。", "历史性": "搭配：“历史性”多用于事件或时代，不能说机器行为的历史性。", "可预测性": "正确：指机器行为能被提前推断的性质，与“提高”搭配，符合工程语境。"}, "sentence_index": 6, "correct_answer": "可预测性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的可预测性很漂亮，很多人来拍照。", "explanation": "这里应该用〈外观〉。〈外观〉指物体的样子，说河好看要用〈外观〉；可预测性指事情能否被提前推断，不能形容好看。"}, {"text": "他的可预测性很甜，大家都喜欢听。", "explanation": "这里应该用〈声音〉。〈甜〉形容声音好听，说嗓音好听要用〈声音〉；可预测性指事情能否被提前推断，不能形容声音。"}, {"text": "他对这段话的可预测性很深。", "explanation": "这里应该用〈理解〉。〈理解〉指懂得、弄明白，说对内容懂得深要用〈理解〉；可预测性指事情能否被提前推断，不能说“深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个系统有一只很高的可预测性。", "corrected_sentence": "这个系统有一种很高的可预测性。", "error_description": "错误在量词：可预测性是抽象名词，表示性质，应该用量词〈种〉，不能用〈只〉（〈只〉多用于动物或成对的东西）。正确说法是：有一种很高的可预测性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套制度的可预测性很多，大家都放心。", "corrected_sentence": "这套制度的可预测性很高，大家都放心。", "error_description": "错误在搭配：“可预测性”指性质，不能用数量词“多”来形容，应说“很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "漂亮", "is_correct": false, "explanation": "与“合理”没有反义关系，是形容外貌的词。"}, {"text": "不合理", "is_correct": true, "explanation": "与“合理”构成反义，表示不合乎道理。"}, {"text": "新鲜", "is_correct": false, "explanation": "与“合理”没有反义关系，指食物或空气的状态。"}, {"text": "高兴", "is_correct": false, "explanation": "与“合理”没有反义关系，指心情愉快。"}], "correct_answer": "不合理", "explanations": {"漂亮": "与“合理”没有反义关系，是形容外貌的词。", "不合理": "与“合理”构成反义，表示不合乎道理。", "新鲜": "与“合理”没有反义关系，指食物或空气的状态。", "高兴": "与“合理”没有反义关系，指心情愉快。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "与“合理”没有反义关系，指光线充足。"}, {"text": "干净", "is_correct": false, "explanation": "与“合理”没有反义关系，指没有污垢。"}, {"text": "不合理", "is_correct": true, "explanation": "与“合理”构成反义，表示不合乎道理。"}, {"text": "年轻", "is_correct": false, "explanation": "与“合理”没有反义关系，指年龄小。"}], "correct_answer": "不合理", "explanations": {"明亮": "与“合理”没有反义关系，指光线充足。", "干净": "与“合理”没有反义关系，指没有污垢。", "不合理": "与“合理”构成反义，表示不合乎道理。", "年轻": "与“合理”没有反义关系，指年龄小。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合乎道理或事理。", "primary_collocate": null, "pronunciation": "hé lǐ", "ipa": "xɤ˧˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种透明应具备功能性，即足以支持外部对算法公平性、非歧视性及结果可预测性的合理评估。", "target_word": "合理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个价格很合理，我们买吧。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的要求合理，老师同意了。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请合理安排你的时间。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要合理使用每一笔钱。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样分工很合理，大家都不累。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的解释听起来很合理。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让病人合理饮食。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租太高，不合理。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样怀疑是合理的。", "target_word": "合理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合理性", "label": "复合"}, {"form": "合理化", "label": "复合"}], "register": "中性", "sense_fingerprint": "合理|合乎道理或事理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语义：“评估”是对算法的分析，不能说漂亮。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或味道，不能修饰“评估”。"}, {"text": "合理", "is_correct": true, "explanation": "正确：指评估有道理、经得起检验，与“足以支持”的语境相符。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：评估本身不带情绪，不能说快乐。"}], "explanations": {"漂亮": "语义：“评估”是对算法的分析，不能说漂亮。", "甜蜜": "搭配：“甜蜜”形容感情或味道，不能修饰“评估”。", "合理": "正确：指评估有道理、经得起检验，与“足以支持”的语境相符。", "快乐": "语义：评估本身不带情绪，不能说快乐。"}, "sentence_index": 0, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很合理，穿起来很舒服。", "explanation": "这里应该用〈合身〉。合理指道理说得通，衣服贴身、大小合适要说〈合身〉。"}, {"text": "这批产品的质量合理，可以放心出售。", "explanation": "这里应该用〈合格〉。合理指合乎道理，产品达到规定标准要说〈合格〉。"}, {"text": "这个节目很合理，观众很喜欢。", "explanation": "这里应该用〈合时宜〉。合理指合乎道理，符合时代或场合的需要要说〈合时宜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合理", "is_correct": true, "explanation": "正确：指解释讲得通，有道理，与“听起来”的评价相符。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：解释讲的是道理，不能感到凉快。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情或味道，不能用来评价解释。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”用于物体或天气，不能形容解释听起来怎样。"}], "explanations": {"合理": "正确：指解释讲得通，有道理，与“听起来”的评价相符。", "凉快": "语义：解释讲的是道理，不能感到凉快。", "甜蜜": "语义：“甜蜜”指感情或味道，不能用来评价解释。", "潮湿": "搭配：“潮湿”用于物体或天气，不能形容解释听起来怎样。"}, "sentence_index": 6, "correct_answer": "合理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很合理，我们都很喜欢。", "explanation": "这里应该用〈合胃口〉。合理指合乎道理，菜的口味合乎人的胃口要说〈合胃口〉。"}, {"text": "她的发型很合理，大家都夸她好看。", "explanation": "这里应该用〈合适〉。〈合适〉指大小、样式与人相称，说发型配人要用〈合适〉；合理指合乎道理，不能用来形容发型。"}, {"text": "他们两人很合理，常常一起去玩。", "explanation": "这里应该用〈合拍〉。合理指合乎道理，两人性情相投、配合默契要说〈合拍〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板的决定很合理性，大家都能接受。", "corrected_sentence": "老板的决定很合理，大家都能接受。", "error_description": "错误在“合理性”：“性”是名词后缀，不能放在“很”后作谓语，应说“很合理”，不说“很合理性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的解释很合理过，我们都接受了。", "corrected_sentence": "他的解释很合理，我们都接受了。", "error_description": "错误在体标：“过”只接在动词后表示经历，形容词“合理”后不能加“过”，应说“很合理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
