INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指引人们行动或解决问题的依据或参考。", "primary_collocate": null, "pronunciation": "zhǐ nán", "ipa": "ʈʂɻ̩˨˩˦ nan˧˥", "syllable_count": 2, "sentences": [{"text": "政府发布了新指南，要求大家注意防疫。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "这份指南是医生治病的重要参考。", "target_word": "指南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为学生写了一份指南，讲怎么注意安全。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "专家们制定了一份新指南，告诉大家怎么吃。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "公司的员工都要按照这份指南做事。", "target_word": "指南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份指南为解决环境问题提供了依据。", "target_word": "指南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家出台了一份新指南，企业要照着做。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "老师说，这份指南对写论文很有帮助。", "target_word": "指南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院发布了新指南，大家都应该看看。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "这份指南让我们知道什么能做，什么不能做。", "target_word": "指南", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "操作指南", "label": "复合"}, {"form": "行动指南", "label": "复合"}], "register": "正式", "sense_fingerprint": "指南：指引人们行动、解决问题的依据或参考（名词，正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指南", "is_correct": true, "explanation": "指南：指引人们行动的依据，符合“发布”和“注意防疫”的语境。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“发布”的对象是公告、消息等，不能说发布心情。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：政府发布的是指导性文件，不会发布蛋糕。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，不能用于政府发布的正式公告。"}], "explanations": {"指南": "指南：指引人们行动的依据，符合“发布”和“注意防疫”的语境。", "心情": "搭配：“发布”的对象是公告、消息等，不能说发布心情。", "蛋糕": "语义：政府发布的是指导性文件，不会发布蛋糕。", "玩意儿": "语域：“玩意儿”是口语，不能用于政府发布的正式公告。"}, "sentence_index": 0, "correct_answer": "指南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩要达到国家指南。", "explanation": "这里应该用〈标准〉。“达到”的对象是标准，指南是指导性文件，不能用来衡量成绩。"}, {"text": "他终于实现了自己的指南。", "explanation": "这里应该用〈理想〉。“实现”的对象是理想或目标，指南是指引行动的依据，不能被实现。"}, {"text": "他每天早上都喝指南。", "explanation": "这里应该用〈咖啡〉。指南是指引行动的依据或参考，不能拿来喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指南", "is_correct": true, "explanation": "指南：指引人们行动的依据，符合“出台”和“企业照着做”的语境。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：国家出台的是政策文件，不会出台一份早餐。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不能由国家出台，也不用于企业照着做。"}, {"text": "噱头", "is_correct": false, "explanation": "语域：“噱头”是口语，指花招，不适合正式的政策文件。"}], "explanations": {"指南": "指南：指引人们行动的依据，符合“出台”和“企业照着做”的语境。", "早餐": "语义：国家出台的是政策文件，不会出台一份早餐。", "礼物": "语义：礼物不能由国家出台，也不用于企业照着做。", "噱头": "语域：“噱头”是口语，指花招，不适合正式的政策文件。"}, "sentence_index": 6, "correct_answer": "指南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上唱指南。", "explanation": "这里应该用〈歌〉。唱的应是歌，指南是指引行动的依据或参考，不能唱。"}, {"text": "他的指南每天早上七点响。", "explanation": "这里应该用〈闹钟〉。指南是指引行动的依据或参考，不会发出声音。"}, {"text": "妈妈昨天烤了指南。", "explanation": "这里应该用〈饼干〉。指南是文件或参考资料，不能烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府今天发布了一把新指南。", "corrected_sentence": "政府今天发布了一份新指南。", "error_description": "量词错误：“把”用于有柄的器具，指南是文件，应该用量词“份”。正确说法是“一份新指南”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校为新生准备了一份很新指南。", "corrected_sentence": "学校为新生准备了一份很新的指南。", "error_description": "错误在“的”：“很”修饰形容词“新”再修饰名词时，中间要加“的”，应说“很新的指南”，不说“很新指南”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
