INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来证明某个事实或真相的材料或信息。", "primary_collocate": null, "pronunciation": "zhèng jù", "ipa": "ʈʂɤŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "证据", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "警察找到了新的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有证据，不能说他有罪。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官要求律师拿出更多证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些照片是重要的证据。", "target_word": "证据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家用实验得到了可靠的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们有证据证明他当时不在家。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把证据交给了警察。", "target_word": "证据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份证据能说明事情的真相。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "证据太少，案子还没有结论。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "證據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "证据|名词|用来证明事实或真相的材料或信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明事实的材料或信息。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, {"text": "正数", "is_correct": false, "explanation": "shù（第四声）与 jù 声母不同（sh／j），意思是大于零的数。"}, {"text": "正序", "is_correct": false, "explanation": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}], "explanations": {"证据": "证据：zhèng jù，指能证明事实的材料或信息。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。", "正数": "shù（第四声）与 jù 声母不同（sh／j），意思是大于零的数。", "正序": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "与前文“提取关键假设与实验证据”搭配，指可用于证明假设的材料，符合句意。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“提取”的对象是假设、证据这类信息，不能提取“工具”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段书面、学术化的表述不协调。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”无法与“假设”并列作为“提取”的对象，句意不通。"}], "explanations": {"证据": "与前文“提取关键假设与实验证据”搭配，指可用于证明假设的材料，符合句意。", "工具": "搭配：“提取”的对象是假设、证据这类信息，不能提取“工具”。", "玩意儿": "语域：“玩意儿”是口语说法，与这段书面、学术化的表述不协调。", "感情": "语义：“感情”无法与“假设”并列作为“提取”的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在房间里找到了一只证据。", "explanation": "这里应该用〈份〉或〈条〉。“只”用于动物等，不能用来计数证据。"}, {"text": "他去派出所办理证据。", "explanation": "这里应该用〈证件〉。办理的是身份证、护照等证件；证据是证明事实的材料，不能办理。"}, {"text": "我们需要出示入场证据才能进去。", "explanation": "这里应该用〈凭证〉。进场时要出示的是门票或入场凭证；证据是证明事实的材料，不能拿来当作入场凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明事实的材料或信息。"}, {"text": "政局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。"}, {"text": "正路", "is_correct": false, "explanation": "lù 与 jù 声母不同（l／j），意思是正确的道路。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}], "explanations": {"证据": "证据：zhèng jù，指能证明事实的材料或信息。", "政局": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。", "正路": "lù 与 jù 声母不同（l／j），意思是正确的道路。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "“有证据证明”是固定搭配，指能证明事实的材料，符合句意。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“答案”不能用来“证明他不在家”，“有答案证明”搭配不当。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不能证明一个人当时在不在家，句意不通。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言本身是假话，不能用来证明事实，与“证明他不在家”的句意相矛盾。"}], "explanations": {"证据": "“有证据证明”是固定搭配，指能证明事实的材料，符合句意。", "答案": "搭配：“答案”不能用来“证明他不在家”，“有答案证明”搭配不当。", "钱": "语义：钱不能证明一个人当时在不在家，句意不通。", "谎言": "语义：谎言本身是假话，不能用来证明事实，与“证明他不在家”的句意相矛盾。"}, "sentence_index": 6, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了一个证据不来上班。", "explanation": "这里应该用〈借口〉。借口是用来推托的说法；证据是证明事实的材料，不能拿来当借口。"}, {"text": "这道题的证据写在纸上了。", "explanation": "这里应该用〈答案〉。考题的解答称为答案；证据不能写在纸上当作解答。"}, {"text": "他被指控犯了证据。", "explanation": "这里应该用〈罪名〉。被指控的是罪名（如盗窃罪），证据不能说“犯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些证据们都很有用。", "corrected_sentence": "这些证据都很有用。", "error_description": "“们”只能加在指人的名词后面，“证据”是抽象名词，不能说“证据们”，应改为“这些证据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察正在收集一只证据。", "corrected_sentence": "警察正在收集一份证据。", "error_description": "错误：量词“只”用于动物等，不能用于“证据”，应说“一份证据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
