INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指个人或事物在他人心中获得的好评和信誉，通常基于品德、能力或成绩而得到的社会认可。", "primary_collocate": null, "pronunciation": "shēng yù", "ipa": "ʂɤŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "当前，欧盟《人工智能法案》与美国联邦贸易委员会（FTC）的执法指南均表明，监管趋势正从“事后追责”转向“前置性问责”，企业若未能建立可审计的合规证据链，将面临声誉折损与巨额罚款的双重风险。", "target_word": "声誉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的声誉一直很好。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次丑闻就能毁掉企业多年的声誉。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学在国际上享有很高的声誉。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了保护个人声誉，没有公开回应。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品质量不好会影响公司的声誉。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的声誉是商人最重要的资产。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生凭着专业水平赢得了声誉。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老字号靠诚信建立了声誉。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次事故让医院的声誉受到了影响。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "基于品德能力而获得的社会好评与信誉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "声誉", "is_correct": true, "explanation": "正确。声誉指社会对某人或事物的好评与信誉，读作 shēng yù。"}, {"text": "声乐", "is_correct": false, "explanation": "yuè 与 yù 韵母不同（yù 变 yuè），意思是声乐，指歌唱艺术。"}, {"text": "声源", "is_correct": false, "explanation": "yuán 与 yù 韵母和声调都不同，意思是声音的来源。"}, {"text": "声律", "is_correct": false, "explanation": "声母混淆：lǜ 与 yù 仅声母不同（l 与零声母），同为第四声，意为声律。"}], "explanations": {"声誉": "正确。声誉指社会对某人或事物的好评与信誉，读作 shēng yù。", "声乐": "yuè 与 yù 韵母不同（yù 变 yuè），意思是声乐，指歌唱艺术。", "声源": "yuán 与 yù 韵母和声调都不同，意思是声音的来源。", "声律": "声母混淆：lǜ 与 yù 仅声母不同（l 与零声母），同为第四声，意为声律。"}, "sentence_index": null, "correct_answer": "声誉"}, "level_3": {"options": [{"text": "声誉", "is_correct": true, "explanation": "正确。“面临声誉折损”指企业的社会信誉受损，与前后的风险语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“折损”用于声誉、资产、人员等，不能说“天气折损”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是企业的社会评价，不能成为“折损”与“罚款风险”的对象。"}, {"text": "发音", "is_correct": false, "explanation": "语义：发音是语音特征，与企业面临的声誉和罚款风险无关，句意不通。"}], "explanations": {"声誉": "正确。“面临声誉折损”指企业的社会信誉受损，与前后的风险语境相符。", "天气": "搭配：“折损”用于声誉、资产、人员等，不能说“天气折损”。", "体温": "语义：体温不是企业的社会评价，不能成为“折损”与“罚款风险”的对象。", "发音": "语义：发音是语音特征，与企业面临的声誉和罚款风险无关，句意不通。"}, "sentence_index": 0, "correct_answer": "声誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的声誉很大，老师在门口都听得见。", "explanation": "这里应该用〈声音〉。声誉指社会评价，不指音量；说声音很大才表示音量。"}, {"text": "政府今天发表了重要声誉。", "explanation": "这里应该用〈声明〉。声明是公开表态的文字，可以发表；声誉是社会评价，不能说“发表”。"}, {"text": "汉语的声誉是学习的难点。", "explanation": "这里应该用〈声调〉。声调指音节的高低变化，声誉指社会评价，这里不能说声誉是难点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声誉", "is_correct": true, "explanation": "正确。“良好的声誉”是商人最重要的资产，与句中的语境吻合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是可以被当作资产的评价，“良好的体重是资产”句意荒谬。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是商人的资产，“良好的颜色”与句意不符。"}, {"text": "口感", "is_correct": false, "explanation": "搭配：“口感”多用于描述食物，不能与商人的资产搭配。"}], "explanations": {"声誉": "正确。“良好的声誉”是商人最重要的资产，与句中的语境吻合。", "体重": "语义：体重不是可以被当作资产的评价，“良好的体重是资产”句意荒谬。", "颜色": "语义：颜色不是商人的资产，“良好的颜色”与句意不符。", "口感": "搭配：“口感”多用于描述食物，不能与商人的资产搭配。"}, "sentence_index": 6, "correct_answer": "声誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院提供很好的声誉服务。", "explanation": "这里应该用〈生育〉。生育指生孩子，可以说生育服务；声誉指社会评价，不能用作服务的修饰语。"}, {"text": "这位歌手的声誉很宽，能唱很高的音。", "explanation": "这里应该用〈声域〉。二者同音，但声域指能唱的音高范围，声誉指社会评价。"}, {"text": "她的声誉一直很靠前。", "explanation": "这里应该用〈名次〉。名次指排列的位置，可以靠前；声誉是他人评价，不能说靠前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位律师在圈子里有一件很好的声誉。", "corrected_sentence": "这位律师在圈子里有一种很好的声誉。", "error_description": "错误：“声誉”的量词用了“件”。“件”多用于事情、衣物等，不能修饰声誉；正确应为“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅凭着多年的诚信赢得了很好声誉。", "corrected_sentence": "这家餐厅凭着多年的诚信赢得了很好的声誉。", "error_description": "错误：修饰“声誉”的“很好”之后漏掉了“的”。形容词加“很”修饰名词时要用“的”，应为“很好的声誉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
