INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物品损耗或人员伤亡。", "primary_collocate": null, "pronunciation": "shé sǔn", "ipa": "ʂɤ˧˥ suən˨˩˦", "syllable_count": 2, "sentences": [{"text": "当前，欧盟《人工智能法案》与美国联邦贸易委员会（FTC）的执法指南均表明，监管趋势正从“事后追责”转向“前置性问责”，企业若未能建立可审计的合规证据链，将面临声誉折损与巨额罚款的双重风险。", "target_word": "折损", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "运输过程中，部分货物发生了折损。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次战斗中，部队折损了不少兵力。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长途搬运难免会折损一些瓷器。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司因为管理不善，每年折损大量物资。", "target_word": "折损", "complexity_tier": "T3", "furigana": "gōngsī yīnwèi guǎnlǐ bú shàn, měi nián zhésǔn dàliàng wùzī。", "sentence_source": "generated"}, {"text": "暴风雪使牧场折损了上千头牛羊。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库潮湿，粮食折损严重。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支队伍在比赛前折损了两名主力。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少折损，工人们小心地包装玻璃。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批机器用了多年，零件折损很多。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "折损了", "label": "体标"}, {"form": "折损过", "label": "体标"}], "register": "正式", "sense_fingerprint": "物品损耗或人员伤亡造成的减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折损", "is_correct": true, "explanation": "正确：“折损”指损耗，与“声誉”“罚款”搭配，符合企业因合规不足而声誉受损的语境。"}, {"text": "提升", "is_correct": false, "explanation": "语义：“提升”表示使变好，与后面的“双重风险”含义相悖。"}, {"text": "巩固", "is_correct": false, "explanation": "语义：“巩固”表示使牢固，与“双重风险”的负面语境矛盾。"}, {"text": "加剧", "is_correct": false, "explanation": "搭配：“加剧”多用于负面状况加重，不能直接修饰“声誉”这样的对象，句子也不通。"}], "explanations": {"折损": "正确：“折损”指损耗，与“声誉”“罚款”搭配，符合企业因合规不足而声誉受损的语境。", "提升": "语义：“提升”表示使变好，与后面的“双重风险”含义相悖。", "巩固": "语义：“巩固”表示使牢固，与“双重风险”的负面语境矛盾。", "加剧": "搭配：“加剧”多用于负面状况加重，不能直接修饰“声誉”这样的对象，句子也不通。"}, "sentence_index": 0, "correct_answer": "折损"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在这次搬家中折损了很多时间。", "explanation": "这里应该用〈浪费〉。折损指物品损耗或人员伤亡，时间的消耗不能说折损。"}, {"text": "我们在这次装修中折损了大量的钱。", "explanation": "这里应该用〈花费〉。折损不用于钱的耗费，钱的支出要说花费。"}, {"text": "他因为这次事故折损了三天假期。", "explanation": "这里应该用〈耽误〉。折损指物品损耗或人员伤亡，假期的占用要说耽误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折损", "is_correct": true, "explanation": "正确：“折损”指粮食的损耗，与“仓库潮湿”的原因及“严重”搭配，语境通顺。"}, {"text": "增产", "is_correct": false, "explanation": "语义：“增产”指产量提高，与“仓库潮湿”及“严重”的损失语境相悖。"}, {"text": "繁殖", "is_correct": false, "explanation": "搭配：“繁殖”用于生物，粮食不能繁殖。"}, {"text": "丰收", "is_correct": false, "explanation": "语义：“丰收”表示收成好，与“严重”的负面语境矛盾。"}], "explanations": {"折损": "正确：“折损”指粮食的损耗，与“仓库潮湿”的原因及“严重”搭配，语境通顺。", "增产": "语义：“增产”指产量提高，与“仓库潮湿”及“严重”的损失语境相悖。", "繁殖": "搭配：“繁殖”用于生物，粮食不能繁殖。", "丰收": "语义：“丰收”表示收成好，与“严重”的负面语境矛盾。"}, "sentence_index": 6, "correct_answer": "折损"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的菜价折损了很多。", "explanation": "这里应该用〈下降〉。折损指物品损耗或人员伤亡，物价的下跌要说下降。"}, {"text": "他的计划折损了。", "explanation": "这里应该用〈失败〉。折损不用于计划的失败，计划没有成功要说失败。"}, {"text": "这个地区的天气折损得很厉害。", "explanation": "这里应该用〈变化〉。折损指物品损耗或人员伤亡，天气的改变要说变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "搬运时，这批瓷器没有折损了很多。", "corrected_sentence": "搬运时，这批瓷器没有折损很多。", "error_description": "错误：“没有”否定时，动词后不能再加“了”，“没有折损了很多”不合语法。正确应为“没有折损很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电梯用了十年，钢缆正在折损了很多。", "corrected_sentence": "这台电梯用了十年，钢缆正在折损很多。", "error_description": "错误：“正在”表示动作进行中，不能与“了”同用，“正在折损了很多”不合语法。正确应为“正在折损很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
