INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19946, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查、核对事物是否符合标准或规范。", "primary_collocate": null, "pronunciation": "shěn chá", "ipa": "ʂən˨˩ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "老师正在审查同学们的申请表。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同要先由律师审查。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司会审查每个人的资料。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们审查了三天，没有发现问题。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行要审查你的收入证明。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影要先送去审查。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你审查一下这份报告。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理审查完预算，就签了字。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们严格审查每一份文件。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些材料已经审查过了。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审查了", "label": "完成体（了）"}, {"form": "审查过", "label": "经历体（过）"}, {"form": "审查员", "label": "复合"}, {"form": "審查", "label": "繁体"}], "register": "书面", "sense_fingerprint": "按标准或规定核对文件、资料、申请等是否合格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审查", "is_correct": true, "explanation": "“审查”指仔细核对申请表是否合格，与“老师正在……同学们的申请表”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，申请表不能被吃。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面接歌曲，不能接“申请表”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能直接带“申请表”作宾语。"}], "explanations": {"审查": "“审查”指仔细核对申请表是否合格，与“老师正在……同学们的申请表”搭配。", "吃": "语义：“吃”指进食，申请表不能被吃。", "唱": "搭配：“唱”后面接歌曲，不能接“申请表”。", "哭": "配价：“哭”是不及物动词，后面不能直接带“申请表”作宾语。"}, "sentence_index": 0, "correct_answer": "审查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士审查了病人的血压。", "explanation": "这里应该用〈检查〉。审查用于文件、材料、申请等需要核对标准的对象，给病人量血压、检查身体要说“检查”。"}, {"text": "我们审查了美丽的风景。", "explanation": "这里应该用〈欣赏〉。审查指按标准核对，欣赏风景是享受美景，不能说“审查风景”。"}, {"text": "妈妈审查了汤的味道。", "explanation": "这里应该用〈品尝〉。尝味道是用舌头感受滋味，审查只用于核对文件或标准，不能用来尝汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审查", "is_correct": true, "explanation": "“审查”指核对报告是否合格，与“请你……一下这份报告”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，报告不能被煮。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”指咀嚼食物，报告不能被嚼。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能直接带“这份报告”作宾语。"}], "explanations": {"审查": "“审查”指核对报告是否合格，与“请你……一下这份报告”搭配。", "煮": "语义：“煮”是烹饪，报告不能被煮。", "嚼": "语义：“嚼”指咀嚼食物，报告不能被嚼。", "笑": "配价：“笑”是不及物动词，不能直接带“这份报告”作宾语。"}, "sentence_index": 6, "correct_answer": "审查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈审查了房间。", "explanation": "这里应该用〈打扫〉。打扫房间是清理卫生，审查只用于核对文件或标准。"}, {"text": "她审查了那片天空。", "explanation": "这里应该用〈仰望〉。仰望天空是抬头看，审查指按标准核对，不能用来指看天。"}, {"text": "他审查了那只小狗。", "explanation": "这里应该用〈喂〉。喂小狗是给它吃东西，审查不能用于照顾动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理仔细审查了着这份预算，然后签字。", "corrected_sentence": "经理仔细审查了这份预算，然后签字。", "error_description": "错误：“了”和“着”不能同时用在同一个动词后；“审查”后应只用“了”。正确是“审查了这份预算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你帮我审查一个这份合同。", "corrected_sentence": "请你帮我审查一下这份合同。", "error_description": "错误：“一个”是名量词，不能用来表示“审查”的次数。这里表示动作的短暂次数，应用动量补语“一下”。正确是“审查一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
