INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指某个政府机构或组织行使管理权、管辖权的区域范围。", "primary_collocate": null, "pronunciation": "xiá qū", "ipa": "ɕja˧˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个派出所的辖区很大。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷在我们辖区被抓住了。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察每天在辖区里巡逻。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起事故发生在他的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子不在我们的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府对辖区内的学校很重视。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辖区的变化让居民很高兴。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把辖区分成了三个部分。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个辖区有两所大学。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的辖区地图已经出来了。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "轄區", "label": "繁体"}], "register": "正式", "sense_fingerprint": "机构行使管辖权的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "体貌：“体重”描述人的身体，不能用于派出所的范围。"}, {"text": "辖区", "is_correct": true, "explanation": "“辖区”指派出所管辖的范围，“很大”与之搭配，句子成立。"}, {"text": "体温", "is_correct": false, "explanation": "语义：派出所没有体温，句子说不通。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“很大”一般用于面积或范围，不用于字数。"}], "explanations": {"体重": "体貌：“体重”描述人的身体，不能用于派出所的范围。", "辖区": "“辖区”指派出所管辖的范围，“很大”与之搭配，句子成立。", "体温": "语义：派出所没有体温，句子说不通。", "字数": "搭配：“很大”一般用于面积或范围，不用于字数。"}, "sentence_index": 0, "correct_answer": "辖区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条辖区很大。", "explanation": "这里应该用〈片〉。辖区是一片管理范围，“条”多用于河流、道路等细长的东西。"}, {"text": "他是我们的辖区。", "explanation": "这里应该用〈民警〉。辖区指管辖的地方，不指人；“他”是人，应说“他是我们的民警”。"}, {"text": "这块辖区属于他们的帮派。", "explanation": "这里应该用〈地盘〉。地盘可指帮派占据的地方；辖区是政府机构依法管理的区域，不属于帮派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾是身体部位，它的变化不会让居民很高兴。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：鞋码的变化与居民的心情无关，句子说不通。"}, {"text": "辖区", "is_correct": true, "explanation": "“辖区”指管辖的范围，其变化可以让居民高兴，句子成立。"}, {"text": "声调", "is_correct": false, "explanation": "搭配：“声调”不是管理的范围，不能作“变化让居民高兴”的主语。"}], "explanations": {"脚趾": "语义：脚趾是身体部位，它的变化不会让居民很高兴。", "鞋码": "语义：鞋码的变化与居民的心情无关，句子说不通。", "辖区": "“辖区”指管辖的范围，其变化可以让居民高兴，句子成立。", "声调": "搭配：“声调”不是管理的范围，不能作“变化让居民高兴”的主语。"}, "sentence_index": 6, "correct_answer": "辖区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片辖区要卖给开发商。", "explanation": "这里应该用〈地块〉。地块可以买卖，辖区是管理范围，不能卖。"}, {"text": "他把辖区搬到了新家。", "explanation": "这里应该用〈行李〉。辖区是一片管理范围，不能搬动；能搬到新家的应是行李、家具等物品。"}, {"text": "这块辖区很好吃。", "explanation": "这里应该用〈蛋糕〉。辖区是管理范围，不能吃；“好吃”只能用于食物，如“这块蛋糕很好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条辖区里有一所小学。", "corrected_sentence": "这片辖区里有一所小学。", "error_description": "量词错误：辖区是一片范围，应用“片”，“条”多用于河流、道路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个辖区了有三所小学。", "corrected_sentence": "这个辖区有三所小学。", "error_description": "“了”位置错误：“了”不能紧跟名词“辖区”，应删去，说“这个辖区有三所小学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
