INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某物从一处移到另一处，常通过某种方式或工具进行。", "primary_collocate": null, "pronunciation": "chuán shū", "ipa": "ʈʂʰwan˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "这个文件传输得很慢。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络可以传输照片和声音。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线把电从工厂传输到城市。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据传输需要几分钟。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管道把水传输到各家各户。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机传输了几张照片。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光纤传输信息的速度很快。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信号传输过程中出了问题。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正在传输今天的资料。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线路不能传输太大的文件。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传输了", "label": "体标"}, {"form": "传输着", "label": "体标"}, {"form": "传输过", "label": "体标"}, {"form": "数据传输", "label": "复合词"}, {"form": "傳輸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "借助工具把东西从一处送到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "传输", "is_correct": true, "explanation": "正确：传输 chuán shū，意思是把东西或数据从一处送到另一处。"}, {"text": "穿书", "is_correct": false, "explanation": "chuān（第一声）与 chuán（第二声）声调不同，穿书意思是穿越进书里。"}, {"text": "传述", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，传述意思是转告别人的话。"}, {"text": "传授", "is_correct": false, "explanation": "shòu 与 shū 韵母不同（ou 与 u），传授意思是把知识或技能教给别人。"}, {"text": "传说", "is_correct": false, "explanation": "shuō 与 shū 韵母不同（uo 与 u），传说意思是民间流传的故事。"}], "explanations": {"传输": "正确：传输 chuán shū，意思是把东西或数据从一处送到另一处。", "穿书": "chuān（第一声）与 chuán（第二声）声调不同，穿书意思是穿越进书里。", "传述": "shù（第四声）与 shū（第一声）声调不同，传述意思是转告别人的话。", "传授": "shòu 与 shū 韵母不同（ou 与 u），传授意思是把知识或技能教给别人。", "传说": "shuō 与 shū 韵母不同（uo 与 u），传说意思是民间流传的故事。"}, "sentence_index": null, "correct_answer": "传输"}, "level_3": {"options": [{"text": "传输", "is_correct": true, "explanation": "正确：「这个文件传输得很慢」中，传输表示文件被送出的过程，符合句意。"}, {"text": "思考", "is_correct": false, "explanation": "语义：「思考」需要有思维的主体，文件不能思考。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：「微笑」的主语必须是人，文件无法微笑。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：「咳嗽」的动作主语是人，不能用来描述文件的速度。"}], "explanations": {"传输": "正确：「这个文件传输得很慢」中，传输表示文件被送出的过程，符合句意。", "思考": "语义：「思考」需要有思维的主体，文件不能思考。", "微笑": "语义：「微笑」的主语必须是人，文件无法微笑。", "咳嗽": "搭配：「咳嗽」的动作主语是人，不能用来描述文件的速度。"}, "sentence_index": 0, "correct_answer": "传输"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把沙发传输给了朋友。", "explanation": "这里应该用〈送〉。传输多用于数据、电流、液体等，沙发是家具，要用送。"}, {"text": "这辆车传输了很多货物。", "explanation": "这里应该用〈运输〉。大批货物的运送用运输，传输不用于货车运货。"}, {"text": "他用眼神传输了心意。", "explanation": "这里应该用〈传递〉。心意、情感等的传递用传递，传输不用于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传输", "is_correct": true, "explanation": "正确：「光纤传输信息的速度很快」中，光纤作为传输媒介，传输符合句意。"}, {"text": "学习", "is_correct": false, "explanation": "语义：「学习」的主体需要是有认知能力的人，光纤不能学习信息。"}, {"text": "观察", "is_correct": false, "explanation": "语义：「观察」需要有感知的主体，光纤不能观察信息。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：「提高」的宾语多为水平、效率，不能说「提高信息」。"}], "explanations": {"传输": "正确：「光纤传输信息的速度很快」中，光纤作为传输媒介，传输符合句意。", "学习": "语义：「学习」的主体需要是有认知能力的人，光纤不能学习信息。", "观察": "语义：「观察」需要有感知的主体，光纤不能观察信息。", "提高": "搭配：「提高」的宾语多为水平、效率，不能说「提高信息」。"}, "sentence_index": 6, "correct_answer": "传输"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把包裹传输到北京。", "explanation": "这里应该用〈寄〉。实物包裹靠邮寄送达，传输不用于实物包裹。"}, {"text": "工人把桌子传输到了楼上。", "explanation": "这里应该用〈搬〉。笨重的家具要靠人搬运，传输不用于搬家具。"}, {"text": "我把垃圾传输到了楼下。", "explanation": "这里应该用〈扔〉。把垃圾拿到楼下处理要用扔，传输不指这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些资料很快就传输了完。", "corrected_sentence": "这些资料很快就传输完了。", "error_description": "错误形式「传输了完」，正确形式「传输完了」。结果补语「完」应紧跟动词，「了」放在补语之后，不能插在动词和补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把数据传输了服务器上。", "corrected_sentence": "他把数据传输到了服务器上。", "error_description": "错误形式「传输了服务器上」，正确形式「传输到了服务器上」。「传输」后应接趋向补语「到」表示送达的处所，不能省略，也不能直接接处所短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
