INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19951, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数据流是指数据在传输或处理过程中形成的连续序列。", "primary_collocate": null, "pronunciation": "shù jù liú", "ipa": "ʂu˥˩ tɕy˥˩ ljoʊ˧˥", "syllable_count": 3, "sentences": [{"text": "这个程序每秒都会接收大量数据流。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查网络中的数据流。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据流从服务器传到我的手机上。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统会实时处理传进来的数据流。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画出了整个系统的数据流。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据流太大时，网页就会很慢。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用软件记录了一小时的数据流。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据流中断了，视频就停了。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们分析这段数据流有什么问题。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把数据流保存在安全的地方。", "target_word": "数据流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据流量", "label": "复合"}], "register": "中性", "sense_fingerprint": "数据在传输或处理中形成的连续序列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据流", "is_correct": true, "explanation": "正确：「这个程序每秒都会接收大量数据流」中，数据流是程序接收的对象，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：程序不能接收石头，「接收」的对象应是信号、数据等。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：程序不会接收花瓣，这与「程序」的功能相矛盾。"}, {"text": "水流", "is_correct": false, "explanation": "搭配：「接收」多与信号、数据、信息搭配，不说「接收水流」。"}], "explanations": {"数据流": "正确：「这个程序每秒都会接收大量数据流」中，数据流是程序接收的对象，符合句意。", "石头": "语义：程序不能接收石头，「接收」的对象应是信号、数据等。", "花瓣": "语义：程序不会接收花瓣，这与「程序」的功能相矛盾。", "水流": "搭配：「接收」多与信号、数据、信息搭配，不说「接收水流」。"}, "sentence_index": 0, "correct_answer": "数据流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在网上查找了很多数据流。", "explanation": "这里应该用〈信息〉。查找的对象是信息，数据流是传输中的连续序列，不能查找。"}, {"text": "他每天用数据流煮饭。", "explanation": "这里应该用〈米〉。煮饭要用米，数据流是传输中的数字序列，不能用来煮饭。"}, {"text": "他把数据流穿在了身上。", "explanation": "这里应该用〈衣服〉。穿的是衣服，数据流是传输中的连续数据，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据流", "is_correct": true, "explanation": "正确：「他用软件记录了一小时的数据流」中，数据流是可以被记录的对象，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是可以用软件记录一小时的对象，句子无法成立。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：「用软件记录」的对象不能是一顿午饭，这与句中的软件与时长不相符。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「一小时的」修饰的应是可被记录的内容，「星期」不能与这种时长修饰搭配。"}], "explanations": {"数据流": "正确：「他用软件记录了一小时的数据流」中，数据流是可以被记录的对象，符合句意。", "蛋糕": "语义：蛋糕不是可以用软件记录一小时的对象，句子无法成立。", "午饭": "语义：「用软件记录」的对象不能是一顿午饭，这与句中的软件与时长不相符。", "星期": "搭配：「一小时的」修饰的应是可被记录的内容，「星期」不能与这种时长修饰搭配。"}, "sentence_index": 6, "correct_answer": "数据流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气喝光了数据流。", "explanation": "这里应该用〈水〉。能被喝的是液体，数据流不能喝。"}, {"text": "工人把货物装进了数据流。", "explanation": "这里应该用〈箱子〉。装进去的应是容器，数据流不是可以装东西的容器。"}, {"text": "他把数据流当成书一页页地翻看。", "explanation": "这里应该用〈文章〉。能一页页翻看的是文章或文档，数据流是传输中的连续数据序列，没有页可以翻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些数据流们都很稳定。", "corrected_sentence": "这些数据流都很稳定。", "error_description": "「们」只用于指人的名词，数据流不能加「们」，应说「这些数据流都很稳定」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "网络里突然出现了一座数据流。", "corrected_sentence": "网络里突然出现了一股数据流。", "error_description": "量词「座」用于山、桥、楼等大型物体，数据流应用「股」或「条」，不能说「一座数据流」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正向", "is_correct": true, "explanation": "正确。“正向思维”与“逆向思维”相对，指思路顺着常规方向，二者构成反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "与“逆向”没有反义关系。“迅速”形容速度快，与思维或行动的方向无关。"}, {"text": "坚硬", "is_correct": false, "explanation": "与“逆向”没有反义关系。“坚硬”形容物体的质地，与方向或思路无关。"}, {"text": "清脆", "is_correct": false, "explanation": "与“逆向”没有反义关系。“清脆”形容声音，与方向或思路无关。"}], "correct_answer": "正向", "explanations": {"正向": "正确。“正向思维”与“逆向思维”相对，指思路顺着常规方向，二者构成反义关系。", "迅速": "与“逆向”没有反义关系。“迅速”形容速度快，与思维或行动的方向无关。", "坚硬": "与“逆向”没有反义关系。“坚硬”形容物体的质地，与方向或思路无关。", "清脆": "与“逆向”没有反义关系。“清脆”形容声音，与方向或思路无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正向", "is_correct": true, "explanation": "正确。“正向思维”与“逆向思维”相对，指思路顺着常规方向，二者构成反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "与“逆向”没有反义关系。“温和”形容性情或语气，与方向或思路无关。"}, {"text": "宽广", "is_correct": false, "explanation": "与“逆向”没有反义关系。“宽广”形容空间范围，与方向或思路无关。"}, {"text": "柔软", "is_correct": false, "explanation": "与“逆向”没有反义关系。“柔软”形容物体的质地，与方向或思路无关。"}], "correct_answer": "正向", "explanations": {"正向": "正确。“正向思维”与“逆向思维”相对，指思路顺着常规方向，二者构成反义关系。", "温和": "与“逆向”没有反义关系。“温和”形容性情或语气，与方向或思路无关。", "宽广": "与“逆向”没有反义关系。“宽广”形容空间范围，与方向或思路无关。", "柔软": "与“逆向”没有反义关系。“柔软”形容物体的质地，与方向或思路无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指方向与原来的或通常的方向相反，或者行为、思维与常规相反。", "primary_collocate": null, "pronunciation": "nì xiàng", "ipa": "ni˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公开得太多，别人可能会逆向推导出模型的设计。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车逆向行驶，非常危险。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这道题要用逆向思维。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从结果出发，逆向分析原因。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上逆向行驶的车会引起事故。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师用逆向的思路研究这个软件。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "gōng chéng shī yòng nì xiàng de sī lù yán jiū zhè ge ruǎn jiàn。", "sentence_source": "generated"}, {"text": "我们换个角度，用逆向的办法试试。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逆向思考有时能找到好办法。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不能逆向骑自行车。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他逆向追踪了这条消息的来源。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逆向思维", "label": "复合"}, {"form": "逆向工程", "label": "复合"}], "register": "中性", "sense_fingerprint": "方向或思维与常规相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。目标词读 nì xiàng（第四声、第四声），意思是方向或思路与常规相反。"}, {"text": "内向", "is_correct": false, "explanation": "nèi（第四声）与 nì（第四声）声调相同，韵母不同（ei 与 i），意思是性格向内、不爱外露。"}, {"text": "意向", "is_correct": false, "explanation": "yì 与 nì 声母不同（零声母与 n），声调相同，意思是打算或意图。"}, {"text": "立项", "is_correct": false, "explanation": "lì 与 nì 声母不同（l 与 n），第二音节 xiàng 相同，意思是批准设立一个项目。"}, {"text": "志向", "is_correct": false, "explanation": "zhì 与 nì 声母不同（zh 与 n），声调相同，意思是立志追求的目标。"}], "explanations": {"逆向": "正确。目标词读 nì xiàng（第四声、第四声），意思是方向或思路与常规相反。", "内向": "nèi（第四声）与 nì（第四声）声调相同，韵母不同（ei 与 i），意思是性格向内、不爱外露。", "意向": "yì 与 nì 声母不同（零声母与 n），声调相同，意思是打算或意图。", "立项": "lì 与 nì 声母不同（l 与 n），第二音节 xiàng 相同，意思是批准设立一个项目。", "志向": "zhì 与 nì 声母不同（zh 与 n），声调相同，意思是立志追求的目标。"}, "sentence_index": null, "correct_answer": "逆向"}, "level_3": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。“逆向推导”指从结果反过来推出原理，与“公开得太多”导致别人能推出设计的语境吻合。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“推导”这类思维活动，“清脆推导”不成立。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不能修饰“推导”，“柔软推导”不成立。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”指动物，不能作为“推导”的方式，句子说不通。"}], "explanations": {"逆向": "正确。“逆向推导”指从结果反过来推出原理，与“公开得太多”导致别人能推出设计的语境吻合。", "清脆": "搭配：“清脆”形容声音，不能修饰“推导”这类思维活动，“清脆推导”不成立。", "柔软": "搭配：“柔软”形容质地，不能修饰“推导”，“柔软推导”不成立。", "宠物": "语义：“宠物”指动物，不能作为“推导”的方式，句子说不通。"}, "sentence_index": 0, "correct_answer": "逆向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的看法和老师正好逆向。", "explanation": "这里应该用〈相反〉。“逆向”多修饰名词或动词（如“逆向思维”“逆向行驶”），在“看法和老师正好……”这类比较句中不如“相反”自然。"}, {"text": "这个西瓜买回来很逆向，一点也不甜。", "explanation": "这里不能用〈逆向〉。“逆向”指方向或思路与常规相反，不用来形容西瓜的味道，应说〈甜〉〈脆〉。"}, {"text": "这次项目进展得很逆向，大家都很紧张。", "explanation": "这里应该用〈不顺利〉。“逆向”表示方向或思路与常规相反，不表示进展的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。“换个角度”说明要改变思路，“逆向的办法”即反向思考的办法，与语境吻合。"}, {"text": "常规", "is_correct": false, "explanation": "语义：“常规”指惯常的做法，与前句“换个角度”的意思相反，前后矛盾。"}, {"text": "同向", "is_correct": false, "explanation": "搭配：“同向”说方向一致，不用来修饰“办法”。"}, {"text": "平行", "is_correct": false, "explanation": "搭配：“平行”说线或关系并列，不用来修饰“办法”。"}], "explanations": {"逆向": "正确。“换个角度”说明要改变思路，“逆向的办法”即反向思考的办法，与语境吻合。", "常规": "语义：“常规”指惯常的做法，与前句“换个角度”的意思相反，前后矛盾。", "同向": "搭配：“同向”说方向一致，不用来修饰“办法”。", "平行": "搭配：“平行”说线或关系并列，不用来修饰“办法”。"}, "sentence_index": 6, "correct_answer": "逆向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把杯子逆向放在桌上。", "explanation": "这里应该用〈倒着〉。“逆向”指方向或思路相反，不用来描述物体摆放的姿态。"}, {"text": "这场比赛我们逆向地赢了。", "explanation": "这里不能用〈逆向〉。“逆向”指方向或思路与常规相反，不表示比赛的胜负。"}, {"text": "他们两人的关系很逆向，常常一起出去玩。", "explanation": "这里不能用〈逆向〉。“逆向”不用来描述人际关系的亲疏，应说〈亲密〉或〈融洽〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路是单行道，车辆不能逆向了行驶。", "corrected_sentence": "这条路是单行道，车辆不能逆向行驶。", "error_description": "错误形式“逆向了行驶”，正确形式“逆向行驶”。“逆向”作状语修饰动词“行驶”，二者之间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一只逆向思维解决了这个难题。", "corrected_sentence": "他用一种逆向思维解决了这个难题。", "error_description": "错误量词“一只”。“只”多用于动物或成对的东西，不能计量“思维”这类抽象名词；应用“种”，说“一种逆向思维”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善意", "is_correct": true, "explanation": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。"}, {"text": "礼貌", "is_correct": false, "explanation": "与“恶意”没有反义关系。“礼貌”指待人有礼节，与用意的好坏不构成对立。"}, {"text": "信心", "is_correct": false, "explanation": "与“恶意”没有反义关系。“信心”指对成功的相信，与用意无关。"}, {"text": "书籍", "is_correct": false, "explanation": "与“恶意”没有反义关系。“书籍”是具体事物，与用意无关。"}], "correct_answer": "善意", "explanations": {"善意": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。", "礼貌": "与“恶意”没有反义关系。“礼貌”指待人有礼节，与用意的好坏不构成对立。", "信心": "与“恶意”没有反义关系。“信心”指对成功的相信，与用意无关。", "书籍": "与“恶意”没有反义关系。“书籍”是具体事物，与用意无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "善意", "is_correct": true, "explanation": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "与“恶意”没有反义关系。“窗户”是具体事物，与用意无关。"}, {"text": "道路", "is_correct": false, "explanation": "与“恶意”没有反义关系。“道路”是具体事物，与用意无关。"}, {"text": "粮食", "is_correct": false, "explanation": "与“恶意”没有反义关系。“粮食”是具体事物，与用意无关。"}], "correct_answer": "善意", "explanations": {"善意": "正确。“善意”与“恶意”相对，指好的、善良的用意，二者是反义词。", "窗户": "与“恶意”没有反义关系。“窗户”是具体事物，与用意无关。", "道路": "与“恶意”没有反义关系。“道路”是具体事物，与用意无关。", "粮食": "与“恶意”没有反义关系。“粮食”是具体事物，与用意无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指存心去做坏事或伤害别人的想法和行为。", "primary_collocate": null, "pronunciation": "è yì", "ipa": "ɤ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的网站遭到了恶意攻击。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我没有恶意，只是开玩笑。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人恶意攻击这位老师。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条消息明显带着恶意。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感到那些话里有恶意。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要恶意修改别人写的文章。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他恶意破坏了公司的电脑系统。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说这是一次恶意行为。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信朋友的话没有一点恶意。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恶意软件会偷走你的密码。", "target_word": "恶意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恶意软件", "label": "复合"}, {"form": "恶意攻击", "label": "复合"}], "register": "中性", "sense_fingerprint": "存心伤害别人的坏念头和行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恶意", "is_correct": true, "explanation": "正确。“恶意攻击”指存心伤害的攻击，与“网站遭到……攻击”的语境吻合。"}, {"text": "诚意", "is_correct": false, "explanation": "搭配：“诚意”表示真心实意，不能用来修饰“攻击”。"}, {"text": "好意", "is_correct": false, "explanation": "搭配：“好意”指善良的心意，不能修饰“攻击”这类敌对行为。"}, {"text": "慈悲", "is_correct": false, "explanation": "语义：“慈悲”表示怜悯、宽厚，与“攻击”的意思相反，前后矛盾。"}], "explanations": {"恶意": "正确。“恶意攻击”指存心伤害的攻击，与“网站遭到……攻击”的语境吻合。", "诚意": "搭配：“诚意”表示真心实意，不能用来修饰“攻击”。", "好意": "搭配：“好意”指善良的心意，不能修饰“攻击”这类敌对行为。", "慈悲": "语义：“慈悲”表示怜悯、宽厚，与“攻击”的意思相反，前后矛盾。"}, "sentence_index": 0, "correct_answer": "恶意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我送来的恶意，我很感激。", "explanation": "这里应该用〈好意〉。“恶意”指存心伤害别人的念头，学习者易把它与“好意”混淆，不能用来指送来的善意。"}, {"text": "服务员的恶意让我们很感动。", "explanation": "这里应该用〈热情〉。“恶意”指存心伤害别人，不能用来形容服务员待客的热心，学习者易把它与“热情”混淆。"}, {"text": "他恶意地做了一顿饭。", "explanation": "这里不能用〈恶意〉。学习者易把“恶意”理解为“用心、刻意”，但它只指存心伤害，不能修饰“做饭”这类普通劳动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恶意", "is_correct": true, "explanation": "正确。“恶意破坏”指存心损坏，“恶意”在此作状语修饰动词“破坏”。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容待人的态度，不能修饰“破坏”这类动作。"}, {"text": "友好", "is_correct": false, "explanation": "搭配：“友好”形容关系或态度，不能说“友好地破坏”。"}, {"text": "热心", "is_correct": false, "explanation": "语义：“热心”表示乐于帮助，与“破坏”的意思相反，前后矛盾。"}], "explanations": {"恶意": "正确。“恶意破坏”指存心损坏，“恶意”在此作状语修饰动词“破坏”。", "热情": "搭配：“热情”形容待人的态度，不能修饰“破坏”这类动作。", "友好": "搭配：“友好”形容关系或态度，不能说“友好地破坏”。", "热心": "语义：“热心”表示乐于帮助，与“破坏”的意思相反，前后矛盾。"}, "sentence_index": 6, "correct_answer": "恶意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师的恶意很好，大家都喜欢他。", "explanation": "这里应该用〈善意〉。“恶意”指存心伤害别人的坏念头，不能用来评价“好”或“讨人喜欢”。"}, {"text": "他常常买恶意，同学们都很讨厌他。", "explanation": "这里应该用〈礼物〉。“恶意”是存心伤害的念头，不是可以买卖的东西，“买”的宾语应是具体物品，如“买礼物”。"}, {"text": "他恶意地同意了我们的建议。", "explanation": "这里不能用〈恶意〉。学习者易把“恶意”理解为“故意、刻意”，但它只指存心伤害，不能修饰“同意”这类表示认可的动作，应说〈欣然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他恶意着删除了公司的文件。", "corrected_sentence": "他恶意删除了公司的文件。", "error_description": "错误形式“恶意着删除”，正确形式“恶意删除”。“着”不能插在状语“恶意”和动词“删除”之间，状语后直接接动词，动作完成用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这封匿名信里带着一只恶意。", "corrected_sentence": "这封匿名信里带着一点恶意。", "error_description": "错误形式“一只恶意”，正确形式“一点恶意”。“恶意”是抽象名词，不能用动物或成对事物的量词“只”计量，表示少量时用“点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭", "is_correct": true, "explanation": "“封闭”指封锁、不让外人进入或使用，与“开放市场”的意思正相反。"}, {"text": "增长", "is_correct": false, "explanation": "“增长”指数量或程度的增加，与解除限制无关，不是反义词。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨问题，与是否允许他人进入市场没有对立关系。"}, {"text": "建设", "is_correct": false, "explanation": "“建设”指建造，与解除限制、允许他人进入不构成反义关系。"}], "correct_answer": "封闭", "explanations": {"封闭": "“封闭”指封锁、不让外人进入或使用，与“开放市场”的意思正相反。", "增长": "“增长”指数量或程度的增加，与解除限制无关，不是反义词。", "研究": "“研究”指探讨问题，与是否允许他人进入市场没有对立关系。", "建设": "“建设”指建造，与解除限制、允许他人进入不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭", "is_correct": true, "explanation": "“封闭”指封锁、不让外人进入或使用，与“对外开放课程”的意思正相反。"}, {"text": "装饰", "is_correct": false, "explanation": "“装饰”指美化物品或环境，与是否允许他人进入没有对立关系。"}, {"text": "清理", "is_correct": false, "explanation": "“清理”指把脏乱的东西清除，与解除限制无关，不是反义词。"}, {"text": "生长", "is_correct": false, "explanation": "“生长”指植物或生物的发育变大，与开放、封闭的对立无关。"}], "correct_answer": "封闭", "explanations": {"封闭": "“封闭”指封锁、不让外人进入或使用，与“对外开放课程”的意思正相反。", "装饰": "“装饰”指美化物品或环境，与是否允许他人进入没有对立关系。", "清理": "“清理”指把脏乱的东西清除，与解除限制无关，不是反义词。", "生长": "“生长”指植物或生物的发育变大，与开放、封闭的对立无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指解除封闭、限制，使事物能够被接近、使用或发展。", "primary_collocate": null, "pronunciation": "kāi fàng", "ipa": "kʰai˥ faŋ˥˩", "syllable_count": 2, "sentences": [{"text": "那家公司决定开放平台接口，让第三方开发者接入。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为它对所有人开放，研究人员、开发者和普通用户都可以测试它、提出建议或增加新功能。", "target_word": "开放", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "但支持者认为，只要管理得当，把数据开放给公众，好处远大于风险。", "target_word": "开放", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这个国家决定对外国游客开放市场。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把技术开放给大家免费使用。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的源代码已经开放了。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家开放了边境，商人可以自由来往。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所向大学开放了实验数据。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城从今年起开放了几处历史建筑，供游客参观。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对外开放了更多课程，欢迎社会人士学习。", "target_word": "开放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开放了", "label": "完成体"}, {"form": "开放着", "label": "持续体"}, {"form": "开放过", "label": "经历体"}, {"form": "开放式", "label": "复合"}, {"form": "开放性", "label": "复合"}, {"form": "開放", "label": "繁体"}], "register": "中性", "sense_fingerprint": "解除限制，使市场、技术、资源等可被他人使用或参与", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放", "is_correct": true, "explanation": "“开放接口”指把平台的接口对外提供给他人使用，与“让第三方开发者接入”相符。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色，不能作动词，句意不通。"}, {"text": "土", "is_correct": false, "explanation": "语义：“土”指不时髦、不正规，不能作动词，句意不通。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容体形，不能作动词，句意不通。"}], "explanations": {"开放": "“开放接口”指把平台的接口对外提供给他人使用，与“让第三方开发者接入”相符。", "红": "语义：“红”是颜色，不能作动词，句意不通。", "土": "语义：“土”指不时髦、不正规，不能作动词，句意不通。", "胖": "语义：“胖”形容体形，不能作动词，句意不通。"}, "sentence_index": 0, "correct_answer": "开放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开放了窗帘。", "explanation": "这里应该用〈拉开〉。拉开指把窗帘等合拢的东西张开，窗帘要用拉开；开放指让场所或资源对外允许接近或使用，不用于窗帘的开合。"}, {"text": "警察开放了那个人。", "explanation": "这里应该用〈释放〉。释放指放出被拘押的人，人被放出要用释放；开放用于场所或资源对外使用。"}, {"text": "他开放了自己的身份。", "explanation": "这里应该用〈公开〉。公开指让大家知道，身份要用公开；开放用于允许接近或使用的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放", "is_correct": true, "explanation": "“开放边境”指允许人员进出，与“商人可以自由来往”相符。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：“关闭边境”与后半句“商人可以自由来往”矛盾。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”一般用于树木、物体，不能用于边境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与国家管理边境无关。"}], "explanations": {"开放": "“开放边境”指允许人员进出，与“商人可以自由来往”相符。", "关闭": "语义：“关闭边境”与后半句“商人可以自由来往”矛盾。", "砍": "搭配：“砍”一般用于树木、物体，不能用于边境。", "唱": "语义：“唱”指发出歌声，与国家管理边境无关。"}, "sentence_index": 6, "correct_answer": "开放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府开放了救济金。", "explanation": "这里应该用〈发放〉。发放指分发钱物，救济金要用发放；开放用于场所或资源对外允许使用。"}, {"text": "妈妈开放了一件衣服。", "explanation": "这里应该用〈缝〉。缝指用针线连缀布料，衣服要用缝；开放指让场所或资源对外允许接近或使用，不用于衣物的制作。"}, {"text": "他把书开放在桌上。", "explanation": "这里应该用〈摆放〉。摆放指把东西放置在某处，书放在桌上要用摆放；开放用于场所或资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家开放过过市场，效果很好。", "corrected_sentence": "这个国家开放过市场，效果很好。", "error_description": "“过”重复：经历体“过”只用一次，应说“开放过市场”，不能写成“开放过过市场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个公园明天没开放。", "corrected_sentence": "这个公园明天不开放。", "error_description": "否定词用错：说明将来的情况应用“不”，不能用“没”。应说“明天不开放”，“明天没开放”不符合汉语的用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
