INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设法找到或得到所需要的事物。", "primary_collocate": null, "pronunciation": "xún qiú", "ipa": "ɕyn˧˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "值得注意的是，透明度实践亦存在边界——过度披露可能引发模型逆向工程或恶意攻击，故企业应在安全与开放间寻求动态平衡，采用差分隐私、联邦学习等技术手段实现“有限透明”。", "target_word": "寻求", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他遇到困难，就向朋友寻求帮助。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直在寻求解决问题的办法。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想寻求一家新的合作伙伴。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭着向妈妈寻求安慰。", "target_word": "寻求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李到处寻求工作机会，还没有找到。", "target_word": "寻求", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人来医院寻求治疗。", "target_word": "寻求", "complexity_tier": "T3", "furigana": "xún qiú", "sentence_source": "generated"}, {"text": "他寻求过很多人的支持，但没人答应。", "target_word": "寻求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生遇到不懂的问题，可以寻求老师的指导。", "target_word": "寻求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有办法都试了，还在寻求新的答案。", "target_word": "寻求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "寻求了", "label": "体标"}, {"form": "寻求过", "label": "体标"}, {"form": "寻求着", "label": "体标"}], "register": "书面", "sense_fingerprint": "设法找到或得到所需要的事物（寻求帮助、寻求答案、寻求机会）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755d8dfd-b59d-4c6c-9903-4203478bf4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打破", "is_correct": false, "explanation": "语义：“打破”意思是破坏，与“企业应在安全与开放间……动态平衡”的目的相反，句子说不通"}, {"text": "寻求", "is_correct": true, "explanation": "正确：“寻求”表示设法找到，句中“在安全与开放间寻求动态平衡”正合适"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”多接问题、矛盾，不说「制造动态平衡」"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是舍弃，与“企业应……动态平衡”的要求相反"}], "explanations": {"打破": "语义：“打破”意思是破坏，与“企业应在安全与开放间……动态平衡”的目的相反，句子说不通", "寻求": "正确：“寻求”表示设法找到，句中“在安全与开放间寻求动态平衡”正合适", "制造": "搭配：“制造”多接问题、矛盾，不说「制造动态平衡」", "放弃": "语义：“放弃”是舍弃，与“企业应……动态平衡”的要求相反"}, "sentence_index": 0, "correct_answer": "寻求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书包里寻求那本数学书。", "explanation": "这里应该用〈寻找〉。寻求多用于帮助、机会、答案等抽象事物，找具体的物品要用寻找"}, {"text": "警察在山里寻求那个失踪的孩子。", "explanation": "这里应该用〈搜寻〉。搜寻指在一定范围内找人或物，寻求的对象是帮助、答案等抽象事物"}, {"text": "他寻求那位姑娘已经很久了。", "explanation": "这里应该用〈追求〉。寻求指设法得到事物，追求人或理想要用追求"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语应是商品，不说「买治疗」"}, {"text": "提供", "is_correct": false, "explanation": "语义：“提供”是给予方做的事，病人来医院不会去提供治疗"}, {"text": "寻求", "is_correct": true, "explanation": "正确：“寻求”表示设法得到，句中“病人来医院寻求治疗”正合适"}, {"text": "实施", "is_correct": false, "explanation": "语义：“实施”是施行方案的人做的事，病人不会去实施治疗"}], "explanations": {"买": "搭配：“买”的宾语应是商品，不说「买治疗」", "提供": "语义：“提供”是给予方做的事，病人来医院不会去提供治疗", "寻求": "正确：“寻求”表示设法得到，句中“病人来医院寻求治疗”正合适", "实施": "语义：“实施”是施行方案的人做的事，病人不会去实施治疗"}, "sentence_index": 6, "correct_answer": "寻求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把三个月的工资寻求给了朋友。", "explanation": "这里应该用〈借给〉。寻求指设法得到所需之物，把钱交给别人是给出，要说借给，不能说寻求。"}, {"text": "我去银行寻求存款余额。", "explanation": "这里应该用〈查询〉。查询指查看账户、资料等信息，寻求的对象是帮助、答案等"}, {"text": "他在冬天寻求了一场感冒，躺了一个星期。", "explanation": "这里应该用〈染上〉。寻求指设法得到所需的事物，生病是不由自主地染上，不能说寻求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他遇到问题，常常向老师的寻求建议。", "corrected_sentence": "他遇到问题，常常向老师寻求建议。", "error_description": "「寻求」是动词，前面不能加「的」变成名词性说法；应说「向老师寻求建议」，不能在「老师」后面加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们寻求着很多次帮助，都没有成功。", "corrected_sentence": "他们寻求过很多次帮助，都没有成功。", "error_description": "「着」表示动作正在进行或状态持续，不能与表示多次经历的「很多次」搭配；应说「寻求过很多次帮助」，用「过」表示曾经有过的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
