INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19958, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容采取行动或措施，提前阻止可能的攻击或批评。", "primary_collocate": null, "pronunciation": "fáng yù xìng", "ipa": "fɑŋ˧˥ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "最终，合规不再仅是防御性策略，而成为塑造用户信任、构建市场差异化的核心竞争力。", "target_word": "防御性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "面对批评，他的第一反应常常是防御性的回答。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到别人提意见，她马上做出防御性的反应。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提前解释一切，这是一种防御性做法。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很有防御性，好像别人都在批评他。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现这个孩子有防御性心理，不愿听建议。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队这场比赛踢得很保守，用了防御性打法。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把可能的批评都提前写进报告，这种防御性的写法让领导无话可说。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行加强防御性措施，提前挡住网络攻击。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问得很尖锐，部长的回答带着防御性。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防禦性", "label": "繁体"}, {"form": "防御性措施", "label": "复合"}, {"form": "防御性策略", "label": "复合"}], "register": "书面", "sense_fingerprint": "防御性：形容行动、措施、态度等提前阻止攻击或批评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755d8dfd-b59d-4c6c-9903-4203478bf4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美观的", "is_correct": false, "explanation": "语义：“美观的”说外形好看，与合规作为核心竞争力的功能不符，句子说不通"}, {"text": "防御性", "is_correct": true, "explanation": "正确：“防御性”形容提前应对攻击的措施，句中“合规不再仅是防御性策略”正合适"}, {"text": "娱乐的", "is_correct": false, "explanation": "语域：“娱乐的”口语轻松，与“核心竞争力”的正式语境不合"}, {"text": "可爱的", "is_correct": false, "explanation": "搭配：“可爱的”多形容人或动物，不修饰“策略”"}], "explanations": {"美观的": "语义：“美观的”说外形好看，与合规作为核心竞争力的功能不符，句子说不通", "防御性": "正确：“防御性”形容提前应对攻击的措施，句中“合规不再仅是防御性策略”正合适", "娱乐的": "语域：“娱乐的”口语轻松，与“核心竞争力”的正式语境不合", "可爱的": "搭配：“可爱的”多形容人或动物，不修饰“策略”"}, "sentence_index": 0, "correct_answer": "防御性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件雨衣的防御性很好，能挡住雨水。", "explanation": "这里应该用〈防护性〉。防御性用于应对攻击或批评的态度和措施，衣物的保护能力要用防护性"}, {"text": "他这次提出的方案很有防御性，一上来就让大家眼前一亮。", "explanation": "这里应该用〈创造性〉。防御性指提前应对攻击或批评，方案新颖、让人眼前一亮要用创造性"}, {"text": "她说话很有防御性，句句都让人安心。", "explanation": "这里应该用〈温和〉。防御性指对攻击或批评设防，说话让人安心要用温和"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进攻性", "is_correct": false, "explanation": "语义：“进攻性”与前文“踢得很保守”的描述相反，句子前后矛盾"}, {"text": "冒险的", "is_correct": false, "explanation": "语义：“冒险的”与“很保守”矛盾，句中球队不会用冒险的打法"}, {"text": "清淡的", "is_correct": false, "explanation": "搭配：“清淡”多形容味道和风格，不用于形容“打法”"}, {"text": "防御性", "is_correct": true, "explanation": "正确：“防御性”形容以防守为主的打法，与“踢得很保守”一致"}], "explanations": {"进攻性": "语义：“进攻性”与前文“踢得很保守”的描述相反，句子前后矛盾", "冒险的": "语义：“冒险的”与“很保守”矛盾，句中球队不会用冒险的打法", "清淡的": "搭配：“清淡”多形容味道和风格，不用于形容“打法”", "防御性": "正确：“防御性”形容以防守为主的打法，与“踢得很保守”一致"}, "sentence_index": 6, "correct_answer": "防御性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅很防御性，客人口味一变，菜单就跟着变。", "explanation": "这里应该用〈灵活〉。防御性指对攻击或批评设防，菜单随客人口味调整要用灵活"}, {"text": "他对同事很防御性，总是把自己的秘密主动说给大家听。", "explanation": "这里应该用〈坦诚〉。防御性指对别人的攻击或批评设防，主动袒露心事是坦诚的表现"}, {"text": "他的态度很防御性，听到批评也欣然接受。", "explanation": "这里应该用〈虚心〉。防御性是对批评设防，欣然接受批评的态度与之相反，应说虚心"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司采取了防御性地措施，保护用户数据。", "corrected_sentence": "这家公司采取了防御性的措施，保护用户数据。", "error_description": "「防御性」修饰名词「措施」，应用「的」；「地」用来修饰动词，这里不能用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部长的回答防御性，不愿多说。", "corrected_sentence": "部长的回答很防御性，不愿多说。", "error_description": "形容词「防御性」作谓语时，前面要加程度副词「很」，应说「很防御性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
