INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "竞争力指在竞争中取胜或获得优势的能力。", "primary_collocate": null, "pronunciation": "jìng zhēng lì", "ipa": "tɕiŋ˥˩ ʈʂɤŋ˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "最终，合规不再仅是防御性策略，而成为塑造用户信任、构建市场差异化的核心竞争力。", "target_word": "竞争力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的产品质量好，竞争力很强。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "降低成本能提高企业的竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术让这个行业的竞争力提升了不少。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格太高，产品在市场上没有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的服务是公司最重要的竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的经济竞争力排在世界前列。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工的能力决定了公司的竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了增强竞争力，他们开发了新产品。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市吸引人才，竞争力越来越强。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心竞争力", "label": "复合"}], "register": "中性", "sense_fingerprint": "在竞争中取胜、获得优势的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争力", "is_correct": true, "explanation": "正确。“竞争力”指能力，与“构建市场差异化”搭配，句子讲的是企业的核心能力。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，不能作为企业构建市场差异化的核心。"}, {"text": "压力", "is_correct": false, "explanation": "搭配：“核心”后不接“压力”，“核心压力”不成词，也与“构建差异化”不符。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，常指人，与这句书面语体（塑造、构建、策略）不协调，也不能作为核心。"}], "explanations": {"竞争力": "正确。“竞争力”指能力，与“构建市场差异化”搭配，句子讲的是企业的核心能力。", "身材": "体貌：身材描述人的体型，不能作为企业构建市场差异化的核心。", "压力": "搭配：“核心”后不接“压力”，“核心压力”不成词，也与“构建差异化”不符。", "家伙": "语域：“家伙”是口语，常指人，与这句书面语体（塑造、构建、策略）不协调，也不能作为核心。"}, "sentence_index": 0, "correct_answer": "竞争力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司在价格上展开了激烈的竞争力。", "explanation": "这里应该用〈角逐〉。“展开”搭配的是角逐这类行为；竞争力指能力，不能被“展开”。"}, {"text": "下周我们要参加重要的竞争力。", "explanation": "这里应该用〈比赛〉。“参加”的对象是比赛等活动；竞争力是能力，不能被参加。"}, {"text": "这家公司有一台很强的竞争力。", "explanation": "这里应该用〈种〉。竞争力是抽象能力，量词用“种”；“台”用于机器等具体物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争力", "is_correct": true, "explanation": "正确。句子讲的是国家的经济能力，“竞争力”与“经济”搭配，且能“排在世界前列”。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积指土地或平面的大小，与“经济”无关，句子讲的是经济能力。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“经济”不能修饰“人口”，“经济人口”不成词。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述人的体形，不能用来形容一个国家的经济。"}], "explanations": {"竞争力": "正确。句子讲的是国家的经济能力，“竞争力”与“经济”搭配，且能“排在世界前列”。", "面积": "语义：面积指土地或平面的大小，与“经济”无关，句子讲的是经济能力。", "人口": "搭配：“经济”不能修饰“人口”，“经济人口”不成词。", "身高": "体貌：身高描述人的体形，不能用来形容一个国家的经济。"}, "sentence_index": 6, "correct_answer": "竞争力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的竞争力越来越多。", "explanation": "这里应该用〈竞争对手〉。竞争力是能力，不能按数量增加；“越来越多”说的是对手。"}, {"text": "他们公司有一家很强的竞争力。", "explanation": "这里应该用〈种〉。竞争力是抽象能力，量词用“种”；“家”一般用于公司、商店等机构，不用于能力。"}, {"text": "我们的竞争力是下个月卖出一万台。", "explanation": "这里应该用〈目标〉。竞争力是能力，不能当作要达到的目标；“是……”后面应说具体目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂有了一把很强的竞争力。", "corrected_sentence": "这家工厂有了一种很强的竞争力。", "error_description": "量词错误：“竞争力”是抽象的能力，应说“一种很强的竞争力”，不说“一把很强的竞争力”；“把”用于有柄的器具等，不能用于能力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次培训提高了员工的竞争力的。", "corrected_sentence": "这次培训提高了员工的竞争力。", "error_description": "多余的“的”：句末的“竞争力的”不成句，应说“提高了员工的竞争力”，去掉句末的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
