INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指通过法律、规定等对某种行为或事物进行约束和管理的规则。", "primary_collocate": null, "pronunciation": "guī zhì", "ipa": "kuei˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "那些能将法律义务转化为治理创新的企业，将在高度规制的AI时代确立不可替代的制度性优势。", "target_word": "规制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府加强了对网络平台的规制。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业的规制越来越严格。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项规制让小公司的合规成本变高了。", "target_word": "规制", "complexity_tier": "T3", "furigana": "guī zhì", "sentence_source": "generated"}, {"text": "食品安全方面需要更严的规制。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行是受到严格规制的行业。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过多的规制会影响企业发展。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国对人工智能的规制并不相同。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家建议放松对小企业的规制。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品的规制比普通商品严得多。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "通过法律规定约束和管理行为的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规制", "is_correct": true, "explanation": "“规制”指法律或规定的约束，与“法律义务”“治理”的语境相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”表示对过去的思念，与面向未来的“AI时代”不合。"}, {"text": "烹饪", "is_correct": false, "explanation": "配价：“烹饪”需要带食物作宾语，不能直接修饰“时代”。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指修复破损，与“确立优势”的语境不合。"}], "explanations": {"规制": "“规制”指法律或规定的约束，与“法律义务”“治理”的语境相符。", "怀念": "语义：“怀念”表示对过去的思念，与面向未来的“AI时代”不合。", "烹饪": "配价：“烹饪”需要带食物作宾语，不能直接修饰“时代”。", "修补": "语义：“修补”指修复破损，与“确立优势”的语境不合。"}, "sentence_index": 0, "correct_answer": "规制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "气象台规制台风的路径。", "explanation": "这里应该用〈监测〉。规制指法律或规定对行为的约束，不用于对台风路径的观测。"}, {"text": "妈妈规制家里的财务。", "explanation": "这里应该用〈管理〉。规制特指法律等对行业或行为的约束，不用于家庭内部的日常料理。"}, {"text": "他很能规制自己的情绪。", "explanation": "这里应该用〈约束〉。规制指外部的法律或规定，不用于个人对情绪的控制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规制", "is_correct": true, "explanation": "“规制”指约束和管理的规则，过多的约束会阻碍企业发展，句意通顺。"}, {"text": "酸奶", "is_correct": false, "explanation": "语义：“酸奶”是食品，与“影响企业发展”没有关系。"}, {"text": "三明治", "is_correct": false, "explanation": "语义：“三明治”是食物，过多的三明治不会影响企业发展这类事情。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：过多的鲜花与企业发展无关，句子不通。"}], "explanations": {"规制": "“规制”指约束和管理的规则，过多的约束会阻碍企业发展，句意通顺。", "酸奶": "语义：“酸奶”是食品，与“影响企业发展”没有关系。", "三明治": "语义：“三明治”是食物，过多的三明治不会影响企业发展这类事情。", "鲜花": "语义：过多的鲜花与企业发展无关，句子不通。"}, "sentence_index": 6, "correct_answer": "规制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生规制了病人的血糖。", "explanation": "这里应该用〈控制〉。规制指法律或规定对行为的约束，不用于医生对病人身体指标的控制。"}, {"text": "工程师规制了新机器的外形。", "explanation": "这里应该用〈设计〉。规制指法律或规定对行为的约束，不指设计器物的外形。"}, {"text": "作家规制了小说的结尾。", "explanation": "这里应该用〈修改〉。规制指法律或规定对行为的约束，不指改动作品的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府出台了一把新的规制，要求食品标签更清楚。", "corrected_sentence": "政府出台了一项新的规制，要求食品标签更清楚。", "error_description": "量词错误：“规制”是抽象的规定，应该用量词“项”，不能用“把”（“把”用于有柄的器具）。改为“一项新的规制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把网络平台规制很严。", "corrected_sentence": "政府把网络平台规制得很严。", "error_description": "补语错误：“规制”后面用“得”引出程度补语，“规制很严”缺少“得”，应说“规制得很严”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
