INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19967, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示令人满意、符合心意，或用于回应、赞同。", "primary_collocate": null, "pronunciation": "hǎo", "ipa": "xau˨˩˦", "syllable_count": 1, "sentences": [{"text": "好，我们现在就走。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“明天去爬山吧？”“好！”", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好，我同意你的看法。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法好，大家都喜欢。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得好，我也这样想。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上一起吃饭，好吗？", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好，就这样，明天见。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“这个主意好不好？”“好，就这么办。”", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服颜色好，大小也合适。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请把门关上。”“好，我马上关。”", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好的", "label": "应答"}, {"form": "好吗", "label": "疑问"}, {"form": "好好", "label": "重叠"}], "register": "口语", "sense_fingerprint": "好：回应他人时表示同意、赞同，或评价办法合心意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7f8796-b995-49d4-a98e-f68767af4dc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好", "is_correct": true, "explanation": "正确答案。hǎo（第三声）是“好”的读音，表示同意或合心意。"}, {"text": "号", "is_correct": false, "explanation": "hào（第四声）与 hǎo（第三声）声调不同，意思是号码、号召。"}, {"text": "毫", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，意思是毫米、一点点（毫不）。"}, {"text": "海", "is_correct": false, "explanation": "hǎi 与 hǎo 韵母不同（ai 与 ao），意思是海洋。"}, {"text": "考", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k 与 h），意思是考试。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 hǎo 声母不同（l 与 h），意思是年纪大、陈旧。"}], "explanations": {"好": "正确答案。hǎo（第三声）是“好”的读音，表示同意或合心意。", "号": "hào（第四声）与 hǎo（第三声）声调不同，意思是号码、号召。", "毫": "háo（第二声）与 hǎo（第三声）声调不同，意思是毫米、一点点（毫不）。", "海": "hǎi 与 hǎo 韵母不同（ai 与 ao），意思是海洋。", "考": "kǎo 与 hǎo 声母不同（k 与 h），意思是考试。", "老": "lǎo 与 hǎo 声母不同（l 与 h），意思是年纪大、陈旧。"}, "sentence_index": null, "correct_answer": "好"}, "level_3": {"options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”作应答，表示同意，符合语境。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”不能用来表示同意或应答。"}, {"text": "坏", "is_correct": false, "explanation": "语义：“坏”表示不好，与句中表示同意的语境相反。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”不作应答词，与“我们现在就走”也不搭配。"}], "explanations": {"好": "正确：“好”作应答，表示同意，符合语境。", "慢": "语义：“慢”不能用来表示同意或应答。", "坏": "语义：“坏”表示不好，与句中表示同意的语境相反。", "远": "搭配：“远”不作应答词，与“我们现在就走”也不搭配。"}, "sentence_index": 0, "correct_answer": "好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病好了，明天可以上班。", "explanation": "这里的“好”作结果补语，表示病愈，是另一个意思，不表示令人满意或赞同。"}, {"text": "好容易才找到这家店。", "explanation": "这里的“好容易”是固定说法，表示很不容易，不表示令人满意或赞同。"}, {"text": "他好久没回家了，我们都很想他。", "explanation": "这里的“好”表示“很久”，修饰时间，是另一个意思，不表示赞同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19967, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好", "is_correct": true, "explanation": "正确答案。hǎo（第三声）是“好”的读音。"}, {"text": "耗", "is_correct": false, "explanation": "hào（第四声）与 hǎo（第三声）声调不同，意思是消耗。"}, {"text": "豪", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，意思是豪迈、豪华。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 hǎo 声母不同（b 与 h），意思是宝贝。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo 与 hǎo 声母不同（p 与 h），意思是奔跑。"}], "explanations": {"好": "正确答案。hǎo（第三声）是“好”的读音。", "耗": "hào（第四声）与 hǎo（第三声）声调不同，意思是消耗。", "豪": "háo（第二声）与 hǎo（第三声）声调不同，意思是豪迈、豪华。", "宝": "bǎo 与 hǎo 声母不同（b 与 h），意思是宝贝。", "跑": "pǎo 与 hǎo 声母不同（p 与 h），意思是奔跑。"}, "sentence_index": null, "correct_answer": "好"}, "level_3": {"options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”作应答，表示同意，与“就这样”相合。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”指高度，不表示应答。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，不能用作应答。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”描述温度，不能用于应答，也不接“就这样”。"}], "explanations": {"好": "正确：“好”作应答，表示同意，与“就这样”相合。", "高": "语义：“高”指高度，不表示应答。", "重": "语义：“重”说分量，不能用作应答。", "冷": "搭配：“冷”描述温度，不能用于应答，也不接“就这样”。"}, "sentence_index": 6, "correct_answer": "好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜做好了，快来吃吧。", "explanation": "这里的“好”作结果补语，表示完成，是另一个意思，不表示令人满意或赞同。"}, {"text": "我们等了好几个小时，他才来。", "explanation": "这里的“好几”表示数量多，修饰数词，是另一个意思，不表示令人满意或赞同。"}, {"text": "这个字好写，你试试看。", "explanation": "这里的“好”表示容易，修饰动词，是另一个意思，不表示令人满意或赞同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法好很，我们试试吧。", "corrected_sentence": "这个办法很好，我们试试吧。", "error_description": "错误：“好很”。正确：“很好”。程度副词“很”作状语，须放在形容词“好”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们选了一个很好办法。", "corrected_sentence": "我们选了一个很好的办法。", "error_description": "错误：“很好办法”。“很好”修饰名词时，中间须加“的”，应说“很好的办法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
