INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指听到并理解别人说话的内容或含义。", "primary_collocate": null, "pronunciation": "tīng dǒng", "ipa": "tʰiŋ˥ tʊŋ˨˩", "syllable_count": 2, "sentences": [{"text": "它们能听懂话，也能做事情。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "老师说得很慢，我听懂了。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能听懂中文吗？", "target_word": "听懂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说的话我一句也没听懂。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请再说一遍，我没听懂。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看电影的时候，你听懂了多少？", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他听懂了问题，马上回答了。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话里声音太小，我没有听懂。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗好像听懂了我的话。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "慢慢听，你一定能听懂。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "听懂了", "label": "体标"}, {"form": "没听懂", "label": "否定"}, {"form": "听得懂", "label": "可能补语"}, {"form": "聽懂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "听到别人的话并理解其意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477f6bce-3da5-4648-b3b5-63365f3456a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听懂", "is_correct": true, "explanation": "正确。「听懂」指听到并理解话的内容，与后半句「也能做事情」相配，说明它们能理解人话。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」只带衣服、鞋袜等对象，不能带「话」作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」是不及物动词，后面不能带宾语「话」。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」的对象是具体的物体，不能带「话」作宾语。"}], "explanations": {"听懂": "正确。「听懂」指听到并理解话的内容，与后半句「也能做事情」相配，说明它们能理解人话。", "穿": "搭配：「穿」只带衣服、鞋袜等对象，不能带「话」作宾语。", "睡": "配价：「睡」是不及物动词，后面不能带宾语「话」。", "洗": "搭配：「洗」的对象是具体的物体，不能带「话」作宾语。"}, "sentence_index": 0, "correct_answer": "听懂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在操场上，听懂了远处飞机的轰鸣声。", "explanation": "这里应该用〈听到〉。轰鸣声没有可以理解的内容，只能说「听到」，不能说「听懂」。"}, {"text": "我终于听懂了这张地图。", "explanation": "这里应该用〈看懂〉。「听懂」用于听到的话语，看地图、看文字要用「看懂」。"}, {"text": "这道汤味道太淡，我一尝就听懂了。", "explanation": "这里应该用〈尝出〉。「听懂」只用于听到的话语，味道要用「尝出」来表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听懂", "is_correct": true, "explanation": "正确。后半句「马上回答了」说明他先理解了问题，「听懂」与之相合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」与「马上回答了」矛盾，忘了问题就不能立刻作答。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：「忽略」表示没有理会，与「马上回答了」的情形不合。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：「打碎」的对象是器物，不能用来搭配「问题」作宾语。"}], "explanations": {"听懂": "正确。后半句「马上回答了」说明他先理解了问题，「听懂」与之相合。", "忘记": "语义：「忘记」与「马上回答了」矛盾，忘了问题就不能立刻作答。", "忽略": "语义：「忽略」表示没有理会，与「马上回答了」的情形不合。", "打碎": "搭配：「打碎」的对象是器物，不能用来搭配「问题」作宾语。"}, "sentence_index": 6, "correct_answer": "听懂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一眼就听懂了他的背影。", "explanation": "这里应该用〈认出〉。「听懂」指理解话语，认出人要用「认出」，背影不能用「听懂」。"}, {"text": "我站得远，终于听懂了黑板上的字。", "explanation": "这里应该用〈看清〉。「听懂」用于听到的话语，看黑板上的字要用「看清」。"}, {"text": "这幅画的颜色，我全都听懂了。", "explanation": "这里应该用〈欣赏〉。「听懂」的对象是话语的内容，颜色要用「看」或「欣赏」来表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师讲的内容，我全都听懂了了。", "corrected_sentence": "老师讲的内容，我全都听懂了。", "error_description": "了字重复：动态助词「了」只用一次，放在复合动词「听懂」之后。错误形式是「听懂了了」，正确形式是「听懂了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上周的录音，她不听懂重点。", "corrected_sentence": "上周的录音，她没听懂重点。", "error_description": "错误形式：「不听懂」。正确形式：「没听懂」。已经发生的事情的否定要用「没」，「不」多用于习惯或意愿，不能用于「上周」这样的过去时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
