INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管好指对人或事物进行管理、照料，使其保持良好状态或遵守规则。", "primary_collocate": null, "pronunciation": "guǎn hǎo", "ipa": "kwan˨˩˦ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小明很高兴，因为他可以自己管好机器人。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "你要管好自己的东西，别弄丢了。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家管好自己的手机。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我管好弟弟，别让他乱跑。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱管好了，一个月只花一千块。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把这家小店管好了，客人越来越多。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，大人要管好他们，别让他们玩火。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想管好这个班，每天都早来。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要管好自己的时间，才能做完作业。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门时请管好你的小狗。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管好了", "label": "体标"}, {"form": "管不好", "label": "可能补语"}, {"form": "管得好", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "管理、照料人或事物，使其保持良好状态或守规矩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd050e39d-2ea0-4db5-ae84-c11939194167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管好", "is_correct": true, "explanation": "管好（guǎn hǎo）指管理照看，使人或事物保持良好状态。"}, {"text": "关好", "is_correct": false, "explanation": "关（guān，第一声）与 guǎn 声调不同，关好意思是关妥当。"}, {"text": "灌好", "is_correct": false, "explanation": "灌（guàn，第四声）与 guǎn 声调不同，灌好意思是灌满。"}, {"text": "干好", "is_correct": false, "explanation": "干（gàn，第四声）去掉了 u 音且声调不同，干好意思是做好。"}], "explanations": {"管好": "管好（guǎn hǎo）指管理照看，使人或事物保持良好状态。", "关好": "关（guān，第一声）与 guǎn 声调不同，关好意思是关妥当。", "灌好": "灌（guàn，第四声）与 guǎn 声调不同，灌好意思是灌满。", "干好": "干（gàn，第四声）去掉了 u 音且声调不同，干好意思是做好。"}, "sentence_index": null, "correct_answer": "管好"}, "level_3": {"options": [{"text": "管好", "is_correct": true, "explanation": "正确：原句为“他可以自己管好机器人”，空格应填“管好”。"}, {"text": "问候", "is_correct": false, "explanation": "搭配：“问候”用于对人表示关心，不能用于机器人。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：机器人不能被“吃掉”，此处意思不通。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”用于动物等生物，机器人不需要喂养。"}], "explanations": {"管好": "正确：原句为“他可以自己管好机器人”，空格应填“管好”。", "问候": "搭配：“问候”用于对人表示关心，不能用于机器人。", "吃掉": "语义：机器人不能被“吃掉”，此处意思不通。", "喂养": "语义：“喂养”用于动物等生物，机器人不需要喂养。"}, "sentence_index": 0, "correct_answer": "管好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就管好了这门外语。", "explanation": "这里应该用〈掌握〉。管好指管理照看，学习语言或技能要用掌握。"}, {"text": "我们明天要管好准备，不能迟到。", "explanation": "这里应该用〈做好〉。管好表示管理照看，准备工作要说做好。"}, {"text": "他把这首歌管好了，很快就会唱了。", "explanation": "这里应该用〈记住〉。管好不表示记忆，记住一首歌要说记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管好", "is_correct": true, "explanation": "正确：原句为“大人要管好他们，别让他们玩火”，空格应填“管好”。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：人不能被“冷冻”，此处意思不通。"}, {"text": "打包", "is_correct": false, "explanation": "语义：“打包”用于包装物品，不用于照看孩子。"}, {"text": "摆放", "is_correct": false, "explanation": "搭配：“摆放”用于物品，不说“摆放孩子”。"}], "explanations": {"管好": "正确：原句为“大人要管好他们，别让他们玩火”，空格应填“管好”。", "冷冻": "语义：人不能被“冷冻”，此处意思不通。", "打包": "语义：“打包”用于包装物品，不用于照看孩子。", "摆放": "搭配：“摆放”用于物品，不说“摆放孩子”。"}, "sentence_index": 6, "correct_answer": "管好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有管好那道数学题。", "explanation": "这里应该用〈做对〉。管好表示管理照看，解题要说做对。"}, {"text": "他管好了一杯牛奶，就去上学了。", "explanation": "这里应该用〈喝完〉。管好表示管理照看，喝牛奶要说喝完。"}, {"text": "他终于管好了那段话。", "explanation": "这里应该用〈听懂〉。管好不表示理解，理解一段话要说听懂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把家里的钱都管好了了。", "corrected_sentence": "他把家里的钱都管好了。", "error_description": "体标错误：“管好了”后面已有“了”，句末不能再加一个“了”，应说“管好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一定会很管好这些学生。", "corrected_sentence": "我一定会管好这些学生。", "error_description": "副词位置错误：“很”不能直接修饰动词“管好”，“很”后面要接形容词，应去掉“很”，说“我一定会管好这些学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
