INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协助他人完成工作的人。", "primary_collocate": null, "pronunciation": "zhù shǒu", "ipa": "ʈʂu˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "很多人开始请个人助手来帮助学习、工作和生活。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "也许以后每个家庭都会雇一个家务助手。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的助手正在准备药品。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我需要一个助手帮我整理文件。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是教授最好的助手。", "target_word": "助手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板请了一位新助手来管账。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位助手每天帮经理安排会议。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里有两个助手，都很努力。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做了三年校长的助手，很熟悉学校。", "target_word": "助手", "complexity_tier": "T3", "furigana": "tā zuò le sān nián xiàozhǎng de zhùshǒu, hěn shú xi xuéxiào.", "sentence_source": "generated"}, {"text": "没有助手，我一个人忙不过来。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个助手", "label": "量词"}, {"form": "小助手", "label": "复合"}], "register": "中性", "sense_fingerprint": "协助他人完成工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。"}, {"text": "祝寿", "is_correct": false, "explanation": "祝寿 zhùshòu 与助手的第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。"}, {"text": "煮熟", "is_correct": false, "explanation": "煮熟 zhǔshú 两个音节的声调都与助手不同，意思是把食物煮到可以吃。"}, {"text": "注水", "is_correct": false, "explanation": "注水 zhùshuǐ 第二个音节韵母不同（shuǐ 与 shǒu），意思是把水灌入。"}, {"text": "猪手", "is_correct": false, "explanation": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。", "祝寿": "祝寿 zhùshòu 与助手的第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。", "煮熟": "煮熟 zhǔshú 两个音节的声调都与助手不同，意思是把食物煮到可以吃。", "注水": "注水 zhùshuǐ 第二个音节韵母不同（shuǐ 与 shǒu），意思是把水灌入。", "猪手": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“个人助手”指帮人处理学习、工作和生活事务的人，符合句中语境。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能帮助学习、工作和生活，与“帮助”的语境冲突。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机的职责是开车，不能帮助人学习，与句中“学习”的语境不符。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“请”后接的应是能帮人做事的人，“房间”不能被请来帮助学习、工作和生活。"}], "explanations": {"助手": "正确答案。“个人助手”指帮人处理学习、工作和生活事务的人，符合句中语境。", "玩具": "语义：玩具不能帮助学习、工作和生活，与“帮助”的语境冲突。", "司机": "语义：司机的职责是开车，不能帮助人学习，与句中“学习”的语境不符。", "房间": "搭配：“请”后接的应是能帮人做事的人，“房间”不能被请来帮助学习、工作和生活。"}, "sentence_index": 0, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个软件是我写作时的好助手，能帮我检查错别字。", "explanation": "这里是〈助手〉的另一个意思，指起辅助作用的软件或工具，不指协助他人工作的人。定义中的〈助手〉指人，这里用来指物，用法不对。"}, {"text": "我的老板是我的助手，每天向我汇报工作。", "explanation": "助手指辅助别人的人，地位在被辅助者之下。这里把上级说成助手，用法不对，应该用〈下属〉或〈同事〉之类的词。"}, {"text": "医院里的助手负责主刀手术，医生只在一旁帮忙。", "explanation": "助手是协助主要人员的人。主刀手术的应是医生，这里把助手当成了主要操作者，角色用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。"}, {"text": "触手", "is_correct": false, "explanation": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是能够碰到的地方或章鱼的腕。"}, {"text": "出手", "is_correct": false, "explanation": "出手 chūshǒu 第一个音节声母不同（ch 与 zh），意思是卖出或动手。"}, {"text": "住宿", "is_correct": false, "explanation": "住宿 zhùsù 第二个音节的韵母和声调不同（sù 第四声，shǒu 第三声），意思是在某处住下来。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指协助他人完成工作的人。", "触手": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是能够碰到的地方或章鱼的腕。", "出手": "出手 chūshǒu 第一个音节声母不同（ch 与 zh），意思是卖出或动手。", "住宿": "住宿 zhùsù 第二个音节的韵母和声调不同（sù 第四声，shǒu 第三声），意思是在某处住下来。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“这位助手”指协助经理的人，能安排会议。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不负责安排会议，与句中“安排会议”的语境冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“这位”用于指人，不能指窗户，量词与名词搭配不当。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：出租车是交通工具，不能每天帮经理安排会议。"}], "explanations": {"助手": "正确答案。“这位助手”指协助经理的人，能安排会议。", "厨师": "语义：厨师负责做饭，不负责安排会议，与句中“安排会议”的语境冲突。", "窗户": "搭配：“这位”用于指人，不能指窗户，量词与名词搭配不当。", "出租车": "语义：出租车是交通工具，不能每天帮经理安排会议。"}, "sentence_index": 6, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在课堂上是老师的助手，负责给老师打分。", "explanation": "助手是协助别人完成工作的人，应辅助被帮助的一方，不能给对方打分。这里把学生说成老师的助手，还让他评判老师，角色用错了。"}, {"text": "这台收割机是农民最好的助手，帮他收割庄稼。", "explanation": "这里是〈助手〉的另一个意思，指起帮助作用的机器，不指协助他人工作的人。定义中的〈助手〉指人，这里用来指物。"}, {"text": "这家公司的老板是助手，每天负责发工资。", "explanation": "助手不能处于老板的位置。这里把决策者说成助手，与助手的身份不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找了一张助手帮我看店。", "corrected_sentence": "我找了一个助手帮我看店。", "error_description": "量词错误：“助手”指人，应用“个”或“位”，不能用“张”。“张”用于纸、桌子等扁平的东西，不能计量指人的助手。正确形式是“一个助手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她请了一把助手来帮她整理房间。", "corrected_sentence": "她请了一个助手来帮她整理房间。", "error_description": "量词用错了。“助手”指人，应用“个”或“位”，不能用“把”。“把”多用于有柄的器物，错误形式把“助手”当成了器物。正确形式是“一个助手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把新的事物、产品、政策等公开发布或开始实行。", "primary_collocate": null, "pronunciation": "tuī chū", "ipa": "tʰueɪ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "一些科技公司推出了开源的AI代理项目，让所有人都能查看和修改程序代码。", "target_word": "推出", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这家公司下个月要推出新手机。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店推出了一种新的蛋糕。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府推出了新政策，帮助老人。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家餐厅最近推出了便宜的午饭。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影公司明年要推出三部新电影。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校推出了网上学习的新办法。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个品牌每年都推出新衣服。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们推出过一个很有名的游戏。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行推出了新的手机服务，大家都很喜欢。", "target_word": "推出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推出了", "label": "体标"}, {"form": "推出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "公开发布新产品、新政策或新服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。"}, {"text": "退出", "is_correct": false, "explanation": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。"}, {"text": "突出", "is_correct": false, "explanation": "突出 tūchū 与推出只差一个音位（tū 与 tuī），意思是高于周围或显眼。"}, {"text": "脱出", "is_correct": false, "explanation": "脱出 tuōchū 第一个音节的韵母和声调都与 tuī 不同（tuō 第二声，tuī 第一声），意思是挣脱后从某处出来。"}], "explanations": {"推出": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。", "退出": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。", "突出": "突出 tūchū 与推出只差一个音位（tū 与 tuī），意思是高于周围或显眼。", "脱出": "脱出 tuōchū 第一个音节的韵母和声调都与 tuī 不同（tuō 第二声，tuī 第一声），意思是挣脱后从某处出来。"}, "sentence_index": null, "correct_answer": "推出"}, "level_3": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。“推出了开源的AI代理项目”指公开发布，与“让所有人都能查看和修改”的语境一致。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除是去掉某物，与句末“让所有人都能查看和修改”的公开语境相反。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏是不让别人看见，与“开源”和“让所有人都能查看”的语境冲突。"}, {"text": "关闭", "is_correct": false, "explanation": "搭配：“关闭”的对象若是开源项目，会让人无法查看和修改，与句末的公开语境相反。"}], "explanations": {"推出": "正确答案。“推出了开源的AI代理项目”指公开发布，与“让所有人都能查看和修改”的语境一致。", "删除": "语义：删除是去掉某物，与句末“让所有人都能查看和修改”的公开语境相反。", "隐藏": "语义：隐藏是不让别人看见，与“开源”和“让所有人都能查看”的语境冲突。", "关闭": "搭配：“关闭”的对象若是开源项目，会让人无法查看和修改，与句末的公开语境相反。"}, "sentence_index": 0, "correct_answer": "推出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师推出了一道很难的数学题。", "explanation": "这里应该用〈出〉。推出用于公开发布新产品或政策，不能用来指出题目。"}, {"text": "他用力把车推出了车库，因为车坏了。", "explanation": "这里是“推出”的另一个意思，表示用力使某物离开。它不表示公开发布新产品，这里的用法与“公开发布”的意思不符。"}, {"text": "会议上大家推出了很多反对意见。", "explanation": "这里应该用〈提出〉。提出用于意见、建议、问题；推出用于可供购买或使用的新产品和服务，不能用于意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。"}, {"text": "吹出", "is_correct": false, "explanation": "吹出 chuīchū 第一个音节声母不同（ch 与 t），意思是用力把气或东西吹出来。"}, {"text": "追出", "is_correct": false, "explanation": "追出 zhuīchū 第一个音节声母不同（zh 与 t），意思是追赶着跑到外面去。"}, {"text": "催出", "is_correct": false, "explanation": "催出 cuīchū 第一个音节声母不同（c 与 t），意思是促使某物显现出来。"}], "explanations": {"推出": "正确答案。推出 tuīchū，指把新的产品、政策等公开发布。", "吹出": "吹出 chuīchū 第一个音节声母不同（ch 与 t），意思是用力把气或东西吹出来。", "追出": "追出 zhuīchū 第一个音节声母不同（zh 与 t），意思是追赶着跑到外面去。", "催出": "催出 cuīchū 第一个音节声母不同（c 与 t），意思是促使某物显现出来。"}, "sentence_index": null, "correct_answer": "推出"}, "level_3": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。“推出了网上学习的新办法”指公开提出并开始实行，与“新办法”的语境一致。"}, {"text": "废除", "is_correct": false, "explanation": "语义：废除是取消既有的规定，与“新办法”的语境相反。"}, {"text": "停止", "is_correct": false, "explanation": "语义：停止是中断已经开始的事，与“推出新办法”的语境冲突。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记是记不住某事，不能用来表示学校把新办法公开实行。"}], "explanations": {"推出": "正确答案。“推出了网上学习的新办法”指公开提出并开始实行，与“新办法”的语境一致。", "废除": "语义：废除是取消既有的规定，与“新办法”的语境相反。", "停止": "语义：停止是中断已经开始的事，与“推出新办法”的语境冲突。", "忘记": "语义：忘记是记不住某事，不能用来表示学校把新办法公开实行。"}, "sentence_index": 6, "correct_answer": "推出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我推出这本书给你，你一定要看。", "explanation": "这里应该用〈推荐〉。推荐指把好的东西介绍给别人让人选用；推出是公开发布新产品或服务，不能用来对个人介绍书籍。"}, {"text": "老师把那个学生推出了教室，让他站在外面。", "explanation": "这里是“推出”的另一个意思，表示用力使人离开某处。它不表示公开发布，这里的用法与句意不符。"}, {"text": "店员把旧衣服推出给顾客，说是新款。", "explanation": "这里应该用〈推销〉。推销是主动向顾客介绍并卖出商品；推出是公开发布新商品，不能用来指向顾客卖旧货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司去年推出了过一款新游戏。", "corrected_sentence": "这家公司去年推出过一款新游戏。", "error_description": "体标叠加错误：「推出」后已用「过」表示曾经做过，不能再加「了」。错误形式是「推出了过」，正确形式是「推出过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店今年推出出了一套新书。", "corrected_sentence": "这家书店今年推出了一套新书。", "error_description": "重复错误：「推出」之后多写了一个「出」，应为「推出了」，只需删去多余的「出」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
