INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了了解或检查而看，比如看消息、看资料。", "primary_collocate": null, "pronunciation": "chá kàn", "ipa": "ʈʂʰa˧˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "一些科技公司推出了开源的AI代理项目，意思是把程序代码公开，让所有人都能查看和修改。", "target_word": "查看", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请你查看一下今天的邮件。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生查看了他的检查结果。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，我查看了天气。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以在手机上查看快递消息。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师正在查看大家的作业。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他查看过这份资料，没有发现问题。", "target_word": "查看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人可以在网站上查看房间的价格。", "target_word": "查看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察查看了周围的情况。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想查看一下银行的账单。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "查看了", "label": "体标"}, {"form": "查看过", "label": "体标"}], "register": "中性", "sense_fingerprint": "为了了解情况或检查内容而看消息、资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "查看", "is_correct": true, "explanation": "正确：让所有人为了检查而看代码，符合“公开”的语境。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝用于食物，代码不能品尝。"}, {"text": "聆听", "is_correct": false, "explanation": "语义：聆听用于声音、乐曲，代码不是用耳朵听的。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象一般是食物，不说“烹饪和修改”代码。"}], "explanations": {"查看": "正确：让所有人为了检查而看代码，符合“公开”的语境。", "品尝": "语义：品尝用于食物，代码不能品尝。", "聆听": "语义：聆听用于声音、乐曲，代码不是用耳朵听的。", "烹饪": "搭配：“烹饪”的对象一般是食物，不说“烹饪和修改”代码。"}, "sentence_index": 0, "correct_answer": "查看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他蹲在花丛旁，查看着花香。", "explanation": "这里应该用〈闻〉。花香要用鼻子闻，“查看”用于了解或检查消息、资料，不用于气味。"}, {"text": "我晚上在家查看了一场电影。", "explanation": "这里应该用〈观看〉。查看强调为了了解或检查；看电影要用观看。"}, {"text": "她站在窗前，查看着寒意。", "explanation": "这里应该用〈感受〉。寒意要用身体感受，“查看”用于了解或检查消息、资料，不用于感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "查看", "is_correct": true, "explanation": "正确：为了检查而看资料，符合“没有发现问题”的语境。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：资料不能演奏，演奏用于乐器或乐曲。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：“烘焙”的对象是面包、点心等食物，不说“烘焙资料”。"}, {"text": "哄", "is_correct": false, "explanation": "搭配：“哄”的对象一般是人或孩子，资料不能被哄。"}], "explanations": {"查看": "正确：为了检查而看资料，符合“没有发现问题”的语境。", "演奏": "语义：资料不能演奏，演奏用于乐器或乐曲。", "烘焙": "搭配：“烘焙”的对象是面包、点心等食物，不说“烘焙资料”。", "哄": "搭配：“哄”的对象一般是人或孩子，资料不能被哄。"}, "sentence_index": 6, "correct_answer": "查看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他咬牙查看着剧烈的疼痛。", "explanation": "这里应该用〈忍受〉。疼痛要靠身体承受，“查看”用于了解或检查消息、资料，不能用于感受痛苦。"}, {"text": "我们晚上查看了一场音乐会。", "explanation": "这里应该用〈聆听〉。音乐会要用耳朵听，“查看”用于了解或检查消息、资料。"}, {"text": "他小口查看着咖啡的苦味。", "explanation": "这里应该用〈品尝〉。苦味要靠舌头品尝，“查看”指了解或检查消息、资料，不用于味觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想查看看一下这份合同。", "corrected_sentence": "我想查看一下这份合同。", "error_description": "重复错误：「查看」之后多写了一个「看」，应说「查看一下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经查看了过这份报告。", "corrected_sentence": "我已经查看过这份报告。", "error_description": "体标叠加错误：「查看了过」把完成和经历两个体标用在一起。表示曾经做过用「查看过」，不加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
