INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19979, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行程指旅行或出行的路线、日程安排。", "primary_collocate": null, "pronunciation": "xíng chéng", "ipa": "ɕiŋ˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比如，你可以让它整理邮件、安排行程，甚至分析数据。", "target_word": "行程", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "明天的行程很满，我没有时间休息。", "target_word": "行程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把行程发给我，我来订酒店。", "target_word": "行程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的行程是五天四夜。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导游给我们讲了今天的行程。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的行程太紧，没有时间吃饭。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为下雨，我们改了行程。", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板这个星期的行程已经排好了。", "target_word": "行程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我去北京的行程吗？", "target_word": "行程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发前我们把行程又确认了一遍。", "target_word": "行程", "complexity_tier": "T3", "furigana": "chū fā qián wǒ men bǎ xíng chéng yòu quèrèn le yí biàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个行程", "label": "量词"}, {"form": "行程表", "label": "复合"}], "register": "通用", "sense_fingerprint": "旅行或出差的路线与日程安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9ed81-ee57-4f6d-9b76-d0a5321a3745') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "搭配：“安排”的对象应是活动或事务，不能安排“天空”。"}, {"text": "行程", "is_correct": true, "explanation": "正确。行程指出行的路线和日程安排，可以被整理、安排。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“安排”不能和“心跳”搭配，心跳是身体自然的节律。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量指人的食量，程序不吃饭，也不能安排食量。"}], "explanations": {"天空": "搭配：“安排”的对象应是活动或事务，不能安排“天空”。", "行程": "正确。行程指出行的路线和日程安排，可以被整理、安排。", "心跳": "搭配：“安排”不能和“心跳”搭配，心跳是身体自然的节律。", "饭量": "语义：饭量指人的食量，程序不吃饭，也不能安排食量。"}, "sentence_index": 0, "correct_answer": "行程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的行程很高，比我还高两厘米。", "explanation": "这里应该用〈身高〉。行程指出行的安排，不能用来说人的高矮。"}, {"text": "这次旅行带了一件行程。", "explanation": "这里应该用〈行李〉。行程是安排，不是可以带的东西，带的应是行李。"}, {"text": "这部电影的行程是两个小时。", "explanation": "这里应该用〈时长〉。行程用于旅行安排，电影的长短要用时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能由人“改”，这里说“我们改了天气”，与句意不符。"}, {"text": "行程", "is_correct": true, "explanation": "正确。因为下雨而调整出行安排，改的正是行程。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是天生的，不能被“改”，与“改”的搭配不成立。"}, {"text": "地球", "is_correct": false, "explanation": "搭配：“改”可搭配计划、路线，不能搭配“地球”。"}], "explanations": {"天气": "语义：天气不能由人“改”，这里说“我们改了天气”，与句意不符。", "行程": "正确。因为下雨而调整出行安排，改的正是行程。", "身高": "体貌：身高是天生的，不能被“改”，与“改”的搭配不成立。", "地球": "搭配：“改”可搭配计划、路线，不能搭配“地球”。"}, "sentence_index": 6, "correct_answer": "行程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱货的行程是三百斤。", "explanation": "这里应该用〈重量〉。行程指出行的路线或安排，货物的重量要用重量或斤数来说。"}, {"text": "他的行程考了九十分，比上次高了。", "explanation": "这里应该用〈成绩〉。行程指出行的路线或安排，考试的分数要用成绩。"}, {"text": "这件衣服的行程是三十块钱。", "explanation": "这里应该用〈价格〉。行程指出行的路线或安排，衣服的价钱要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今天有一篇行程。", "corrected_sentence": "我们今天有一个行程。", "error_description": "量词错误：表示日程安排的“行程”用量词“个”，“篇”用于文章、文件，不能用于行程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的行程安排地很满。", "corrected_sentence": "他的行程安排得很满。", "error_description": "补语标志错误：“安排得很满”中的补语要用“得”连接，“地”用在动词前作状语，不能用在“很满”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
