INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一般的使用者，没有特殊权限或专业背景的普通人群。", "primary_collocate": null, "pronunciation": "pǔ tōng yòng hù", "ipa": "pʰu˨˩˦ tʰʊŋ˥ jʊŋ˥˩ xu˥˩", "syllable_count": 4, "sentences": [{"text": "因为它对所有人开放，研究人员、开发者和普通用户都可以测试它、提出建议或增加新功能。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "普通用户不能删除别人的文件。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件对普通用户是免费的。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只是普通用户，不懂电脑里面的设置。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理员可以改设置，普通用户只能看。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机很便宜，适合普通用户。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对普通用户来说，这个网站太复杂了。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想听听普通用户的看法。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普通用户每天最多可以下载三个文件。", "target_word": "普通用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多普通用户不会用这个功能。", "target_word": "普通用户", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位普通用户", "label": "量词"}, {"form": "一个普通用户", "label": "量词"}], "register": "通用", "sense_fingerprint": "没有特殊权限或专业背景的一般使用者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9ed81-ee57-4f6d-9b76-d0a5321a3745') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通用户", "is_correct": true, "explanation": "正确。与前面的「研究人员、开发者」并列，指没有特殊权限、可以测试软件并提出建议的一般使用者。"}, {"text": "软件", "is_correct": false, "explanation": "语义：「软件」是物件，不能与「研究人员、开发者」并列，作测试和提建议的主体。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：「说明书」不能测试软件或提出建议，与并列的人员不属同类。"}, {"text": "服务器", "is_correct": false, "explanation": "配价：「测试它、提出建议」要求施事是人，「服务器」不能充当施事。"}], "explanations": {"普通用户": "正确。与前面的「研究人员、开发者」并列，指没有特殊权限、可以测试软件并提出建议的一般使用者。", "软件": "语义：「软件」是物件，不能与「研究人员、开发者」并列，作测试和提建议的主体。", "说明书": "语义：「说明书」不能测试软件或提出建议，与并列的人员不属同类。", "服务器": "配价：「测试它、提出建议」要求施事是人，「服务器」不能充当施事。"}, "sentence_index": 0, "correct_answer": "普通用户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班里的普通用户都考了满分。", "explanation": "这里应该用〈学生〉。「普通用户」指使用软件或服务的人，班里的人要说学生。"}, {"text": "这条马路上的普通用户很少。", "explanation": "这里应该用〈行人〉。「普通用户」指使用软件或服务的人，走在路上的人要说行人。"}, {"text": "这家医院的普通用户都在看病。", "explanation": "这里应该用〈病人〉。「普通用户」指使用软件或服务的人，在医院看病的人要说病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通用户", "is_correct": true, "explanation": "正确。「对……来说」引出感到网站复杂的人，「普通用户」指没有特殊权限的一般使用者，符合此语境。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有感受，不能觉得这个网站「太复杂了」。"}, {"text": "汉语", "is_correct": false, "explanation": "配价：「对……来说」引出的是感受者，「汉语」不能充当感受者。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感觉，无法判断网站复杂与否。"}], "explanations": {"普通用户": "正确。「对……来说」引出感到网站复杂的人，「普通用户」指没有特殊权限的一般使用者，符合此语境。", "电脑": "语义：电脑没有感受，不能觉得这个网站「太复杂了」。", "汉语": "配价：「对……来说」引出的是感受者，「汉语」不能充当感受者。", "石头": "语义：石头没有感觉，无法判断网站复杂与否。"}, "sentence_index": 6, "correct_answer": "普通用户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是普通用户，所以能修改所有系统设置。", "explanation": "这里应该用〈管理员〉。普通用户没有特殊权限，不能修改系统设置；「能修改所有设置」是管理员的权限。"}, {"text": "这部电影的普通用户很多。", "explanation": "这里应该用〈观众〉。普通用户指使用软件、网站等服务的人，看电影的人要说观众。"}, {"text": "那位普通用户是这家公司的董事长。", "explanation": "这里应该用〈管理层〉。普通用户指没有特殊职务或权限的使用者，不指担任公司高层职务的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司里有三台普通用户参加了测试。", "corrected_sentence": "公司里有三位普通用户参加了测试。", "error_description": "「普通用户」指人，计量词应用「位」或「个」，不能用「台」（「台」用于机器、设备）。应说「三位普通用户」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款软件的普通用户们很多。", "corrected_sentence": "这款软件的普通用户很多。", "error_description": "「很多」已表示数量，「普通用户」后面不能再加「们」。应说「这款软件的普通用户很多」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
