INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了检查事物的性能、质量或能力等而进行尝试。", "primary_collocate": null, "pronunciation": "cè shì", "ipa": "tsʰɤ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这批零件在装配之前，都要先测试一遍，以确认质量合格。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为它对所有人开放，研究人员、开发者和普通用户都可以测试它、提出建议或增加新功能。", "target_word": "测试", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工程师正在测试新手机的电池能用多久。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想测试一下学生的听力水平。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车上市以前，必须先测试它的安全性。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们测试了这个软件的运行速度。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请用户来测试新游戏有没有问题。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用仪器测试病人的视力。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们测试过三种方法，只有这一种有用。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器还没有测试，不能马上使用。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "测试了", "label": "完成体"}, {"form": "测试过", "label": "经历体"}, {"form": "测试测试", "label": "重叠"}, {"form": "测试员", "label": "复合"}, {"form": "測試", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为检查性能、质量或能力而进行试验（正式检测）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "测试", "is_correct": true, "explanation": "“测试”指为检查零件质量而进行试验，与“装配之前……确认质量合格”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是名词，不能作动词，句意不通。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”是饮料，不能用来检验零件，句意不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”是名词，不能作动词，与正式检验语境也不符。"}], "explanations": {"测试": "“测试”指为检查零件质量而进行试验，与“装配之前……确认质量合格”相符。", "天气": "语义：“天气”是名词，不能作动词，句意不通。", "咖啡": "语义：“咖啡”是饮料，不能用来检验零件，句意不通。", "玩意儿": "语义：“玩意儿”是名词，不能作动词，与正式检验语境也不符。"}, "sentence_index": 0, "correct_answer": "测试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用尺子测试房间的面积。", "explanation": "这里应该用〈测量〉。测试指检验物品的性能、质量或人的能力，量房间面积要用测量。"}, {"text": "记者测试了这件事的真相。", "explanation": "这里应该用〈调查〉。测试用于检验物品或能力，查明事情真相要用调查。"}, {"text": "科学家测试鸟类的迁徙。", "explanation": "这里应该用〈观察〉。观察指仔细看事物的变化，研究鸟类迁徙要用观察；测试指检验性能或能力，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "测试", "is_correct": true, "explanation": "“测试”指为检查新游戏的问题而进行试验，与“公司请用户来……有没有问题”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于检查游戏。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖给别人，与“请用户来检查问题”的意思不符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理，与检查游戏是否有问题无关。"}], "explanations": {"测试": "“测试”指为检查新游戏的问题而进行试验，与“公司请用户来……有没有问题”的语境相符。", "吃": "搭配：“吃”的对象是食物，不能用于检查游戏。", "出售": "语义：“出售”是卖给别人，与“请用户来检查问题”的意思不符。", "打扫": "语义：“打扫”指清理，与检查游戏是否有问题无关。"}, "sentence_index": 6, "correct_answer": "测试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家测试这次地震的损失。", "explanation": "这里应该用〈估计〉。估计指根据情况推断数量或程度，损失要用估计；测试指检验物品的性能或人的能力。"}, {"text": "卫星测试了火星的表面。", "explanation": "这里应该用〈探测〉。探测指勘察未知的地表或空间，火星表面要用探测；测试不用于勘察自然环境。"}, {"text": "我测试了她的笑容。", "explanation": "这里应该用〈感受〉。感受指身心的体会，笑容要用感受；测试不能用于体会感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器我们以前测试了过。", "corrected_sentence": "这台机器我们以前测试过。", "error_description": "“了”与“过”不能同用：“测试了过”同时用了完成体和经历体的标记。应说“测试过”，表示曾经做过测试。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑测试不得顺利。", "corrected_sentence": "这台电脑测试得不顺利。", "error_description": "补语位置用错：“得”应紧跟动词，说“测试得不顺利”。“不得”表示“不允许”，“测试不得顺利”意思不对，也不符合汉语语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，连接前后两个部分，表示因为前面说的原因或条件，所以有了后面的结果或变化。", "primary_collocate": null, "pronunciation": "zhè yàng yī lái", "ipa": "ʈʂɤ⁵¹ jɑŋ⁵¹ i⁵⁵ laɪ³⁵", "syllable_count": 4, "sentences": [{"text": "它每天都学习新知识，这样一来，它的能力可以不断变强。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早起跑步，这样一来，身体越来越好。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机放在家里了，这样一来，我联系不上他。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上在修路，这样一来，我们到得很晚。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷了，这样一来，很多人都感冒了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离家很近，这样一来，我可以走路上学。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每周见面一次，这样一来，大家都不会忘记对方。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先做完作业，这样一来，晚上就有时间玩儿了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了很多菜，这样一来，周末不用出门了。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师多给我们练习，这样一来，我们进步得很快。", "target_word": "这样一来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接前因与后果，引出由前面情况带来的结果或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9ed81-ee57-4f6d-9b76-d0a5321a3745') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这样一来", "is_correct": true, "explanation": "正确。表示由前面的情况引出的结果，「能力可以不断变强」是顺接的结果。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，与「能力不断变强」这一顺接结果不相反，不能引出此句。"}, {"text": "然而", "is_correct": false, "explanation": "语域：「然而」偏书面，且表示转折，此处是顺接的结果，不相符。"}, {"text": "否则", "is_correct": false, "explanation": "语义：「否则」表示不然的后果，与「能力不断变强」的正面结果相矛盾。"}], "explanations": {"这样一来": "正确。表示由前面的情况引出的结果，「能力可以不断变强」是顺接的结果。", "但是": "语义：「但是」表示转折，与「能力不断变强」这一顺接结果不相反，不能引出此句。", "然而": "语域：「然而」偏书面，且表示转折，此处是顺接的结果，不相符。", "否则": "语义：「否则」表示不然的后果，与「能力不断变强」的正面结果相矛盾。"}, "sentence_index": 0, "correct_answer": "这样一来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样一来，我们先吃饭，再去看电影。", "explanation": "这里应该用〈然后〉。「这样一来」表示由前面原因导致的结果，这里说的是先后顺序，不表示因果，应用〈然后〉。"}, {"text": "他会说英语，这样一来，他还会弹钢琴。", "explanation": "这里应该用〈另外〉。「这样一来」表示由前面原因导致的结果，两件事没有因果关系，只是补充。"}, {"text": "我很想去，这样一来，没有时间。", "explanation": "这里应该用〈但是〉。「这样一来」表示顺接的结果，不表示转折，「想去」与「没有时间」是对立关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这样一来", "is_correct": true, "explanation": "正确。表示「我们每周见面」带来的结果：大家都不会忘记对方。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：「虽然」要与「但是」等配对，单独用在这里，句子不完整。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：「尽管」要与「仍然」「却」等配对，此处缺少后一分句的配合词，句子不通。"}, {"text": "反之", "is_correct": false, "explanation": "语域：「反之」是书面语，表示相反的情况，与这句口语化的叙述不协调，也与前句的结果相悖。"}], "explanations": {"这样一来": "正确。表示「我们每周见面」带来的结果：大家都不会忘记对方。", "虽然": "搭配：「虽然」要与「但是」等配对，单独用在这里，句子不完整。", "尽管": "搭配：「尽管」要与「仍然」「却」等配对，此处缺少后一分句的配合词，句子不通。", "反之": "语域：「反之」是书面语，表示相反的情况，与这句口语化的叙述不协调，也与前句的结果相悖。"}, "sentence_index": 6, "correct_answer": "这样一来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有复习，这样一来，他还是考得很好。", "explanation": "这里应该用〈尽管如此〉。「这样一来」表示顺接的结果，不表示让步，「没复习还考好」应用〈尽管如此〉引出转折。"}, {"text": "这样一来，你不来，我就去。", "explanation": "这里应该用〈如果〉。「这样一来」表示结果，不表示假设条件，「你不来」是假设，应用〈如果〉。"}, {"text": "这个问题很难，这样一来，他很快就解出来了。", "explanation": "这里应该用〈相反〉。前后是对立关系，「这样一来」表示的因果关系不成立，应用〈相反〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天打扫，这样一来了，房间就干净多了。", "corrected_sentence": "我每天打扫，这样一来，房间就干净多了。", "error_description": "「这样一来」是固定的连词，后面不能加「了」。应去掉「了」，说「这样一来，房间就干净多了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把钱存起来，明年这样一来就能买车了。", "corrected_sentence": "我把钱存起来，这样一来就能买车了。", "error_description": "「明年」插在「这样一来」之前，使「这样一来」不再紧接原因分句。应删去「明年」，说「我把钱存起来，这样一来就能买车了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变弱", "is_correct": true, "explanation": "正确：“变弱”与“变强”互为反义，指能力减弱，与本句的语境相对。"}, {"text": "睡觉", "is_correct": false, "explanation": "不构成反义：“睡觉”与“变强”没有对立关系，只是不相关的动词。"}, {"text": "旅行", "is_correct": false, "explanation": "不构成反义：“旅行”与“变强”没有对立关系，只是不相关的动词。"}, {"text": "唱歌", "is_correct": false, "explanation": "不构成反义：“唱歌”与“变强”没有对立关系，只是不相关的动词。"}], "correct_answer": "变弱", "explanations": {"变弱": "正确：“变弱”与“变强”互为反义，指能力减弱，与本句的语境相对。", "睡觉": "不构成反义：“睡觉”与“变强”没有对立关系，只是不相关的动词。", "旅行": "不构成反义：“旅行”与“变强”没有对立关系，只是不相关的动词。", "唱歌": "不构成反义：“唱歌”与“变强”没有对立关系，只是不相关的动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变弱", "is_correct": true, "explanation": "正确：“变弱”与“变强”互为反义，指能力减弱，与本句的语境相对。"}, {"text": "跑步", "is_correct": false, "explanation": "不构成反义：“跑步”与“变强”没有对立关系，只是不相关的动词。"}, {"text": "读书", "is_correct": false, "explanation": "不构成反义：“读书”与“变强”没有对立关系，只是不相关的动词。"}, {"text": "做饭", "is_correct": false, "explanation": "不构成反义：“做饭”与“变强”没有对立关系，只是不相关的动词。"}], "correct_answer": "变弱", "explanations": {"变弱": "正确：“变弱”与“变强”互为反义，指能力减弱，与本句的语境相对。", "跑步": "不构成反义：“跑步”与“变强”没有对立关系，只是不相关的动词。", "读书": "不构成反义：“读书”与“变强”没有对立关系，只是不相关的动词。", "做饭": "不构成反义：“做饭”与“变强”没有对立关系，只是不相关的动词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指通过努力或经历，使自己的能力、技能或状态得到提升，变得更好。", "primary_collocate": null, "pronunciation": "biàn qiáng", "ipa": "pjɛn⁵¹ tɕʰjɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这样一来，它的能力可以不断变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他每天练习，一年后变强了很多。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想通过学习变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经历了这次失败，他变强了。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要努力，你也会慢慢变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想变强，这样才能保护家人。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队伍这几年一直在变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕困难，所以很快就变强了。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要多读书，才能变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会新方法以后，我们变强了。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变强了", "label": "体标：了"}, {"form": "变强过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "通过努力或经历让自己的能力、技能提升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9ed81-ee57-4f6d-9b76-d0a5321a3745') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：变强（biàn qiáng），指能力、实力变得更强。"}, {"text": "变迁", "is_correct": false, "explanation": "qiān（第一声）与 qiáng（第二声）韵母不同（an 与 ang），声调也不同；变迁指事物的演变，不是能力变强。"}, {"text": "变穷", "is_correct": false, "explanation": "qióng 与 qiáng 声调相同，韵母不同（ong 与 ang）；变穷意思是变得贫穷。"}, {"text": "变清", "is_correct": false, "explanation": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变清意思是变得清澈。"}], "explanations": {"变强": "正确：变强（biàn qiáng），指能力、实力变得更强。", "变迁": "qiān（第一声）与 qiáng（第二声）韵母不同（an 与 ang），声调也不同；变迁指事物的演变，不是能力变强。", "变穷": "qióng 与 qiáng 声调相同，韵母不同（ong 与 ang）；变穷意思是变得贫穷。", "变清": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变清意思是变得清澈。"}, "sentence_index": null, "correct_answer": "变强"}, "level_3": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：“变强”指能力不断提升，与“它的能力可以不断”搭配，符合句意。"}, {"text": "变长", "is_correct": false, "explanation": "搭配：“变长”说长度，不能用来形容能力。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：“变轻”指重量减少，与能力的提升方向不合，句意说不通。"}, {"text": "变胖", "is_correct": false, "explanation": "语义：“变胖”指身体变胖，能力不能变胖，句意说不通。"}], "explanations": {"变强": "正确：“变强”指能力不断提升，与“它的能力可以不断”搭配，符合句意。", "变长": "搭配：“变长”说长度，不能用来形容能力。", "变轻": "语义：“变轻”指重量减少，与能力的提升方向不合，句意说不通。", "变胖": "语义：“变胖”指身体变胖，能力不能变胖，句意说不通。"}, "sentence_index": 0, "correct_answer": "变强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月公司的员工人数变强了，比去年多了三十个人。", "explanation": "这里应该用〈增加〉。变强只说人或团体的能力、本领变强，人数等数量要用增加。"}, {"text": "这次改革后，工厂的产品质量变强了。", "explanation": "这里应该用〈提高〉。变强描述能力、本领变强，产品质量这类要用提高。"}, {"text": "这几天的天气变强了，我们出去玩吧。", "explanation": "这里不能用变强。变强指人或团队的能力变强，天气的变化要说变好或转晴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：变强（biàn qiáng），指能力、实力变得更强。"}, {"text": "变轻", "is_correct": false, "explanation": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变轻意思是变得轻。"}, {"text": "变晴", "is_correct": false, "explanation": "qíng（第二声）与 qiáng 声调相同，韵母不同（ing 与 ang）；变晴指天气转晴。"}, {"text": "变亲", "is_correct": false, "explanation": "qīn（第一声）与 qiáng 韵母不同（in 与 ang），声调也不同；变亲意思是变得亲近。"}], "explanations": {"变强": "正确：变强（biàn qiáng），指能力、实力变得更强。", "变轻": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变轻意思是变得轻。", "变晴": "qíng（第二声）与 qiáng 声调相同，韵母不同（ing 与 ang）；变晴指天气转晴。", "变亲": "qīn（第一声）与 qiáng 韵母不同（in 与 ang），声调也不同；变亲意思是变得亲近。"}, "sentence_index": null, "correct_answer": "变强"}, "level_3": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：“变强”指团队实力提升，与“这几年一直在”搭配，符合句意。"}, {"text": "变亮", "is_correct": false, "explanation": "语义：“亮”描写光线或颜色，队伍不能“变亮”，句意说不通。"}, {"text": "变深", "is_correct": false, "explanation": "搭配：“深”多用于颜色、程度或水，不用于形容队伍。"}, {"text": "变圆", "is_correct": false, "explanation": "体貌：“圆”描写形状或身材，不能用来说队伍变圆。"}], "explanations": {"变强": "正确：“变强”指团队实力提升，与“这几年一直在”搭配，符合句意。", "变亮": "语义：“亮”描写光线或颜色，队伍不能“变亮”，句意说不通。", "变深": "搭配：“深”多用于颜色、程度或水，不用于形容队伍。", "变圆": "体貌：“圆”描写形状或身材，不能用来说队伍变圆。"}, "sentence_index": 6, "correct_answer": "变强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学会新方法以后，我们的工作流程变强了。", "explanation": "这里应该用〈改进〉。变强用于人或团队的能力，工作流程、做法要用改进。"}, {"text": "学会新方法以后，学校的管理制度变强了。", "explanation": "这里应该用〈完善〉。变强指能力、实力变强，管理制度要用完善。"}, {"text": "学会新方法以后，这家店的营业额变强了。", "explanation": "这里应该用〈增长〉。变强不用于营业额这类数额，数额的增加要说增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的队伍今年变强着，赢了不少比赛。", "corrected_sentence": "我们的队伍今年变强了，赢了不少比赛。", "error_description": "错误在“着”。“变强”表示一个已完成的变化，应接“了”，不能接“着”（“着”表示状态的持续）。应改为“变强了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学会新方法以后，我们变强得不少。", "corrected_sentence": "学会新方法以后，我们变强了不少。", "error_description": "错误在“得”。表示变化后的程度应说“变强了不少”，“变强得不少”不地道。应改为“变强了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
