INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把内在的能力、特点或思想充分表现出来。", "primary_collocate": null, "pronunciation": "fā huī", "ipa": "fa˥ xwei˥", "syllable_count": 2, "sentences": [{"text": "虽然现在还有挑战，但很多专家认为，开源模式将在其中发挥重要作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他在比赛中发挥得很好。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家发挥自己的想象力。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员充分发挥了自己的才能。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李考试时没有发挥好。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让孩子们发挥创意。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队发挥出了真正的水平。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老板会让员工发挥长处。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的特点发挥得很充分。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要发挥自己的优势。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发挥了", "label": "完成体"}, {"form": "发挥着", "label": "持续体"}, {"form": "发挥过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "充分表现出自己的能力、特长、水平或想象力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7745670-384d-4266-b7e1-8f53799026db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发挥", "is_correct": true, "explanation": "正确答案：“发挥”与“重要作用”搭配，表示产生效果。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多用于能量、资源，“作用”不能被消耗，与“重要作用”搭配不当。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指拿回，与“开源模式将在其中……重要作用”的语义不合。"}, {"text": "扣除", "is_correct": false, "explanation": "语义：“扣除”指减去，“重要作用”不能被扣除，句子说不通。"}], "explanations": {"发挥": "正确答案：“发挥”与“重要作用”搭配，表示产生效果。", "消耗": "搭配：“消耗”多用于能量、资源，“作用”不能被消耗，与“重要作用”搭配不当。", "收回": "语义：“收回”指拿回，与“开源模式将在其中……重要作用”的语义不合。", "扣除": "语义：“扣除”指减去，“重要作用”不能被扣除，句子说不通。"}, "sentence_index": 0, "correct_answer": "发挥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爱迪生发挥了电灯。", "explanation": "这里应该用〈发明〉。“发挥”指充分表现已有的能力，表示创造出新事物要用“发明”。"}, {"text": "中国经济发挥得很快。", "explanation": "这里应该用〈发展〉。“发挥”指表现能力，描述经济、事业的进步要用“发展”。"}, {"text": "他把心里的不满发挥了出来。", "explanation": "这里应该用〈发泄〉。“发挥”指充分表现能力、特点，宣泄不满、情绪要用“发泄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发挥", "is_correct": true, "explanation": "正确答案：“发挥出”表示充分表现出来，与“真正的水平”相符。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”不能与“出了”组合表示展现，“真正的水平”也不会被浪费。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“真正的水平”应有的展现之义相反，句子说不通。"}, {"text": "耗尽", "is_correct": false, "explanation": "配价：“耗尽”不能带“水平”作宾语，也无法与“出了”搭配。"}], "explanations": {"发挥": "正确答案：“发挥出”表示充分表现出来，与“真正的水平”相符。", "浪费": "搭配：“浪费”不能与“出了”组合表示展现，“真正的水平”也不会被浪费。", "隐藏": "语义：“隐藏”与“真正的水平”应有的展现之义相反，句子说不通。", "耗尽": "配价：“耗尽”不能带“水平”作宾语，也无法与“出了”搭配。"}, "sentence_index": 6, "correct_answer": "发挥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你要发挥自己的缺点。", "explanation": "这里应该用〈克服〉。“发挥”只用于能力、优势等正面的东西，缺点要用“克服”。"}, {"text": "你要发挥自己的问题。", "explanation": "这里应该用〈解决〉。“发挥”用于能力、特长，问题要用“解决”。"}, {"text": "这件事让我发挥了很大的压力。", "explanation": "这里应该用〈承受〉。“发挥”用于能力、才能，压力要用“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她今天状态好，把发挥得很出色。", "corrected_sentence": "她今天状态好，发挥得很出色。", "error_description": "错误在「把」：「把」字句要有处置对象，「把发挥得」缺少宾语，应去掉「把」，说「发挥得很出色」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我要充分发挥了自己的优势。", "corrected_sentence": "我要充分发挥自己的优势。", "error_description": "错误在“了”：“要”表示意愿或将来，句中已有“要”，不能再加“了”，应说“我要充分发挥自己的优势”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共同相处，彼此在一起生活或工作。", "primary_collocate": null, "pronunciation": "gòng chǔ", "ipa": "kʊŋ˥˩ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这不仅改变了技术的发展方式，也可能改变我们与AI共处的方式。", "target_word": "共处", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我们要学会和不同的人共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人和自然应该和平共处。", "target_word": "共处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在一个小房子里共处了三年。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "室友之间要互相帮助，才能好好共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子和祖父母共处得很愉快。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里新人和老同事共处得很好。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我跟他共处过一段时间，知道他很细心。", "target_word": "共处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家希望能长期和平共处。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和同学共处时，要尊重对方的习惯。", "target_word": "共处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "和平共处", "label": "复合"}, {"form": "共处过", "label": "体标"}], "register": "中性", "sense_fingerprint": "共处·人与人或人与事物彼此相处、共同生活工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共处", "is_correct": true, "explanation": "共处：指人与人或人与事物长期相互相处，与“与AI……的方式”搭配自然。"}, {"text": "施肥", "is_correct": false, "explanation": "语义：施肥是给植物或土地加肥料，AI不能被施肥，句子不通。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指烤面包、饼干等食物，不能用来描述人与AI的关系。"}, {"text": "装订", "is_correct": false, "explanation": "配价：装订的对象是纸张、书本等，不能说“与AI装订”。"}], "explanations": {"共处": "共处：指人与人或人与事物长期相互相处，与“与AI……的方式”搭配自然。", "施肥": "语义：施肥是给植物或土地加肥料，AI不能被施肥，句子不通。", "烘焙": "语义：烘焙指烤面包、饼干等食物，不能用来描述人与AI的关系。", "装订": "配价：装订的对象是纸张、书本等，不能说“与AI装订”。"}, "sentence_index": 0, "correct_answer": "共处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站共处，聊了很久。", "explanation": "这里应该用〈相遇〉。共处强调长时间一起生活或工作，偶然碰面聊天要用相遇。"}, {"text": "两国军队在边境共处了三天，谁也不肯退让。", "explanation": "这里应该用〈对峙〉。共处表示和睦地待在一起，双方相持不下时要用对峙。"}, {"text": "两家企业共处了五年，抢了无数客户。", "explanation": "这里应该用〈竞争〉。共处表示和睦地相处，互相争抢客户要说竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共处", "is_correct": true, "explanation": "共处：“共处得很好”指人与人在一起相处融洽，符合句意。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵指面团、食物的变化过程，不能用来描述人际关系。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：砍伐指砍树木，不能用来形容人与人的关系。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：登记指办理手续，不能说“新人和老同事登记得很好”。"}], "explanations": {"共处": "共处：“共处得很好”指人与人在一起相处融洽，符合句意。", "发酵": "语义：发酵指面团、食物的变化过程，不能用来描述人际关系。", "砍伐": "语义：砍伐指砍树木，不能用来形容人与人的关系。", "登记": "搭配：登记指办理手续，不能说“新人和老同事登记得很好”。"}, "sentence_index": 6, "correct_answer": "共处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们共处了一段路，然后各自回家。", "explanation": "这里应该用〈同行〉。共处强调长时间在一起生活或工作，只一起走一段路要说同行。"}, {"text": "两家公司为了市场共处得很激烈。", "explanation": "这里应该用〈争夺〉。共处表示和睦地相处，不能用来形容为抢占市场的激烈竞争。"}, {"text": "他一个人共处了三年，从不和别人来往。", "explanation": "这里应该用〈独处〉。共处指多人一起相处，一个人待着要说独处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个孩子共处地很融洽。", "corrected_sentence": "两个孩子共处得很融洽。", "error_description": "“共处”后面的程度补语要用“得”，不能用“地”。正确：共处得很融洽；错误：共处地很融洽。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对室友共处得很愉快。", "corrected_sentence": "我跟室友共处得很愉快。", "error_description": "与人共同相处要用“跟”或“和”引出对象，“对”表示对待，不能和“共处”搭配。正确：跟室友共处；错误：对室友共处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渺小", "is_correct": true, "explanation": "渺小与宏大互为反义，指规模小、气势弱，与“场面宏大”相对。"}, {"text": "精巧", "is_correct": false, "explanation": "精巧指精细灵巧，与规模或气势无关，不是宏大的反义词。"}, {"text": "轻盈", "is_correct": false, "explanation": "轻盈指轻快灵活，与规模和气势无关，不构成反义。"}, {"text": "平淡", "is_correct": false, "explanation": "平淡指不突出、不新奇，与宏大的规模或气势不构成反义。"}], "correct_answer": "渺小", "explanations": {"渺小": "渺小与宏大互为反义，指规模小、气势弱，与“场面宏大”相对。", "精巧": "精巧指精细灵巧，与规模或气势无关，不是宏大的反义词。", "轻盈": "轻盈指轻快灵活，与规模和气势无关，不构成反义。", "平淡": "平淡指不突出、不新奇，与宏大的规模或气势不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渺小", "is_correct": true, "explanation": "渺小与宏大互为反义，指规模小、气势弱，与“很大”相对。"}, {"text": "单薄", "is_correct": false, "explanation": "单薄指薄弱、不厚实，与宏大的规模无关，不构成反义。"}, {"text": "浅显", "is_correct": false, "explanation": "浅显指容易理解，与宏大的规模或气势无关。"}, {"text": "柔弱", "is_correct": false, "explanation": "柔弱指柔和而软弱，与宏大的规模或气势不构成反义。"}], "correct_answer": "渺小", "explanations": {"渺小": "渺小与宏大互为反义，指规模小、气势弱，与“很大”相对。", "单薄": "单薄指薄弱、不厚实，与宏大的规模无关，不构成反义。", "浅显": "浅显指容易理解，与宏大的规模或气势无关。", "柔弱": "柔弱指柔和而软弱，与宏大的规模或气势不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容规模、范围、气势等非常大。", "primary_collocate": null, "pronunciation": "hóng dà", "ipa": "xʊŋ˧˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "在当代人工智能发展的宏大叙事中，开源自主AI代理的崛起正重新定义技术演进的边界。", "target_word": "宏大", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个计划很宏大，需要很多人一起做。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个宏大的梦想，想让全国的孩子都读书。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的场面宏大，让人难忘。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐的气势宏大，大厅里很安静。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座新城的规模宏大，路也很宽。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个宏大的故事，从古代说到现在。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工程太宏大了，十年也做不完。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，宏大的目标要一步一步实现。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的建筑群非常宏大。", "target_word": "宏大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宏大的", "label": "结构助词"}, {"form": "宏大叙事", "label": "复合"}], "register": "书面", "sense_fingerprint": "规模、范围、气势非常大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ee36597-8734-49e0-a69e-b3539cfe9228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宏大", "is_correct": true, "explanation": "宏大修饰“叙事”，构成“宏大叙事”，指规模和气势都很大的叙述框架，与句中的技术演进语境相符。"}, {"text": "渺小", "is_correct": false, "explanation": "语义：渺小指微不足道，与“崛起”“重新定义技术演进的边界”的宏大语境相反。"}, {"text": "简陋", "is_correct": false, "explanation": "搭配：简陋多用于房屋、设施等实物，不用来修饰“叙事”。"}, {"text": "老旧", "is_correct": false, "explanation": "语义：老旧表示陈旧，与“当代”“崛起”“重新定义”的语境相矛盾。"}], "explanations": {"宏大": "宏大修饰“叙事”，构成“宏大叙事”，指规模和气势都很大的叙述框架，与句中的技术演进语境相符。", "渺小": "语义：渺小指微不足道，与“崛起”“重新定义技术演进的边界”的宏大语境相反。", "简陋": "搭配：简陋多用于房屋、设施等实物，不用来修饰“叙事”。", "老旧": "语义：老旧表示陈旧，与“当代”“崛起”“重新定义”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "宏大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的人口很宏大。", "explanation": "这里应该用〈庞大〉。宏大用于规模、范围、气势等，人口、人数这类数量要用庞大。"}, {"text": "他是一位宏大的科学家，获得了很多奖。", "explanation": "这里应该用〈伟大〉。宏大形容规模或气势，不用来评价人的贡献与品格，称赞人物要用伟大。"}, {"text": "这双鞋很宏大，穿着走路很舒服。", "explanation": "这里应该用〈宽大〉。宏大指规模很大，鞋子、衣服的宽松要用宽大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宏大", "is_correct": true, "explanation": "宏大修饰“故事”，表示故事的范围广、跨度大，与“从古代说到现在”相符。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：短暂指时间很短，与“从古代说到现在”的时间跨度矛盾。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：狭窄多用于空间，不用来形容故事的范围。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清形容场所或气氛，不用来修饰故事。"}], "explanations": {"宏大": "宏大修饰“故事”，表示故事的范围广、跨度大，与“从古代说到现在”相符。", "短暂": "语义：短暂指时间很短，与“从古代说到现在”的时间跨度矛盾。", "狭窄": "搭配：狭窄多用于空间，不用来形容故事的范围。", "冷清": "搭配：冷清形容场所或气氛，不用来修饰故事。"}, "sentence_index": 6, "correct_answer": "宏大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故造成了宏大的损失。", "explanation": "这里应该用〈巨大〉。宏大指规模、范围很大，损失、压力这类程度上的大要用巨大。"}, {"text": "这项政策受到了宏大群众的欢迎。", "explanation": "这里应该用〈广大〉。宏大不用来修饰人群，指人多、范围广要用广大。"}, {"text": "他犯了一个宏大的错误，大家都很失望。", "explanation": "这里应该用〈重大〉。宏大形容规模、范围或气势，不修饰错误、事件的严重程度，这类要用重大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项改革的规模非常宏大过，影响了全国。", "corrected_sentence": "这项改革的规模非常宏大，影响了全国。", "error_description": "体标错误：形容词“宏大”后不能加动态助词“过”，应删去“过”，说“规模非常宏大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的场面办地很宏大，来了很多人。", "corrected_sentence": "这次活动的场面办得很宏大，来了很多人。", "error_description": "错误：补语前应用“得”而不是“地”。“地”用于修饰动词，“办得很宏大”的“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
