INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业界指的是从事生产、制造、服务等经济活动的企业和组织所构成的整体领域。", "primary_collocate": null, "pronunciation": "chǎn yè jiè", "ipa": "tʂʰan˨˩ jɛ˥˩ tɕjɛ˥˩", "syllable_count": 3, "sentences": [{"text": "其中，一种名为OpenClaw的模型无关架构，凭借其去中心化的设计哲学和高度可适配的代理范式，正在引发学界与产业界的深层思辨：它是否将在2026年成为个人AI代理的标准模板？", "target_word": "产业界", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "产业界和学术界应该多合作。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位专家在产业界工作了二十年。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界的老板们都关注这项新政策。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界欢迎这个减税的新办法。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从大学老师变成了产业界的顾问。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界需要更多懂技术的年轻人。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府请产业界的代表来开会。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界对明年的市场很有信心。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校和产业界一起培养工程师。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "企业与组织构成的整体经济领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084ae0df-3253-40e5-a861-f0a9a013f1f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电线", "is_correct": false, "explanation": "语义：电线是物件，不是可以与“学界”并列的群体或领域。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能与“学界”并列构成讨论的一方。"}, {"text": "产业界", "is_correct": true, "explanation": "正确。产业界指企业和组织构成的整体领域，与“学界”并列，符合AI技术落地的语境。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能与“学界”并列构成讨论的一方。"}], "explanations": {"电线": "语义：电线是物件，不是可以与“学界”并列的群体或领域。", "石头": "语义：石头是无生命的物体，不能与“学界”并列构成讨论的一方。", "产业界": "正确。产业界指企业和组织构成的整体领域，与“学界”并列，符合AI技术落地的语境。", "沙发": "语义：沙发是家具，不能与“学界”并列构成讨论的一方。"}, "sentence_index": 0, "correct_answer": "产业界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在产业界建了一座新工厂。", "explanation": "这里应该用〈工业区〉。产业界指企业和组织构成的整体领域，是抽象的群体，不能作为建厂的地点。"}, {"text": "他留下了很多产业界，有房子和土地。", "explanation": "这里应该用〈财产〉。产业界指企业和组织构成的整体领域，是抽象群体，不能作为个人留下的财产。"}, {"text": "他用产业界写了一封信。", "explanation": "这里应该用〈笔〉。产业界指企业和组织构成的整体领域，不是书写工具，不能用来写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是需要人才的主体，不能“需要”年轻人。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场地，不是能够“需要”人才的主体，不能与“需要更多懂技术的年轻人”搭配。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日常用品，不能“需要”懂技术的年轻人，句意不通。"}, {"text": "产业界", "is_correct": true, "explanation": "正确。产业界指企业和组织构成的整体领域，作主语表示需要人才，符合句意。"}], "explanations": {"天气": "语义：天气不是需要人才的主体，不能“需要”年轻人。", "花园": "语义：花园是场地，不是能够“需要”人才的主体，不能与“需要更多懂技术的年轻人”搭配。", "雨伞": "语义：雨伞是日常用品，不能“需要”懂技术的年轻人，句意不通。", "产业界": "正确。产业界指企业和组织构成的整体领域，作主语表示需要人才，符合句意。"}, "sentence_index": 6, "correct_answer": "产业界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的产业界很好吃。", "explanation": "这里应该用〈饭菜〉。产业界是抽象的领域，不是可以品尝的食物。"}, {"text": "产业界每天早上跳舞。", "explanation": "这里应该用〈妹妹〉。产业界是企业和组织构成的领域，不是人，不能跳舞。"}, {"text": "他把产业界拿去修了。", "explanation": "这里应该用〈电脑〉。产业界是抽象的群体，不是可以拿去修理的实体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一个产业界工作了很多年。", "corrected_sentence": "他在产业界工作了很多年。", "error_description": "错误在于量词：产业界指企业和组织构成的整体领域，是抽象群体，不能用“个”计量，应直接说“在产业界”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司从产业界的变化很敏感。", "corrected_sentence": "公司对产业界的变化很敏感。", "error_description": "错误在于介词：“对……敏感”是固定说法，引出对象要用“对”，不能用“从”。正确形式为“对产业界的变化很敏感”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
