INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指运用逻辑进行深入分析和辨别，以形成清晰、合理的判断。", "primary_collocate": null, "pronunciation": "sī biàn", "ipa": "sɨ˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "其中，一种名为OpenClaw的模型无关架构，凭借其去中心化的设计哲学和高度可适配的代理范式，正在引发学界与产业界的深层思辨：它是否将在2026年成为个人AI代理的标准模板？", "target_word": "思辨", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这本书引起了大家的思辨。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学课需要很多思辨。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章充满了思辨的力量。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的思辨需要清楚的逻辑。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的思辨能力要慢慢培养。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场思辨让我们明白了问题所在。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深入的思辨使他改变了看法。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励学生多做思辨练习。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有许多深刻的思辨。", "target_word": "思辨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "运用逻辑深入分析辨别的思考活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084ae0df-3253-40e5-a861-f0a9a013f1f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矿藏", "is_correct": false, "explanation": "语义：矿藏是地下的矿物，与学界讨论的逻辑分析无关。"}, {"text": "地下水", "is_correct": false, "explanation": "语义：地下水是自然资源，不能与“深层”的讨论搭配。"}, {"text": "思辨", "is_correct": true, "explanation": "正确。“深层思辨”指运用逻辑深入分析辨别，与后文的讨论语境相符。"}, {"text": "闲聊", "is_correct": false, "explanation": "语域：“闲聊”口语色彩浓，与句中的书面语域不符。"}], "explanations": {"矿藏": "语义：矿藏是地下的矿物，与学界讨论的逻辑分析无关。", "地下水": "语义：地下水是自然资源，不能与“深层”的讨论搭配。", "思辨": "正确。“深层思辨”指运用逻辑深入分析辨别，与后文的讨论语境相符。", "闲聊": "语域：“闲聊”口语色彩浓，与句中的书面语域不符。"}, "sentence_index": 0, "correct_answer": "思辨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把思辨装进了箱子里。", "explanation": "这里应该用〈书〉。思辨指运用逻辑分析辨别的活动，是抽象的思考，不能像书一样装进箱子。"}, {"text": "这思辨是红色的。", "explanation": "这里应该用〈房子〉。思辨是抽象的分析活动，没有颜色，不能用红色来形容。"}, {"text": "妈妈在厨房里洗思辨。", "explanation": "这里应该用〈碗〉。思辨是抽象的分析活动，不能像碗一样用来洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电线", "is_correct": false, "explanation": "语义：电线是物件，不能让人明白问题所在，与“这场”也不搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能让人明白问题所在。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能让人明白问题所在。"}, {"text": "思辨", "is_correct": true, "explanation": "正确。“思辨”指逻辑分析辨别，与“让我们明白了问题所在”相符。"}], "explanations": {"电线": "语义：电线是物件，不能让人明白问题所在，与“这场”也不搭配。", "石头": "语义：石头是无生命的物体，不能让人明白问题所在。", "沙发": "语义：沙发是家具，不能让人明白问题所在。", "思辨": "正确。“思辨”指逻辑分析辨别，与“让我们明白了问题所在”相符。"}, "sentence_index": 6, "correct_answer": "思辨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的思辨很好吃。", "explanation": "这里应该用〈饭菜〉。思辨指运用逻辑分析辨别的活动，是抽象的思考，不是可以品尝的食物。"}, {"text": "他在思辨里吃了一顿饭。", "explanation": "这里应该用〈饭馆〉。思辨是抽象的思考活动，不是可以进去吃饭的场所。"}, {"text": "这本书的思辨一直在跑步。", "explanation": "这里应该用〈运动员〉。思辨是抽象的分析活动，不能充当会运动的行动主体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的思辨了很深，大家都佩服他。", "corrected_sentence": "他的思辨很深，大家都佩服他。", "error_description": "错误在于“了”：作名词的“思辨”后面不能直接加“了”。正确形式为“他的思辨很深”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一把思辨很有意思。", "corrected_sentence": "这一场思辨很有意思。", "error_description": "错误在于量词：“把”用于有柄的器具，“思辨”指一次活动，应用“场”。正确形式为“这一场思辨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
