INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20001, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "涉及或谈到某个问题、话题或利益等。", "primary_collocate": null, "pronunciation": "chù jí", "ipa": "tʂʰu˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这一命题不仅关乎技术路径的选择，更触及智能个体化时代的伦理架构、知识主权与人类认知协同的根本问题。", "target_word": "触及", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这篇文章触及了环境问题。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话触及了我心里的痛处。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者的问题触及了事情的核心。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议没有触及价格问题。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影触及了很多人的回忆。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈话时请不要触及他的隐私。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书触及了社会的老问题。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈话很快就触及了家庭的困难。", "target_word": "触及", "complexity_tier": "T3", "furigana": "zhè cì tán huà hěn kuài jiù chù jí le jiā tíng de kùn nán", "sentence_source": "generated"}, {"text": "新法律触及了许多公司的利益。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "触及了", "label": "完成体"}, {"form": "触及过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "话题或言论涉及、接触到某个问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084ae0df-3253-40e5-a861-f0a9a013f1f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "触及", "is_correct": true, "explanation": "正确答案。触及（chù jí）意思是接触到、涉及到。"}, {"text": "初级", "is_correct": false, "explanation": "chū jí（第一声）与 chù jí（第四声）第一音节声调不同，意思是初级、入门级。"}, {"text": "处级", "is_correct": false, "explanation": "chǔ jí（第三声）与 chù jí（第四声）第一音节声调不同，意思是处一级的干部级别。"}, {"text": "出击", "is_correct": false, "explanation": "chū jī（第一声）与 chù jí 两个音节声调都不同，意思是主动发起攻击。"}], "explanations": {"触及": "正确答案。触及（chù jí）意思是接触到、涉及到。", "初级": "chū jí（第一声）与 chù jí（第四声）第一音节声调不同，意思是初级、入门级。", "处级": "chǔ jí（第三声）与 chù jí（第四声）第一音节声调不同，意思是处一级的干部级别。", "出击": "chū jī（第一声）与 chù jí 两个音节声调都不同，意思是主动发起攻击。"}, "sentence_index": null, "correct_answer": "触及"}, "level_3": {"options": [{"text": "触及", "is_correct": true, "explanation": "正确答案。“更触及……的根本问题”表示谈到并涉及这些根本问题。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮只用于食物，不能用来处理伦理架构和根本问题。"}, {"text": "剥削", "is_correct": false, "explanation": "语义：剥削指压榨他人劳动，与伦理架构和根本问题无关。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：挥霍指浪费财物，不能用于伦理架构和根本问题。"}], "explanations": {"触及": "正确答案。“更触及……的根本问题”表示谈到并涉及这些根本问题。", "煮": "语义：煮只用于食物，不能用来处理伦理架构和根本问题。", "剥削": "语义：剥削指压榨他人劳动，与伦理架构和根本问题无关。", "挥霍": "语义：挥霍指浪费财物，不能用于伦理架构和根本问题。"}, "sentence_index": 0, "correct_answer": "触及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经常触及外国朋友。", "explanation": "这里应该用〈接触〉。触及表示涉及问题或话题的范围，不用于人与人之间的往来。"}, {"text": "我在路上触及了老同学。", "explanation": "这里应该用〈碰到〉。表示偶然遇见某人要用碰到，触及不用于遇见人。"}, {"text": "我们一起触及了那个周末。", "explanation": "这里应该用〈度过〉。触及表示碰到或涉及问题，不能支配“周末”这类时间名词，度过那个周末才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触及", "is_correct": true, "explanation": "正确答案。“请不要触及他的隐私”表示谈话时不要涉及他的隐私。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：烘烤指用火加热食物，不能用于隐私。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪多用于树枝、头发，不说修剪隐私。"}, {"text": "擦亮", "is_correct": false, "explanation": "语义：擦亮指擦得发光，与隐私无关，不能用在这里。"}], "explanations": {"触及": "正确答案。“请不要触及他的隐私”表示谈话时不要涉及他的隐私。", "烘烤": "语义：烘烤指用火加热食物，不能用于隐私。", "修剪": "搭配：修剪多用于树枝、头发，不说修剪隐私。", "擦亮": "语义：擦亮指擦得发光，与隐私无关，不能用在这里。"}, "sentence_index": 6, "correct_answer": "触及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他触及了一个建议。", "explanation": "这里应该用〈提出〉。触及表示接触到或涉及问题，不说触及建议，提出建议才是正确搭配。"}, {"text": "我们触及了任务。", "explanation": "这里应该用〈完成〉。任务要说完成，触及不能用于任务。"}, {"text": "他触及了比赛。", "explanation": "这里应该用〈赢得〉。比赛要说赢得或参加，触及不表示取得结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告没有触及了问题的核心。", "corrected_sentence": "这份报告没有触及问题的核心。", "error_description": "错误在“触及了”。“没有”否定时不与“了”同用，应去掉“了”，写作“没有触及问题的核心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案触及触及教育的根本问题。", "corrected_sentence": "这个方案触及了教育的根本问题。", "error_description": "错误在动词“触及”重叠。“触及”不能重叠（不说“触及触及”），应去掉重复的部分，写作“触及了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
