INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指软件或系统能够被迁移到不同环境或平台上运行的能力，通常无需大量修改。", "primary_collocate": null, "pronunciation": "kě yí zhí xìng", "ipa": "kʰɤ˨˩˦ i˧˥ ʈʂɨ˧˥ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "OpenClaw的核心突破在于其“代理可移植性”理念——它不依赖特定基础模型的封闭生态，而是通过标准化接口协议，实现推理引擎、记忆模块、行动策略与外部环境的动态耦合。", "target_word": "可移植性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个软件的可移植性很好，换电脑也能用。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序员很重视代码的可移植性。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套系统的可移植性不高，只能在一种电脑上运行。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了提高可移植性，他们改写了整个程序。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可移植性强的游戏，手机和电脑都能玩。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板问我们这个产品的可移植性怎么样。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件的可移植性越高，换平台就越省事。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "测试时，我们先检查了程序的可移植性。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种语言的可移植性很强，所以很多人用。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "软件或系统迁移到不同平台仍能运行的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c16dde-b3e4-4ca0-a198-05848c7b5269') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可移植性", "is_correct": true, "explanation": "正确：指代理能迁移到不同平台运行，符合“代理可移植性理念”的语境。"}, {"text": "依赖性", "is_correct": false, "explanation": "语义：句中说“不依赖特定基础模型”，用“依赖性”与前文直接矛盾。"}, {"text": "封闭性", "is_correct": false, "explanation": "语义：句中强调标准化接口和动态耦合，是开放设计，“封闭性”与之相反。"}, {"text": "可读性", "is_correct": false, "explanation": "搭配：“可读性”多用于文字和代码的阅读难易，不用来描述代理理念。"}], "explanations": {"可移植性": "正确：指代理能迁移到不同平台运行，符合“代理可移植性理念”的语境。", "依赖性": "语义：句中说“不依赖特定基础模型”，用“依赖性”与前文直接矛盾。", "封闭性": "语义：句中强调标准化接口和动态耦合，是开放设计，“封闭性”与之相反。", "可读性": "搭配：“可读性”多用于文字和代码的阅读难易，不用来描述代理理念。"}, "sentence_index": 0, "correct_answer": "可移植性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的可移植性很强，读者很喜欢。", "explanation": "这里应该用〈可读性〉。可移植性指软件或系统能迁移到不同平台运行，不用来说文章是否容易读懂。"}, {"text": "这套门锁的可移植性很高，小偷很难打开。", "explanation": "这里应该用〈安全性〉。可移植性指软件或系统能迁移到不同环境运行，不用来说门锁能否防盗。"}, {"text": "这件衣服的可移植性很好，穿多少年都不变形。", "explanation": "这里应该用〈耐用性〉。可移植性指软件或系统能迁移到不同平台运行，不用来说衣服是否耐穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可移植性", "is_correct": true, "explanation": "正确：问的是产品能否迁移到其他平台，与“怎么样”的评价相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是人的情绪，产品没有心情，不能用来问产品的评价。"}, {"text": "信仰", "is_correct": false, "explanation": "语义：“信仰”属于人的精神层面，不能用来评价产品。"}, {"text": "人格", "is_correct": false, "explanation": "语义：“人格”只用于人，与“这个产品”的主语冲突。"}], "explanations": {"可移植性": "正确：问的是产品能否迁移到其他平台，与“怎么样”的评价相符。", "心情": "语义：“心情”是人的情绪，产品没有心情，不能用来问产品的评价。", "信仰": "语义：“信仰”属于人的精神层面，不能用来评价产品。", "人格": "语义：“人格”只用于人，与“这个产品”的主语冲突。"}, "sentence_index": 6, "correct_answer": "可移植性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师的可移植性很强，讲课总是很有趣。", "explanation": "这里应该用〈吸引力〉。可移植性指软件或系统能迁移到不同平台运行，不用来说老师讲课是否有趣。"}, {"text": "这座桥的可移植性很好，用了几十年还很结实。", "explanation": "这里应该用〈耐久性〉。可移植性指软件或系统能迁移到不同平台运行，不用来说桥梁经久耐用的程度。"}, {"text": "这家快递公司的可移植性很高，东西从来没丢过。", "explanation": "这里应该用〈可靠性〉。可移植性指软件或系统能迁移到不同平台运行，不用来说公司是否靠得住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这个软件的可移植性提高，换电脑就方便多了。", "corrected_sentence": "我们把这个软件的可移植性提高了，换电脑就方便多了。", "error_description": "“把”字句中，“提高”后缺少“了”。应为“把……提高了”，“把”字句要求动词带“了”或补语，缺少则句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个框架的可移植性的很强，在不同的系统上都能运行。", "corrected_sentence": "这个框架的可移植性很强，在不同的系统上都能运行。", "error_description": "多余的“的”：“可移植性”后直接接“很强”作谓语，不能加“的”。正确说法是“这个框架的可移植性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
