INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指计算机系统中，不同模块之间进行数据交换和通信时，双方共同遵守的约定和规范。", "primary_collocate": null, "pronunciation": "jiē kǒu xié yì", "ipa": "tɕjɛ˥ kʰoʊ˨˩˦ ɕjɛ˧˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "OpenClaw的核心突破在于其“代理可移植性”理念——它不依赖特定基础模型的封闭生态，而是通过标准化接口协议，实现推理引擎、记忆模块、行动策略与外部环境的动态耦合。", "target_word": "接口协议", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两个模块要先遵守同一个接口协议。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份接口协议写得很清楚。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "软件工程师正在修改接口协议。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "接口协议规定了数据的格式。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方的接口协议不一样，数据就传不过去。", "target_word": "接口协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑通过接口协议交换数据。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开发前，我们先确定接口协议。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的接口协议让系统连接更快。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把接口协议发给了合作公司。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "接口協議", "label": "繁体"}, {"form": "项", "label": "量词"}], "register": "专业", "sense_fingerprint": "接口协议：计算机模块间交换数据时双方共同遵守的约定和规范", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084ae0df-3253-40e5-a861-f0a9a013f1f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”指做菜的方法，与推理引擎、记忆模块之间的耦合无关。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“情绪”是人的心理状态，无法用来标准化并连接各个技术模块。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语，与这段专业的技术描述不合。"}, {"text": "接口协议", "is_correct": true, "explanation": "正确：接口协议指模块之间交换数据时双方遵守的规范，与“标准化”和模块耦合相合。"}], "explanations": {"食谱": "语义：“食谱”指做菜的方法，与推理引擎、记忆模块之间的耦合无关。", "情绪": "语义：“情绪”是人的心理状态，无法用来标准化并连接各个技术模块。", "门道": "语域：“门道”是口语，与这段专业的技术描述不合。", "接口协议": "正确：接口协议指模块之间交换数据时双方遵守的规范，与“标准化”和模块耦合相合。"}, "sentence_index": 0, "correct_answer": "接口协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把接口协议写得很清楚。", "explanation": "这里应该用〈份〉。协议属于文件，用“份”计量；“把”用于有柄或可握的器具，不能用来数接口协议。"}, {"text": "我把电脑的接口协议拔下来了。", "explanation": "这里应该用〈接口〉。接口是可以拔下来的实物插口；接口协议是双方约定的规则，不能被拔下来。"}, {"text": "程序员用接口协议写代码。", "explanation": "这里应该用〈编程语言〉。写代码要用编程语言；接口协议只规定模块间交换数据的规则，不能用来写程序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "语义：手机和电脑交换数据不靠“电影”，两者毫无关系。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指人或物的外形，不能用来说明设备之间如何交换数据。"}, {"text": "窍门", "is_correct": false, "explanation": "语域：“窍门”是口语，与这句的技术叙述不合。"}, {"text": "接口协议", "is_correct": true, "explanation": "正确：手机和电脑要按双方约定的规则交换数据，这正是接口协议。"}], "explanations": {"电影": "语义：手机和电脑交换数据不靠“电影”，两者毫无关系。", "外貌": "语义：“外貌”指人或物的外形，不能用来说明设备之间如何交换数据。", "窍门": "语域：“窍门”是口语，与这句的技术叙述不合。", "接口协议": "正确：手机和电脑要按双方约定的规则交换数据，这正是接口协议。"}, "sentence_index": 6, "correct_answer": "接口协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们和房东签了一份接口协议，每月房租是三千元。", "explanation": "这里应该用〈合同〉。合同可以约定房租；接口协议只规定技术上的数据交换方式，不涉及房租。"}, {"text": "这局游戏的接口协议很公平。", "explanation": "这里应该用〈规则〉。规则用于比赛、游戏等活动；接口协议只约束机器之间的数据交换。"}, {"text": "老人说的是一口地道的四川接口协议。", "explanation": "这里应该用〈方言〉。“一口地道的……”修饰的是语言或方言；接口协议是机器之间的约定，不是人说的话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师修改了一只接口协议。", "corrected_sentence": "工程师修改了一份接口协议。", "error_description": "量词错误：“只”用于动物，接口协议是文件，应说“份”，不能说“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把接口协议修改了好了。", "corrected_sentence": "我们把接口协议修改好了。", "error_description": "补语位置错误：“了”插在动词“修改”和结果补语“好”之间。结果补语“好”应紧跟动词，应说“修改好了”，不能说“修改了好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
