INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某个事物或系统外界的情况和条件。", "primary_collocate": null, "pronunciation": "wài bù huán jìng", "ipa": "wai˥˩ pu˥˩ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "OpenClaw的核心突破在于其“代理可移植性”理念——它不依赖特定基础模型的封闭生态，而是通过标准化接口协议，实现推理引擎、记忆模块、行动策略与外部环境的动态耦合。", "target_word": "外部环境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司的发展受外部环境影响很大。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部环境变了，我们的计划也要改。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统要适应不同的外部环境。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好是外部环境的问题，不是我们的错。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人要先了解外部环境，才能做决定。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部环境很复杂，公司必须小心。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序不受外部环境的影响。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在研究外部环境对产品的影响。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度、网络都是外部环境的一部分。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外部环境因素", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物或系统外界的情况和条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d23743e-da8a-456c-b392-e2c429d26a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外部环境", "is_correct": true, "explanation": "正确。“实现……与外部环境的动态耦合”，外部环境指系统外界的情况和条件，符合句意。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”不是系统中可以与推理引擎、记忆模块耦合的要素，不合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是系统中可以与推理引擎、记忆模块耦合的要素。"}, {"text": "俗语", "is_correct": false, "explanation": "语域：“俗语”是口语化的通俗说法，与这段书面的技术描述不相符。"}], "explanations": {"外部环境": "正确。“实现……与外部环境的动态耦合”，外部环境指系统外界的情况和条件，符合句意。", "账单": "语义：“账单”不是系统中可以与推理引擎、记忆模块耦合的要素，不合句意。", "颜色": "语义：“颜色”不是系统中可以与推理引擎、记忆模块耦合的要素。", "俗语": "语域：“俗语”是口语化的通俗说法，与这段书面的技术描述不相符。"}, "sentence_index": 0, "correct_answer": "外部环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把外部环境装进了行李箱，准备出门。", "explanation": "这里应该用〈行李〉。外部环境是抽象的情况和条件，不是可以装进箱子的具体东西。"}, {"text": "他的外部环境比同班同学高很多。", "explanation": "这里应该用〈身高〉。外部环境指事物之外的情况和条件，不用来形容人的身高。"}, {"text": "妈妈在汤里加了一勺外部环境，味道很好。", "explanation": "这里应该用〈调料〉。外部环境是抽象的情况和条件，不能当作调料加进汤里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外部环境", "is_correct": true, "explanation": "正确。“外部环境很复杂，公司必须小心”，外部环境指公司之外的情况和条件，符合句意。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”是一顿饭，不能说“很复杂”，与“公司必须小心”的语境无关。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：“乐谱”是音乐的记录，不能作为这句话的主语。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的身体高度，不能用“很复杂”来形容，也与公司的处境无关。"}], "explanations": {"外部环境": "正确。“外部环境很复杂，公司必须小心”，外部环境指公司之外的情况和条件，符合句意。", "早餐": "语义：“早餐”是一顿饭，不能说“很复杂”，与“公司必须小心”的语境无关。", "乐谱": "语义：“乐谱”是音乐的记录，不能作为这句话的主语。", "身高": "体貌：“身高”描述人的身体高度，不能用“很复杂”来形容，也与公司的处境无关。"}, "sentence_index": 6, "correct_answer": "外部环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的外部环境很快乐，每天都笑个不停。", "explanation": "这里应该用〈心情〉。外部环境指周围的情况和条件，不能用来形容人的心情。"}, {"text": "妈妈把外部环境煮熟了，端上了桌。", "explanation": "这里应该用〈饭菜〉。外部环境是抽象的情况，不是可以煮熟、端上桌的东西。"}, {"text": "这辆车的外部环境很快，一下就开远了。", "explanation": "这里应该用〈速度〉。外部环境是抽象的情况和条件，不用来形容车的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个系统要适应一只复杂的外部环境。", "corrected_sentence": "这个系统要适应一种复杂的外部环境。", "error_description": "量词错误：“外部环境”是抽象的情况，应搭配量词“种”，不能用“只”（“只”多用于动物或成对物件中的一个）。正确说法是：一种复杂的外部环境。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外部环境很稳定地，但仍要注意风险。", "corrected_sentence": "外部环境很稳定，但仍要注意风险。", "error_description": "错误：“稳定”作谓语时后面不能加“地”，应说“很稳定”；“地”用于修饰动词的状语，不用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
