INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20015, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某个活动或事情中起主要作用、带领别人的人。", "primary_collocate": null, "pronunciation": "zhǔ dǎo zhě", "ipa": "tʂu˧˥ tɑʊ˧˥ tʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "主导者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小李是这次活动的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个项目里，王经理是主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子应该成为自己学习的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁是这场谈判的主导者？", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想只听别人说，想做讨论的主导者。", "target_word": "主导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不是课堂唯一的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行的主导者是我姐姐。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直是这个小组的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从参与者变成了比赛的主导者。", "target_word": "主导者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在活动或事情中起主要作用、带领别人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '177778a7-0e89-45d6-9599-764796678496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主导者", "is_correct": true, "explanation": "正确：“主导者”指在演化方向上起主要作用的人，与句意相符。"}, {"text": "跟随者", "is_correct": false, "explanation": "语义：“跟随者”处于从属地位，与“成为……方向的”主动推动的语境相反。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：“旁观者”不参与其中，与“成为代理演化方向的”要主动推动相悖。"}, {"text": "接收者", "is_correct": false, "explanation": "搭配：“演化方向”多与“主导”“引导”搭配，“接收者”不宜与之搭配。"}], "explanations": {"主导者": "正确：“主导者”指在演化方向上起主要作用的人，与句意相符。", "跟随者": "语义：“跟随者”处于从属地位，与“成为……方向的”主动推动的语境相反。", "旁观者": "语义：“旁观者”不参与其中，与“成为代理演化方向的”要主动推动相悖。", "接收者": "搭配：“演化方向”多与“主导”“引导”搭配，“接收者”不宜与之搭配。"}, "sentence_index": 0, "correct_answer": "主导者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区最近来了很多主导者在偷东西。", "explanation": "这里应该用〈小偷〉。“主导者”指带领别人、起主要作用的人，偷东西的人要说“小偷”。"}, {"text": "这场比赛吸引了很多主导者。", "explanation": "这里应该用〈观众〉。“主导者”指在某事中起主要作用、带领别人的人，看比赛的人要说“观众”。"}, {"text": "医院里有很多主导者在打针。", "explanation": "这里应该用〈病人〉。“主导者”指带领别人、起主要作用的人，在医院打针、接受治疗的人要说“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主导者", "is_correct": true, "explanation": "正确：“唯一的主导者”指课堂中起主要作用的人，句意合理。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘车的人，与“课堂”无关。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指接受治疗的人，与“课堂”无关。"}, {"text": "顾客", "is_correct": false, "explanation": "搭配：“课堂”不接“顾客”，“顾客”搭配的是商店、餐厅。"}], "explanations": {"主导者": "正确：“唯一的主导者”指课堂中起主要作用的人，句意合理。", "乘客": "语义：“乘客”指乘车的人，与“课堂”无关。", "病人": "语义：“病人”指接受治疗的人，与“课堂”无关。", "顾客": "搭配：“课堂”不接“顾客”，“顾客”搭配的是商店、餐厅。"}, "sentence_index": 6, "correct_answer": "主导者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这趟列车有很多主导者。", "explanation": "这里应该用〈乘客〉。“主导者”指在某事中起主要作用的人，乘车的人要说“乘客”。"}, {"text": "这座动物园有很多主导者。", "explanation": "这里应该用〈游客〉。“主导者”指在某事中起主要作用的人，参观景点的人要说“游客”。"}, {"text": "这家超市来了很多主导者排队结账。", "explanation": "这里应该用〈顾客〉。“主导者”指带领别人、起主要作用的人，到超市购物的人要说“顾客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动有三只主导者。", "corrected_sentence": "这次活动有三位主导者。", "error_description": "错误在量词：“只”应改为“位”。“只”多用于动物或小件物品，“主导者”指人，应用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两台主导者都同意了这个方案。", "corrected_sentence": "两位主导者都同意了这个方案。", "error_description": "错误在量词：“台”应改为“位”。“台”用于机器、设备，“主导者”指人，应用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
