INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "价值观是个人或群体对事物价值的基本看法和评价标准，影响人的选择和行动。", "primary_collocate": null, "pronunciation": "jià zhí guān", "ipa": "tɕja˥˩ ʈʂɨ˧˥ kuan˥", "syllable_count": 3, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "价值观", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个人的价值观都不一样。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母的价值观会影响孩子。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的价值观和我的很接近。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司很重视员工的价值观。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人的价值观在慢慢变化。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要有正确的价值观。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人价值观不同，很难相处。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校应该帮助学生形成好的价值观。", "target_word": "价值观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的人，价值观也不同。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "个人或群体对事物价值的基本看法和评价标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '177778a7-0e89-45d6-9599-764796678496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价值观", "is_correct": true, "explanation": "正确。价值观与偏好、伦理准则并列，指人的基本评价标准，符合句中语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体的外形特征，不是评价标准，不能与偏好、伦理准则并列嵌入认知循环。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是主观的价值判断，与偏好、伦理准则不搭配。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是具体物品，不能作为可嵌入认知循环的价值标准，与句意不符。"}], "explanations": {"价值观": "正确。价值观与偏好、伦理准则并列，指人的基本评价标准，符合句中语境。", "身高": "体貌：身高是身体的外形特征，不是评价标准，不能与偏好、伦理准则并列嵌入认知循环。", "天气": "语义：天气是自然现象，不是主观的价值判断，与偏好、伦理准则不搭配。", "钥匙": "语义：钥匙是具体物品，不能作为可嵌入认知循环的价值标准，与句意不符。"}, "sentence_index": 0, "correct_answer": "价值观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件古董的价值观很高。", "explanation": "这里应该用〈身价〉。说古董值多少钱要用身价，价值观指看法和评价标准，不指物品的价值高低。"}, {"text": "他的价值观很开朗。", "explanation": "这里应该用〈性格〉。形容人的为人、脾气开朗要说性格，价值观指看法和评价标准，不能用来形容性情。"}, {"text": "这台电脑的价值观很合理。", "explanation": "这里应该用〈价格〉。价格指买卖时的钱数，评价电脑的价钱要用价格，价值观指看法和标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价值观", "is_correct": true, "explanation": "正确。“正确的价值观”是常见搭配，指人的基本看法和标准，符合句意。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出行时携带的物品，不能被“正确”修饰成为人应当拥有的看法。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“正确”一般修饰看法、做法等抽象内容，不说“正确的鞋子”来表达应有的标准。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是可以“要有”并且可以被判断正确与否的内容，与句意不符。"}], "explanations": {"价值观": "正确。“正确的价值观”是常见搭配，指人的基本看法和标准，符合句意。", "行李": "语义：行李是出行时携带的物品，不能被“正确”修饰成为人应当拥有的看法。", "鞋子": "搭配：“正确”一般修饰看法、做法等抽象内容，不说“正确的鞋子”来表达应有的标准。", "桌子": "语义：桌子是家具，不是可以“要有”并且可以被判断正确与否的内容，与句意不符。"}, "sentence_index": 6, "correct_answer": "价值观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为这次失败付出了很大的价值观。", "explanation": "这里应该用〈代价〉。付出的是代价，价值观是看法和标准，不能被付出。"}, {"text": "这次旅行的价值观很高，大家都觉得很贵。", "explanation": "这里应该用〈费用〉。说旅行花钱多少要用费用，价值观不能用来指花费的高低。"}, {"text": "他的价值观越来越多，已经够买房了。", "explanation": "这里应该用〈存款〉。存款是钱财，可以越来越多；价值观是看法标准，不能这样计量，也不能用来买房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社区的人有一只共同的价值观。", "corrected_sentence": "这个社区的人有一种共同的价值观。", "error_description": "量词错误：价值观是抽象概念，应使用量词“种”，不能用“只”。正确说法是“一种共同的价值观”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她希望孩子拥有健康地价值观。", "corrected_sentence": "她希望孩子拥有健康的价值观。", "error_description": "的地混用：“健康”修饰名词“价值观”时应用“的”，不能用“地”。正确说法是“健康的价值观”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
