INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20017, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某个人或某件事更感兴趣，觉得他或它比别的更好。", "primary_collocate": null, "pronunciation": "piān hào", "ipa": "pʰjɛn˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "用户不再是被动接受预设行为逻辑的终端使用者，而成为代理演化方向的主导者，其价值观、偏好与伦理准则可被持续嵌入代理的认知循环。", "target_word": "偏好", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个人的饮食偏好都不同。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网站会记录你的阅读偏好。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店很了解客人的偏好。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我你的颜色偏好。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的音乐偏好很特别。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师会根据学生的偏好安排活动。", "target_word": "偏好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人偏好不应该影响工作。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对咖啡没有特别的偏好。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长要留意孩子的学习偏好。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "对某人或某事更感兴趣、觉得更好的倾向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '177778a7-0e89-45d6-9599-764796678496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏好", "is_correct": true, "explanation": "正确。偏好与价值观、伦理准则并列，指对事物的倾向，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是身体特征，不是对事物的倾向，不能与价值观、伦理准则并列。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为人对事物的倾向，与句中的并列对象不搭。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是具体物品，不能作为可嵌入认知循环的倾向，与句意不符。"}], "explanations": {"偏好": "正确。偏好与价值观、伦理准则并列，指对事物的倾向，符合句意。", "身高": "体貌：身高是身体特征，不是对事物的倾向，不能与价值观、伦理准则并列。", "天气": "语义：天气是自然现象，不能作为人对事物的倾向，与句中的并列对象不搭。", "钥匙": "语义：钥匙是具体物品，不能作为可嵌入认知循环的倾向，与句意不符。"}, "sentence_index": 0, "correct_answer": "偏好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店卖的偏好很多。", "explanation": "这里应该用〈商品〉。卖的是实物，偏好指个人对事物的倾向，不能说“卖的偏好”。"}, {"text": "他在比赛中取得了好偏好。", "explanation": "这里应该用〈成绩〉。“取得”搭配的是成绩、名次，偏好是对事物的倾向，不能被取得。"}, {"text": "他的偏好有一米八。", "explanation": "这里应该用〈身高〉。说人的身高要用身高，偏好指对事物的倾向，不能用来表示长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏好", "is_correct": true, "explanation": "正确。“根据学生的偏好安排活动”是合理的说法，偏好指学生对事物的倾向，符合语境。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不能作为老师安排活动的依据，与句意不符。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“根据鞋子安排活动”没有意义，鞋子不是安排活动的依据。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能作为根据学生情况安排活动的依据。"}], "explanations": {"偏好": "正确。“根据学生的偏好安排活动”是合理的说法，偏好指学生对事物的倾向，符合语境。", "行李": "语义：行李是物品，不能作为老师安排活动的依据，与句意不符。", "鞋子": "搭配：“根据鞋子安排活动”没有意义，鞋子不是安排活动的依据。", "桌子": "语义：桌子是家具，不能作为根据学生情况安排活动的依据。"}, "sentence_index": 6, "correct_answer": "偏好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每月的偏好是五千元。", "explanation": "这里应该用〈工资〉。说每月拿到的钱数要用工资，偏好指对事物的倾向，不能用来表示金额。"}, {"text": "这次旅行的偏好很高，大家都觉得很贵。", "explanation": "这里应该用〈费用〉。说旅行花钱多少要用费用，偏好是倾向，不能用“高”来形容花费。"}, {"text": "他为这次失败付出了很大的偏好。", "explanation": "这里应该用〈代价〉。付出的是代价，偏好是个人的倾向，不能被付出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对咖啡有一只特别的偏好。", "corrected_sentence": "我对咖啡有一种特别的偏好。", "error_description": "量词错误：偏好是抽象概念，应使用量词“种”，不能用“只”。正确说法是“一种特别的偏好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对音乐有明显地偏好。", "corrected_sentence": "他对音乐有明显的偏好。", "error_description": "的地混用：“有”后面要接名词短语，“明显地偏好”是状中结构，修饰名词“偏好”时应用“的”。正确说法是“有明显的偏好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
