INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指涉指语言表达中提及或关联到特定对象、事物或概念的行为。", "primary_collocate": null, "pronunciation": "zhǐ shè", "ipa": "tʂʅ˨˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，该架构在元学习层面引入“自我指涉优化”机制。", "target_word": "指涉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这句话指涉的是我们的老师。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他”在这里指涉前面提到的人。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词指涉一种很特别的颜色。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗里的“月亮”常常指涉思念的人。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章没有指涉任何具体的人。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“这个代词指涉谁？”", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话明显指涉昨天发生的事。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名字可以指涉一个人，也可以指涉一家公司。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的“门”其实指涉一种机会。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指涉了", "label": "体标"}, {"form": "指涉过", "label": "体标"}, {"form": "自我指涉", "label": "复合"}], "register": "书面", "sense_fingerprint": "指涉：语言表达提及或关联到特定对象、事物或概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20019, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指涉", "is_correct": true, "explanation": "正确：指涉指语言表达提及或关联到某对象或概念，符合“自我指涉优化”的用法。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指降低温度，与“自我……优化”这样的机制无关。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：报销多用于费用、开支，不与“优化机制”组合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体变为液体，不能用于抽象的机制。"}], "explanations": {"指涉": "正确：指涉指语言表达提及或关联到某对象或概念，符合“自我指涉优化”的用法。", "冷却": "语义：冷却指降低温度，与“自我……优化”这样的机制无关。", "报销": "搭配：报销多用于费用、开支，不与“优化机制”组合。", "融化": "语义：融化指固体变为液体，不能用于抽象的机制。"}, "sentence_index": 0, "correct_answer": "指涉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手指涉远处的那棵树。", "explanation": "这里应该用〈指向〉。指涉指语言表达所提及的对象，不表示用手指着某处。"}, {"text": "班长把他指涉到了门口。", "explanation": "这里应该用〈领〉。指涉表示提及，不表示带领他人移动。"}, {"text": "教练把哨子指涉到了嘴边。", "explanation": "这里应该用〈放〉。指涉表示提及，不表示移动或放置物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指涉", "is_correct": true, "explanation": "正确：指涉指代词提到某人，此处老师在问这个代词指的是谁。"}, {"text": "询问", "is_correct": false, "explanation": "语义：代词本身不能“询问”，句中是要问这个代词指谁。"}, {"text": "覆盖", "is_correct": false, "explanation": "语义：覆盖指遮盖或铺满，与代词的指称关系无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是不及物动词，不能带“谁”作宾语。"}], "explanations": {"指涉": "正确：指涉指代词提到某人，此处老师在问这个代词指的是谁。", "询问": "语义：代词本身不能“询问”，句中是要问这个代词指谁。", "覆盖": "语义：覆盖指遮盖或铺满，与代词的指称关系无关。", "睡觉": "配价：睡觉是不及物动词，不能带“谁”作宾语。"}, "sentence_index": 6, "correct_answer": "指涉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把我们指涉到了操场上。", "explanation": "这里应该用〈带〉。指涉表示提及，不表示带领他人到某处。"}, {"text": "他负责指涉公司的财务。", "explanation": "这里应该用〈管理〉。指涉不表示管理或负责事务。"}, {"text": "妈妈把一件新衣服指涉进了衣柜。", "explanation": "这里应该用〈放〉。指涉表示提及，不表示把物品放置到某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个概念指涉着了一种抽象的关系。", "corrected_sentence": "这个概念指涉了一种抽象的关系。", "error_description": "体标重复：“着”与“了”不能同用于“指涉”，应去掉“着”，说“这个概念指涉了一种抽象的关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个符号指涉得一个国家。", "corrected_sentence": "这个符号指涉一个国家。", "error_description": "多余的助词：“得”只能接在动词后作补语的标记，“指涉”后直接带宾语，不能加“得”。应说“这个符号指涉一个国家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
