INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "函数是一种数学关系，每个输入值对应唯一的输出值。", "primary_collocate": null, "pronunciation": "hán shù", "ipa": "xan˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "代理不仅执行任务，还能对自身决策过程进行反思性建模，通过多层级反馈回路调整目标函数。", "target_word": "函数", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师在黑板上写了一个函数。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输入三，这个函数就输出九。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个函数都有输入和输出。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在学一次函数。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个函数的每个输入都对应一个输出。", "target_word": "函数", "complexity_tier": "T3", "furigana": "zhè gè hán shù de měi gè shū rù dōu duì yìng yí gè shū chū.", "sentence_source": "generated"}, {"text": "这个函数的结果总是正数。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "函数的图像可以画在坐标系里。", "target_word": "函数", "complexity_tier": "T3", "furigana": "hán shù de tú xiàng kě yǐ huà zài zuò biāo xì lǐ.", "sentence_source": "generated"}, {"text": "请你找出这个函数的最大值。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们画了二次函数的图。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "目标函数", "label": "复合"}, {"form": "一次函数", "label": "复合"}, {"form": "函數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "函数：每个输入值对应唯一输出值的数学关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "函数", "is_correct": true, "explanation": "正确：函数（hán shù）指数学中输入与输出之间的对应关系。"}, {"text": "行数", "is_correct": false, "explanation": "háng（第二声）与 hán（第二声）声母相同，韵母 ang 与 an 不同，意思是行的数目，不是函数。"}, {"text": "韩式", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是韩国式的，不是函数。"}, {"text": "寒暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是寒冷与炎热，不是函数。"}], "explanations": {"函数": "正确：函数（hán shù）指数学中输入与输出之间的对应关系。", "行数": "háng（第二声）与 hán（第二声）声母相同，韵母 ang 与 an 不同，意思是行的数目，不是函数。", "韩式": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是韩国式的，不是函数。", "寒暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是寒冷与炎热，不是函数。"}, "sentence_index": null, "correct_answer": "函数"}, "level_3": {"options": [{"text": "函数", "is_correct": true, "explanation": "正确：目标函数是优化问题中被调整的对象，与“调整目标”搭配。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”是手段，不是可以被调整的目标对象，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“调整”不与“窗户”搭配，且句子讲的是算法优化，与窗户无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，不适合这段书面的技术语境。"}], "explanations": {"函数": "正确：目标函数是优化问题中被调整的对象，与“调整目标”搭配。", "工具": "语义：“工具”是手段，不是可以被调整的目标对象，句意不通。", "窗户": "搭配：“调整”不与“窗户”搭配，且句子讲的是算法优化，与窗户无关。", "玩意儿": "语域：“玩意儿”是口语，不适合这段书面的技术语境。"}, "sentence_index": 0, "correct_answer": "函数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的答案是靠函数的颜色得到的。", "explanation": "这里应该用〈思路〉。函数是数学对应关系，不能指解题的方法，与颜色更无关。"}, {"text": "这款手机的拍照函数很强。", "explanation": "这里应该用〈功能〉。函数指输入与输出的数学对应关系，不能用来说手机的拍照功能。"}, {"text": "这个部门的函数很清楚。", "explanation": "这里应该用〈职责〉。函数是数学概念，不能用来说部门负责的事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "函数", "is_correct": true, "explanation": "正确：函数的结果指输入经运算后得到的值，可以是正数，符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是数学对象，不存在“结果总是正数”的说法。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语，不能指代数学对象，与数学陈述的语体不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“结果总是正数”说的是数值，不能与“冰箱”搭配。"}], "explanations": {"函数": "正确：函数的结果指输入经运算后得到的值，可以是正数，符合语境。", "手机": "语义：手机不是数学对象，不存在“结果总是正数”的说法。", "哥们": "语域：“哥们”是口语，不能指代数学对象，与数学陈述的语体不合。", "冰箱": "搭配：“结果总是正数”说的是数值，不能与“冰箱”搭配。"}, "sentence_index": 6, "correct_answer": "函数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的函数很温和。", "explanation": "这里应该用〈性格〉。函数是数学概念，不能用来形容人的性格。"}, {"text": "今天的函数很好。", "explanation": "这里应该用〈天气〉。函数不能用来说天气的好坏。"}, {"text": "这朵花的函数很鲜艳。", "explanation": "这里应该用〈颜色〉。函数不能用来形容花的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的作业里有一只函数。", "corrected_sentence": "我们的作业里有一个函数。", "error_description": "量词错误：“函数”是抽象概念，量词应用“个”；“只”多用于动物，这里应改为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在优化一个的目标函数。", "corrected_sentence": "他们在优化一个目标函数。", "error_description": "多余的助词：数量词「一个」与修饰语「目标」之间不能加「的」，应说「一个目标函数」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
