INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指具有人的特征或类似人的事物，如外形、行为或智能。", "primary_collocate": null, "pronunciation": "lèi rén", "ipa": "lei˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这种内省能力使得OpenClaw在复杂、非结构化的生活场景中展现出类人的问题解决韧性。", "target_word": "类人", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个机器人有类人的外形。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "类人机器人会像人一样走路。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在做类人的智能助手。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它的动作很自然，有类人的协调性，不像普通机器。", "target_word": "类人", "complexity_tier": "T3", "furigana": "tā de dòngzuò hěn zìrán, yǒu lèirén de xiétiáoxìng, bú xiàng pǔtōng jīqì.", "sentence_source": "generated"}, {"text": "展览上有一个类人的机器人，会笑也会说话。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "类人的表情让孩子们很喜欢。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想让电脑有类人的思考方式。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里的角色，行为有明显的类人特点。", "target_word": "类人", "complexity_tier": "T3", "furigana": "zhège yóuxì lǐ de juésè, xíngwéi yǒu míngxiǎn de lèirén tèdiǎn.", "sentence_source": "generated"}, {"text": "他设计了一个类人的玩具，会点头。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "类人的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "具有人的外形、行为或智能特征的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类人", "is_correct": true, "explanation": "正确：类人指具有人的特征，符合“展现出类人的……”的用法。"}, {"text": "僵硬", "is_correct": false, "explanation": "语义：僵硬指不灵活，与韧性所指的灵活应变相反。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：迟钝指反应慢、不灵敏，与韧性的意思相反。"}, {"text": "方正", "is_correct": false, "explanation": "体貌：方正描写外形的棱角，不用来形容问题解决韧性。"}], "explanations": {"类人": "正确：类人指具有人的特征，符合“展现出类人的……”的用法。", "僵硬": "语义：僵硬指不灵活，与韧性所指的灵活应变相反。", "迟钝": "语义：迟钝指反应慢、不灵敏，与韧性的意思相反。", "方正": "体貌：方正描写外形的棱角，不用来形容问题解决韧性。"}, "sentence_index": 0, "correct_answer": "类人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工匠做了一张类人的桌子。", "explanation": "这里应该用〈木制〉。类人指像人的特征，不用于描述桌子等无人形的物品。"}, {"text": "这个盘子是类人的。", "explanation": "这里应该用〈圆形〉。类人说的是像人，不描述盘子的形状。"}, {"text": "她买了一条类人的裙子。", "explanation": "这里应该用〈深蓝色〉。类人不用于描述颜色或款式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类人", "is_correct": true, "explanation": "正确：类人形容像人的表情，符合句中语境。"}, {"text": "金属", "is_correct": false, "explanation": "语义：金属指材料，与表情的意思不符。"}, {"text": "陶瓷", "is_correct": false, "explanation": "语义：陶瓷指材料，与表情的意思不符。"}, {"text": "平整", "is_correct": false, "explanation": "体貌：平整描写表面是否平坦，不用于形容表情。"}], "explanations": {"类人": "正确：类人形容像人的表情，符合句中语境。", "金属": "语义：金属指材料，与表情的意思不符。", "陶瓷": "语义：陶瓷指材料，与表情的意思不符。", "平整": "体貌：平整描写表面是否平坦，不用于形容表情。"}, "sentence_index": 6, "correct_answer": "类人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙是类人的，刷成了白色。", "explanation": "这里应该用〈白色〉。类人指像人的特征，不用于描述墙面的颜色。"}, {"text": "这些花是类人的，不会谢。", "explanation": "这里应该用〈人工〉。人工指人造的物品，类人指像人的特征，不说明事物是否人造。"}, {"text": "这是一杯类人的牛奶。", "explanation": "这里应该用〈液态〉。类人指像人的特征，牛奶的状态要用液态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机器人有类人地动作，看起来很自然。", "corrected_sentence": "这个机器人有类人的动作，看起来很自然。", "error_description": "错误：定语标记用错。类人修饰名词“动作”，应用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她设计了一个类人地小熊，会眨眼睛。", "corrected_sentence": "她设计了一个类人的小熊，会眨眼睛。", "error_description": "错误：定语标记用错。“类人”修饰名词“小熊”，应用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮助、辅助别人完成某项工作或活动。", "primary_collocate": null, "pronunciation": "xié zhù", "ipa": "ɕi̯ɛ˧˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "协助", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "同事协助我完成了这份报告。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你协助经理安排明天的会议。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请大家协助调查这件事。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在朋友的协助下，他找到了工作。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生协助她整理资料。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派两个人协助我们做这个项目。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你协助我们完成任务。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾协助过很多新同事。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在护士的协助下做完了检查。", "target_word": "协助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协助了", "label": "体标（完成）"}, {"form": "协助过", "label": "体标（经历）"}], "register": "书面", "sense_fingerprint": "协助：辅助他人完成工作或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助（xié zhù）：帮助他人完成工作或活动。"}, {"text": "截住", "is_correct": false, "explanation": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。"}, {"text": "接住", "is_correct": false, "explanation": "jiē（第一声）与 xié（第二声）声母和声调都不同，“接住”意思是接过来。"}, {"text": "邪术", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。"}, {"text": "借住", "is_correct": false, "explanation": "jiè（第四声）与 xié 声母和声调都不同，“借住”意思是暂时住在别人家里。"}], "explanations": {"协助": "协助（xié zhù）：帮助他人完成工作或活动。", "截住": "jié 与 xié 声母不同（j 与 x），“截住”意思是拦住。", "接住": "jiē（第一声）与 xié（第二声）声母和声调都不同，“接住”意思是接过来。", "邪术": "shù 与 zhù 声母不同（sh 与 zh），“邪术”意思是邪门的法术。", "借住": "jiè（第四声）与 xié 声母和声调都不同，“借住”意思是暂时住在别人家里。"}, "sentence_index": null, "correct_answer": "协助"}, "level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：辅助科研工作者梳理文献，与后文“认知协作者”的角色相合。"}, {"text": "监督", "is_correct": false, "explanation": "语义：“监督”是监管他人，与“认知协作者”的角色相反。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”是妨碍，与“提取证据、提出建议”的助益功能相矛盾。"}, {"text": "参与", "is_correct": false, "explanation": "配价：“参与”的宾语应是活动或事件，不能直接以“科研工作者”作宾语。"}], "explanations": {"协助": "协助：辅助科研工作者梳理文献，与后文“认知协作者”的角色相合。", "监督": "语义：“监督”是监管他人，与“认知协作者”的角色相反。", "阻碍": "语义：“阻碍”是妨碍，与“提取证据、提出建议”的助益功能相矛盾。", "参与": "配价：“参与”的宾语应是活动或事件，不能直接以“科研工作者”作宾语。"}, "sentence_index": 0, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈始终协助我的选择。", "explanation": "这里应该用〈支持〉。协助指帮别人完成具体的工作或活动，不用于对选择表态；支持可以表示站在某人一边。"}, {"text": "妈妈每天协助我睡觉。", "explanation": "这里应该用〈哄〉。协助指帮别人完成具体工作或活动，不用于哄孩子入睡这类照料。"}, {"text": "我们要协助国家的利益。", "explanation": "这里应该用〈维护〉。协助是帮别人完成事务，利益需要的是维护，不能说协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协助", "is_correct": true, "explanation": "协助：公司派人帮我们完成项目，正合语境。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”是妨碍，与“派人来帮忙”的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽的态度，与派人帮忙的正面语境不符。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”的宾语应是物体，“我们做这个项目”不能作其宾语。"}], "explanations": {"协助": "协助：公司派人帮我们完成项目，正合语境。", "阻止": "语义：“阻止”是妨碍，与“派人来帮忙”的语境相反。", "嘲笑": "语义：“嘲笑”带有讥讽的态度，与派人帮忙的正面语境不符。", "搬运": "配价：“搬运”的宾语应是物体，“我们做这个项目”不能作其宾语。"}, "sentence_index": 6, "correct_answer": "协助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们协助远道而来的朋友吃了一顿饭。", "explanation": "这里应该用〈招待〉。协助是帮对方完成工作或事务，请客吃饭应说招待，不能说协助。"}, {"text": "他协助了伤心的朋友。", "explanation": "这里应该用〈安慰〉。协助指帮别人完成具体工作，不用于安抚情绪。"}, {"text": "老板协助员工的身体健康。", "explanation": "这里应该用〈关心〉。协助的对象是工作或事务，身体健康不能被协助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他协助我了两次。", "corrected_sentence": "他协助了我两次。", "error_description": "错误：“了”放在宾语“我”之后。正确：“协助了我”，“了”紧跟动词“协助”，表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是协助做我家务。", "corrected_sentence": "他总是协助我做家务。", "error_description": "错误：“我”被放到了“做”后面，“做我家务”不成立。正确：“协助我做家务”，“我”是“协助”的对象，“做家务”是被协助的内容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
