INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20025, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指进行科学或学术方面的研究活动。", "primary_collocate": null, "pronunciation": "kē yán", "ipa": "kʰɤ˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "例如，在协助做科研的人梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "科研", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他在大学做科研已经十年了。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司每年投入很多钱做科研。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科研需要耐心，也需要好的设备。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视科研。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她白天上课，晚上做科研。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的科研水平很高。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科研经费不够，项目只好停下来。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃了高薪工作，回国搞科研。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科研让我们了解了更多宇宙的知识。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科研人员", "label": "复合词"}, {"form": "科研工作", "label": "复合词"}, {"form": "科研成果", "label": "复合词"}], "register": "中性", "sense_fingerprint": "科研：科学或学术研究活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科研", "is_correct": true, "explanation": "科研：进行科学研究，“做科研的人”正合语境，与梳理文献相合。"}, {"text": "体育", "is_correct": false, "explanation": "语义：“做体育的人”指从事体育的人，与梳理跨学科文献的语境不符。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“做烹饪的人”指厨师一类，不能与梳理跨学科文献搭配。"}, {"text": "外交", "is_correct": false, "explanation": "语义：“做外交的人”指外交人员，与文献研究的语境不符。"}], "explanations": {"科研": "科研：进行科学研究，“做科研的人”正合语境，与梳理文献相合。", "体育": "语义：“做体育的人”指从事体育的人，与梳理跨学科文献的语境不符。", "烹饪": "搭配：“做烹饪的人”指厨师一类，不能与梳理跨学科文献搭配。", "外交": "语义：“做外交的人”指外交人员，与文献研究的语境不符。"}, "sentence_index": 0, "correct_answer": "科研"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在农村做了一只科研。", "explanation": "这里应该用〈项〉。“只”用于动物等，科研是活动，应说“一项科研”。"}, {"text": "这是一位很好的科研。", "explanation": "这里应该用〈项〉。“位”用于人，科研是活动，应说“一项科研”。"}, {"text": "这家公司投入了一座很大的科研。", "explanation": "这里应该用〈项〉。“座”用于建筑、山峰等大型物体，科研是活动，应说“一项科研”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科研", "is_correct": true, "explanation": "科研：学校在科学研究方面的水平，正合语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“水平”用于能力、质量，不说“天气水平”。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：影子是光线形成的暗影，不能用“水平”来评价学校。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”属于身体特征，不能说学校的“体重水平很高”。"}], "explanations": {"科研": "科研：学校在科学研究方面的水平，正合语境。", "天气": "搭配：“水平”用于能力、质量，不说“天气水平”。", "影子": "搭配：影子是光线形成的暗影，不能用“水平”来评价学校。", "体重": "体貌：“体重”属于身体特征，不能说学校的“体重水平很高”。"}, "sentence_index": 6, "correct_answer": "科研"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师有一张很好的科研。", "explanation": "这里应该用〈项〉。“张”用于纸张、桌子等，科研是活动，应说“一项科研”。"}, {"text": "这是一台很好的科研。", "explanation": "这里应该用〈项〉。“台”用于机器，科研是活动，应说“一项科研”。"}, {"text": "我们在会上做了一封科研。", "explanation": "这里应该用〈项〉。“封”用于信件，科研是活动，应说“一项科研”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只科研很重要。", "corrected_sentence": "这项科研很重要。", "error_description": "错误：“科研”作名词计量时应用“项”，“只”用于动物等，不能用于科研这类活动。正确：“这项科研”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些很科研人员每天都很努力。", "corrected_sentence": "这些科研人员每天都很努力。", "error_description": "错误：“很”不能插在“科研人员”的“科研”前修饰名词性成分。正确：“这些科研人员”，“科研”直接修饰“人员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
