INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或工具整理头发、毛羽等，使顺畅。", "primary_collocate": null, "pronunciation": "shū lǐ", "ipa": "ʂu˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "例如，在帮母亲打理长发时，她一缕一缕地梳理，直到每根头发都顺滑整齐，这比任何护理都更能让人安心。", "target_word": "梳理", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "妈妈在给女儿梳理长长的头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上起来，他先梳理一下头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟用嘴梳理自己的羽毛。", "target_word": "梳理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她坐在镜子前，慢慢梳理着头发。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风把头发吹乱了，我用手指梳理了几下。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫舔着爪子，梳理自己身上的毛。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理发师小心地梳理客人的头发，然后剪短。", "target_word": "梳理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的白头发很乱，我帮她梳理整齐。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡，她用梳子梳理湿头发。", "target_word": "梳理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "梳理了", "label": "完成体"}, {"form": "梳理着", "label": "持续体"}, {"form": "梳理过", "label": "经历体"}, {"form": "梳理梳理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用手指或梳子把头发、羽毛等理顺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梳理", "is_correct": true, "explanation": "正确：梳理（shū lǐ），用手或梳子把头发、羽毛理顺。"}, {"text": "树立", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，树立意思是建立，与头发无关。"}, {"text": "数理", "is_correct": false, "explanation": "shù 与 shū 声调不同，数理指数学和物理，与整理头发无关。"}, {"text": "疏离", "is_correct": false, "explanation": "lí（第二声）与 lǐ（第三声）声调不同，疏离意思是关系疏远，与头发无关。"}], "explanations": {"梳理": "正确：梳理（shū lǐ），用手或梳子把头发、羽毛理顺。", "树立": "shù（第四声）与 shū（第一声）声调不同，树立意思是建立，与头发无关。", "数理": "shù 与 shū 声调不同，数理指数学和物理，与整理头发无关。", "疏离": "lí（第二声）与 lǐ（第三声）声调不同，疏离意思是关系疏远，与头发无关。"}, "sentence_index": null, "correct_answer": "梳理"}, "level_3": {"options": [{"text": "梳理", "is_correct": true, "explanation": "梳理：用梳子或手指一缕一缕理顺头发，正合语境。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽种植物，不能用于理顺头发，与句意不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于清除脏物，不用于理顺头发。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，头发不能被煮，与句意不符。"}], "explanations": {"梳理": "梳理：用梳子或手指一缕一缕理顺头发，正合语境。", "种植": "语义：种植是栽种植物，不能用于理顺头发，与句意不符。", "打扫": "搭配：“打扫”用于清除脏物，不用于理顺头发。", "煮": "语义：“煮”是烹饪动作，头发不能被煮，与句意不符。"}, "sentence_index": 0, "correct_answer": "梳理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把房间梳理得很干净。", "explanation": "这里应该用〈整理〉。整理可用于房间、物品，梳理只用于理顺头发、羽毛等，不用于房间。"}, {"text": "她用毛巾梳理干头发。", "explanation": "这里应该用〈擦〉。毛巾用于擦干，梳理是用梳子或手指理顺，不用于吸干水分。"}, {"text": "她用肥皂梳理脏衣服。", "explanation": "这里应该用〈洗〉。洗用于去除污垢，梳理只表示理顺，不表示去脏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "梳理", "is_correct": true, "explanation": "梳理指用手或梳子理顺毛发，与猫用舌头整理身上的毛相符。"}, {"text": "熨", "is_correct": false, "explanation": "语义：熨是用熨斗烫平，猫不能熨自己身上的毛。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤需要火源加热，与猫舔毛的动作不符。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“舔着爪子”的动作与“剪”不搭配，猫整理毛不用剪。"}], "explanations": {"梳理": "梳理指用手或梳子理顺毛发，与猫用舌头整理身上的毛相符。", "熨": "语义：熨是用熨斗烫平，猫不能熨自己身上的毛。", "烤": "语义：烤需要火源加热，与猫舔毛的动作不符。", "剪": "搭配：“舔着爪子”的动作与“剪”不搭配，猫整理毛不用剪。"}, "sentence_index": 6, "correct_answer": "梳理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用砂纸梳理粗糙的木板。", "explanation": "这里应该用〈打磨〉。梳理只用于理顺头发、羽毛等，不用于打磨木板。"}, {"text": "他把树枝梳理得很整齐。", "explanation": "这里应该用〈修剪〉。修剪用于树枝、草木，梳理用于头发、羽毛等，不能用于树枝。"}, {"text": "他用刀梳理掉了胡子。", "explanation": "这里应该用〈刮〉。梳理只表示理顺，不表示去掉、剪掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把长发梳理很整齐。", "corrected_sentence": "她把长发梳理得很整齐。", "error_description": "补语标记错误：“很整齐”作结果补语时需要用“得”引出，应说“梳理得很整齐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在梳理过湿头发。", "corrected_sentence": "她正在梳理湿头发。", "error_description": "“过”表示经历，与“正在”表示进行冲突，应去掉“过”，说“她正在梳理湿头发。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
