INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了进行推理或论述，暂时认定某种情况为真的想法或前提。", "primary_collocate": null, "pronunciation": "jiǎ shè", "ipa": "tɕja˨˩˦ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "假设", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个假设很有意思。", "target_word": "假设", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师请我们先提出一个假设。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做实验以前，我们要先有假设。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个假设后来被实验证明是对的。", "target_word": "假设", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他的假设没有证据，所以大家不同意。", "target_word": "假设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果假设错了，结论就不对。", "target_word": "假设", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "科学家先提出假设，再做实验验证。", "target_word": "假设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一个假设，还不是事实。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生用数据检验自己的假设。", "target_word": "假设", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个假设", "label": "量词"}, {"form": "假設", "label": "繁体"}], "register": "中性", "sense_fingerprint": "推理或研究中暂时认定为真的前提或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "假设", "is_correct": true, "explanation": "正确：假设是研究中暂时认定为真的前提，可以被提取，与“实验证据”配合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：文献中提取的应是前提与证据等学术内容，“颜色”与此无关，句意说不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“提取”的对象应是学术内容，“钥匙”与此无关，句意说不通。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“提取”通常接要点、数据、证据，不接“名声”。"}], "explanations": {"假设": "正确：假设是研究中暂时认定为真的前提，可以被提取，与“实验证据”配合。", "颜色": "语义：文献中提取的应是前提与证据等学术内容，“颜色”与此无关，句意说不通。", "钥匙": "语义：“提取”的对象应是学术内容，“钥匙”与此无关，句意说不通。", "名声": "搭配：“提取”通常接要点、数据、证据，不接“名声”。"}, "sentence_index": 0, "correct_answer": "假设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假设很有创意，要在下个月实施。", "explanation": "这里应该用〈设想〉。设想是对未来做法的构想，可以付诸实施；假设是用来推理论证的前提，不能“实施”。"}, {"text": "假设明天下雨，我们就取消野餐。", "explanation": "这里“假设”表示“如果”，是连词用法，不是名词“假设”指推理论证前提的意思。"}, {"text": "我们先制定假设，再开始实验。", "explanation": "这里应该用〈计划〉。制定的是计划或方案，假设应说“提出”，不能“制定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假设", "is_correct": true, "explanation": "正确：假设是暂时认定为真的前提，“如果……错了，结论就不对”正说明它的作用。"}, {"text": "口味", "is_correct": false, "explanation": "语义：“口味”不是推理的前提，“如果口味错了，结论就不对”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装东西的器物，不是推理的前提，“如果书包错了，结论就不对”说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是日用物品，不能作为推理的前提，“如果雨伞错了，结论就不对”说不通。"}], "explanations": {"假设": "正确：假设是暂时认定为真的前提，“如果……错了，结论就不对”正说明它的作用。", "口味": "语义：“口味”不是推理的前提，“如果口味错了，结论就不对”说不通。", "书包": "语义：“书包”是装东西的器物，不是推理的前提，“如果书包错了，结论就不对”说不通。", "雨伞": "语义：“雨伞”是日用物品，不能作为推理的前提，“如果雨伞错了，结论就不对”说不通。"}, "sentence_index": 6, "correct_answer": "假设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他算出了这道题的假设。", "explanation": "这里应该用〈答案〉。算出的是答案或结果；假设是尚未证实的前提，不能“算出”。"}, {"text": "这个假设可以降低成本。", "explanation": "这里应该用〈方案〉。方案是可以付诸实施的做法，能降低成本；假设是推理论证的前提，不能用来降低成本。"}, {"text": "学生用假设证明自己的观点。", "explanation": "这里应该用〈数据〉。证明需要已确认的证据，假设尚未证实，不能用来证明观点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了一只新的假设。", "corrected_sentence": "他提出了一个新的假设。", "error_description": "错误：量词“只”用错。“假设”是抽象名词，量词应用“个”；“只”多用于动物或成对的小物件。正确：他提出了一个新的假设。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把假设需要我们认真检验。", "corrected_sentence": "这个假设需要我们认真检验。", "error_description": "错误：量词“把”用错。“假设”不是可以手拿的器具，量词应用“个”。正确：这个假设需要我们认真检验。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于方法的理论体系，研究如何认识世界和改造世界的根本方法。", "primary_collocate": null, "pronunciation": "fāng fǎ lùn", "ipa": "faŋ˥ fa˨˩˦ lwən˥˩", "syllable_count": 3, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "方法论", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这本书讲的是科学方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上介绍了新的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的方法论，会得到不同的结果。", "target_word": "方法论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学的是哲学，常常谈方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授的方法论很有名。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花了十年时间，终于总结出一套认识世界的方法论。", "target_word": "方法论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位科学家的方法论完全不同。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的方法论能帮人少走弯路。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门课讲历史研究的方法论。", "target_word": "方法论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套方法论", "label": "量词"}, {"form": "方法論", "label": "繁体"}], "register": "书面", "sense_fingerprint": "关于认识和改造世界的方法的理论体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是关于方法的理论体系，可以产生“冲突”，与前文“识别”相合。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：文献研究中的冲突指观点、方法或证据之间的对立，“旋律冲突”与此无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，用在这样的学术描述中不协调。"}, {"text": "面貌", "is_correct": false, "explanation": "搭配：“冲突”多指观点、利益或目标之间的对立，不说“面貌冲突”。"}], "explanations": {"方法论": "正确：方法论是关于方法的理论体系，可以产生“冲突”，与前文“识别”相合。", "旋律": "语义：文献研究中的冲突指观点、方法或证据之间的对立，“旋律冲突”与此无关。", "玩意儿": "语域：“玩意儿”是口语，用在这样的学术描述中不协调。", "面貌": "搭配：“冲突”多指观点、利益或目标之间的对立，不说“面貌冲突”。"}, "sentence_index": 0, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法论解释了行星为什么绕太阳转。", "explanation": "这里应该用〈理论〉。理论用于解释现象；方法论是研究方法的理论体系，不能用来解释行星的运动。"}, {"text": "这套方法论修好了我的自行车。", "explanation": "这里应该用〈工具〉。修车要靠扳手等工具；方法论是理论体系，不能用来修车。"}, {"text": "他把方法论洗干净，放进冰箱。", "explanation": "这里应该用〈碗〉。碗可以洗，也能放进冰箱；方法论是抽象的理论，没有实体，不能当作器物处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法论", "is_correct": true, "explanation": "正确：方法论是认识世界的方法的理论，“研究……的人，想知道怎样认识世界”正相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“总结出”的对象应是理论或规律，“味道”无法被总结为认识世界的方法，句意不通。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：“认识世界的”修饰的应是理论或方法，“鞋码”只是尺寸，不能被总结出来，句意不通。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”是外在的形式，不是可以总结出的认识方法，“总结出一套……包装”句意不通。"}], "explanations": {"方法论": "正确：方法论是认识世界的方法的理论，“研究……的人，想知道怎样认识世界”正相合。", "味道": "语义：“总结出”的对象应是理论或规律，“味道”无法被总结为认识世界的方法，句意不通。", "鞋码": "语义：“认识世界的”修饰的应是理论或方法，“鞋码”只是尺寸，不能被总结出来，句意不通。", "包装": "语义：“包装”是外在的形式，不是可以总结出的认识方法，“总结出一套……包装”句意不通。"}, "sentence_index": 6, "correct_answer": "方法论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课的方法论很甜，同学们都爱吃。", "explanation": "这里应该用〈糖果〉。糖果有甜味、可以吃；方法论是抽象的理论，没有味道，也不能吃。"}, {"text": "这套方法论很重，我搬不动。", "explanation": "这里应该用〈石头〉。石头有重量，搬得动或搬不动；方法论是抽象的理论，没有重量，不能这样形容。"}, {"text": "他用方法论把门擦干净了。", "explanation": "这里应该用〈抹布〉。擦门要用抹布等清洁用具；方法论是理论体系，不能用来擦门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的研究遵循一颗严谨的方法论。", "corrected_sentence": "他的研究遵循一套严谨的方法论。", "error_description": "错误：量词“颗”用错。“颗”用于颗粒状的小物，方法论是抽象的理论体系，应用“套”。正确：他的研究遵循一套严谨的方法论。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这套方法论讲完着。", "corrected_sentence": "老师把这套方法论讲完了。", "error_description": "体标错误：“讲完”是结果补语，表示动作已完成，应接完成体“了”；“着”表示持续状态，与已完成的结果不相容。正确：老师把这套方法论讲完了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指带有尝试性质的行为或态度，目的是观察结果或对方反应。", "primary_collocate": null, "pronunciation": "shì tàn xìng", "ipa": "ʂɻ̩˥˩ tʰan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "试探性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他先问了一个试探性的问题，想看看老板怎么想。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司先做了试探性的调整，再看客户有什么反应。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试探性地问我：“你想不想换工作？”", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是试探性的做法，大家不用太紧张。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用试探性的语气说话，怕朋友不高兴。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先做了一个试探性的小测验，看看学生会不会。", "target_word": "试探性", "complexity_tier": "T3", "furigana": "lǎo shī xiān zuò le yí gè shì tàn xìng de xiǎo cè yàn, kàn kan xué shēng huì bu huì.", "sentence_source": "generated"}, {"text": "这次试探性的投票，结果会决定我们下一步怎么做。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子试探性地碰了碰小狗，发现它不咬人。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店先卖少量新产品，这是试探性的销售。", "target_word": "试探性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "带有尝试性质、用来观察反应的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "试探性", "is_correct": true, "explanation": "正确：“试探性”修饰“建议”，表示带有尝试性质的建议，与前文“融合路径”的谨慎提议相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”说的是说话风格，修饰“融合路径”的建议时，与前文严谨的科研分析语境冲突。"}, {"text": "老掉牙", "is_correct": false, "explanation": "语域：“老掉牙”是口语色彩很强的说法，与这段书面化的学术表述不合。"}, {"text": "圆滚滚", "is_correct": false, "explanation": "体貌：“圆滚滚”描述外形，不能用来修饰“建议”这样的抽象事物。"}], "explanations": {"试探性": "正确：“试探性”修饰“建议”，表示带有尝试性质的建议，与前文“融合路径”的谨慎提议相符。", "幽默": "语义：“幽默”说的是说话风格，修饰“融合路径”的建议时，与前文严谨的科研分析语境冲突。", "老掉牙": "语域：“老掉牙”是口语色彩很强的说法，与这段书面化的学术表述不合。", "圆滚滚": "体貌：“圆滚滚”描述外形，不能用来修饰“建议”这样的抽象事物。"}, "sentence_index": 0, "correct_answer": "试探性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大桥的承重是试探性的，已经通车多年。", "explanation": "这里应该用〈确定〉。承重是既定的工程数值，“试探性”指先试着做，不能用来形容它。"}, {"text": "他的身高是试探性的，已经有一米八了。", "explanation": "“试探性”形容做事的尝试态度，身高是固定的属性，不能用它来形容。"}, {"text": "这份合同的签字是试探性的，双方都很确定。", "explanation": "签字是有法律效力的正式行为，不能说成“试探性”；“试探性”只用来形容尝试性的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试探性", "is_correct": true, "explanation": "正确：“试探性”修饰“小测验”，表示先试一下、观察学生反应的测验，与“看看学生会不会”相合。"}, {"text": "圆滚滚", "is_correct": false, "explanation": "体貌：“圆滚滚”描述外形，不能用来修饰“小测验”这样的事物。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”表示情绪，与“小测验”的做法和用途不合。"}, {"text": "绿油油", "is_correct": false, "explanation": "体貌：“绿油油”描述颜色和外观，不能用来修饰测验。"}], "explanations": {"试探性": "正确：“试探性”修饰“小测验”，表示先试一下、观察学生反应的测验，与“看看学生会不会”相合。", "圆滚滚": "体貌：“圆滚滚”描述外形，不能用来修饰“小测验”这样的事物。", "悲伤": "语义：“悲伤”表示情绪，与“小测验”的做法和用途不合。", "绿油油": "体貌：“绿油油”描述颜色和外观，不能用来修饰测验。"}, "sentence_index": 6, "correct_answer": "试探性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他试探性地一口气吃完了一整个西瓜，连皮都没剩。", "explanation": "这里应该用〈痛快〉。“试探性”只指先尝一尝，吃完一整个西瓜是尽兴地吃，应说“痛快”。"}, {"text": "他试探性地解开了全部谜题，给出了标准答案。", "explanation": "这里应该用〈确定〉。解开谜题并给出标准答案是确定的结果，“试探性”强调的是先试一试。"}, {"text": "这场比赛的冠军是试探性的，大家都已经认定了。", "explanation": "冠军是确定的结果，不能用“试探性”形容；“试探性”只用于尚在尝试的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她试探性的问了我一个问题。", "corrected_sentence": "她试探性地问了我一个问题。", "error_description": "错误在“试探性”后的“的”。“试探性”修饰动词“问”时要用“地”，“的”用于修饰名词，应改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们先做了一把试探性的改版，再观察用户的反应。", "corrected_sentence": "他们先做了一次试探性的改版，再观察用户的反应。", "error_description": "错误在“改版”前的量词。“改版”要用“次”计量，“把”用于有柄的器具，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
