INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过各种工具和方式，从大量信息中找到需要的内容。", "primary_collocate": null, "pronunciation": "xìn xī jiǎn suǒ", "ipa": "ɕin˥˩ ɕi˥ tɕjɛn˨˩˦ swɔ˨˩˦", "syllable_count": 4, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "信息检索", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "图书馆的老师教我们怎么做信息检索。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息检索可以帮你很快找到需要的资料。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做论文以前，我先学了信息检索的方法。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的信息检索工具能节省很多时间。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学过信息检索这门课。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息检索的结果太多，我不知道看哪一个。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的信息检索越来越方便了。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天做信息检索，帮公司找新闻和数据。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想找到准确的资料，要会用信息检索。", "target_word": "信息检索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从大量信息中查找所需内容的方法或技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息检索", "is_correct": true, "explanation": "正确：“信息检索”指从大量信息中查找所需内容的方法与工具，与“超越传统……工具的功能边界”相合。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“情绪”不是用来查找资料的工具，“传统情绪工具”说不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段书面化的学术叙述不合。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“风景”不能与“工具”搭配，不能说成“风景工具”。"}], "explanations": {"信息检索": "正确：“信息检索”指从大量信息中查找所需内容的方法与工具，与“超越传统……工具的功能边界”相合。", "情绪": "语义：“情绪”不是用来查找资料的工具，“传统情绪工具”说不通。", "玩意儿": "语域：“玩意儿”是口语说法，与这段书面化的学术叙述不合。", "风景": "搭配：“风景”不能与“工具”搭配，不能说成“风景工具”。"}, "sentence_index": 0, "correct_answer": "信息检索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做论文以前，我先学了一把信息检索。", "explanation": "这里应该用〈一种〉。“把”用于有柄的器具，“信息检索”是方法，不能用“把”来计量。"}, {"text": "做论文以前，我先把信息检索装进了箱子。", "explanation": "这里应该用〈资料〉。“装进箱子”针对具体的东西，“信息检索”是查找资料的方法，不能被装进箱子。"}, {"text": "做论文以前，我先给信息检索做了一顿饭。", "explanation": "“信息检索”是查找资料的方法，不能用来做饭；“做饭”需要食材和厨具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息检索", "is_correct": true, "explanation": "正确：“信息检索”指查找资料的过程，它的结果可能很多，与“结果太多”相合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”是饮品，不能有可以挑选的“结果”。"}, {"text": "胃口", "is_correct": false, "explanation": "搭配：“胃口”指食欲，不能说“胃口的结果”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是情绪状态，没有可以挑选的“结果”。"}], "explanations": {"信息检索": "正确：“信息检索”指查找资料的过程，它的结果可能很多，与“结果太多”相合。", "咖啡": "语义：“咖啡”是饮品，不能有可以挑选的“结果”。", "胃口": "搭配：“胃口”指食欲，不能说“胃口的结果”。", "心情": "语义：“心情”是情绪状态，没有可以挑选的“结果”。"}, "sentence_index": 6, "correct_answer": "信息检索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的信息检索很合身。", "explanation": "这里应该用〈尺码〉。“合身”形容衣服的尺码是否合适，“信息检索”是查找资料的方法，没有尺码。"}, {"text": "这首歌的信息检索很好听。", "explanation": "这里应该用〈旋律〉。“好听”形容的是声音本身，应说“这首歌的旋律很好听”；“信息检索”是查找资料的方法。"}, {"text": "他每天吃信息检索，身体很棒。", "explanation": "“信息检索”不能吃，“吃”只能搭配食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期学了一把信息检索方法。", "corrected_sentence": "他这学期学了一种信息检索方法。", "error_description": "错误在“信息检索”前的量词。它是方法，应用“种”计量；“把”用于有柄的器具，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的信息检索快很，几分钟就找到了。", "corrected_sentence": "他的信息检索很快，几分钟就找到了。", "error_description": "错误在“很”与“快”的顺序。程度副词“很”要放在形容词“快”前，说“很快”，不说“快很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确。“远离”与“趋近”构成反义，指距离越来越远。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与“趋近”的距离义没有反义关系。"}, {"text": "编织", "is_correct": false, "explanation": "无关：“编织”指把线或材料交错做成物品，与距离变化无关。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清除污物，与“趋近”的空间变化无反义关系。"}], "correct_answer": "远离", "explanations": {"远离": "正确。“远离”与“趋近”构成反义，指距离越来越远。", "收藏": "无关：“收藏”指保存物品，与“趋近”的距离义没有反义关系。", "编织": "无关：“编织”指把线或材料交错做成物品，与距离变化无关。", "打扫": "无关：“打扫”指清除污物，与“趋近”的空间变化无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确。“远离”与“趋近”构成反义，指距离越来越远。"}, {"text": "装饰", "is_correct": false, "explanation": "无关：“装饰”指使事物美观，与“趋近”的距离义没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "无关：“翻译”指转换语言文字，与空间变化无关。"}, {"text": "运输", "is_correct": false, "explanation": "无关：“运输”指把物品从一处送到另一处，不构成与“趋近”的反义。"}], "correct_answer": "远离", "explanations": {"远离": "正确。“远离”与“趋近”构成反义，指距离越来越远。", "装饰": "无关：“装饰”指使事物美观，与“趋近”的距离义没有反义关系。", "翻译": "无关：“翻译”指转换语言文字，与空间变化无关。", "运输": "无关：“运输”指把物品从一处送到另一处，不构成与“趋近”的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接近，靠近。", "primary_collocate": null, "pronunciation": "qū jìn", "ipa": "tɕʰy˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "趋近", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "火车慢慢趋近车站，大家都站了起来。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，温度趋近零度。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个数越算越趋近，差别只有一点点。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船趋近小岛时，我们看见了灯光。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩正在趋近全班第一名。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机趋近机场，开始慢慢降低高度。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着时间过去，两家公司的看法趋近了。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟一点一点趋近桌上的面包。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格趋近成本时，商店就不赚钱了。", "target_word": "趋近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趋近了", "label": "体标"}, {"form": "趋近过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向某处或某种状态接近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趋近", "is_correct": true, "explanation": "正确。趋近（qū jìn）指接近、靠近。"}, {"text": "拘禁", "is_correct": false, "explanation": "jū（第一声）与 qū 声母不同（j 与 q），意思是限制人身自由，不是靠近。"}, {"text": "曲径", "is_correct": false, "explanation": "jìng 与 jìn 韵尾不同（-ng 与 -n），意思是弯曲的小路。"}, {"text": "去尽", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是消失得干干净净。"}, {"text": "取尽", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是全部拿走、用完。"}], "explanations": {"趋近": "正确。趋近（qū jìn）指接近、靠近。", "拘禁": "jū（第一声）与 qū 声母不同（j 与 q），意思是限制人身自由，不是靠近。", "曲径": "jìng 与 jìn 韵尾不同（-ng 与 -n），意思是弯曲的小路。", "去尽": "qù（第四声）与 qū（第一声）声调不同，意思是消失得干干净净。", "取尽": "qǔ（第三声）与 qū（第一声）声调不同，意思是全部拿走、用完。"}, "sentence_index": null, "correct_answer": "趋近"}, "level_3": {"options": [{"text": "趋近", "is_correct": true, "explanation": "正确。“趋近于”表示向某种状态靠拢，与前句“超越功能边界”的递进语气相合。"}, {"text": "停留", "is_correct": false, "explanation": "语义：“停留”指停在某处不再前进，与前句“已超越功能边界”相矛盾。"}, {"text": "陷于", "is_correct": false, "explanation": "语义：“陷于”指落入某种困境，与前句“已超越功能边界”相矛盾。"}, {"text": "限", "is_correct": false, "explanation": "语义：“限于”指局限在某个范围内，与“已超越边界”的方向相反。"}], "explanations": {"趋近": "正确。“趋近于”表示向某种状态靠拢，与前句“超越功能边界”的递进语气相合。", "停留": "语义：“停留”指停在某处不再前进，与前句“已超越功能边界”相矛盾。", "陷于": "语义：“陷于”指落入某种困境，与前句“已超越功能边界”相矛盾。", "限": "语义：“限于”指局限在某个范围内，与“已超越边界”的方向相反。"}, "sentence_index": 0, "correct_answer": "趋近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每次考试都趋近三个小时才交卷。", "explanation": "这里应该用〈用〉。趋近指朝某个目标靠拢，不能用来计算时长。"}, {"text": "他看见一条蛇就趋近了，吓得大叫起来。", "explanation": "这里应该用〈后退〉。看见蛇吓得大叫，应当后退远离，不会趋近。"}, {"text": "他趋近了一句话也不说，只是盯着窗外。", "explanation": "这里应该用〈说〉。趋近是靠近，不能接“一句话”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋近", "is_correct": true, "explanation": "正确。“飞机趋近机场”指飞机慢慢接近机场，与后句“慢慢降低高度”相合。"}, {"text": "冲向", "is_correct": false, "explanation": "语义：“冲向”指猛然奔去，与后句“慢慢降低高度”相矛盾。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”指距离变远，与“趋近”相反，与后句“慢慢降低高度”的降落过程相矛盾。"}, {"text": "撞向", "is_correct": false, "explanation": "语义：“撞向”指猛烈地撞过去，与“慢慢”的节奏相矛盾。"}], "explanations": {"趋近": "正确。“飞机趋近机场”指飞机慢慢接近机场，与后句“慢慢降低高度”相合。", "冲向": "语义：“冲向”指猛然奔去，与后句“慢慢降低高度”相矛盾。", "远离": "语义：“远离”指距离变远，与“趋近”相反，与后句“慢慢降低高度”的降落过程相矛盾。", "撞向": "语义：“撞向”指猛烈地撞过去，与“慢慢”的节奏相矛盾。"}, "sentence_index": 6, "correct_answer": "趋近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一看见老师就趋近了，吓得连话都说不出来。", "explanation": "这里应该用〈后退〉。见到老师吓得说不出话，应当后退远离，不会趋近。"}, {"text": "我家趋近地铁站，走路五分钟就到。", "explanation": "这里表示位置相近、距离不远，应该用〈临近〉。趋近强调朝目标移动靠拢的过程，不用来说房子与地点的静态位置关系。"}, {"text": "小猫突然趋近了桌子，把杯子碰倒了。", "explanation": "这里表示“猛然靠近”的意思。趋近强调慢慢靠拢的过程，不能用于瞬间发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "邮车慢慢趋近到村口。", "corrected_sentence": "邮车慢慢趋近了村口。", "error_description": "错误：“趋近”后多加了“到”。正确：“趋近”本身已表示靠近，后面直接带处所宾语，写作“趋近了村口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "探险队曾经趋近着那座雪山。", "corrected_sentence": "探险队曾经趋近过那座雪山。", "error_description": "错误：“着”表示持续的状态，与表示经历的“曾经”不搭配。正确：应用经历体“过”，写作“趋近过那座雪山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
