INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20035, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指软件或硬件能够在不同的操作系统或平台上运行，无需额外修改。", "primary_collocate": null, "pronunciation": "kuà píng tái", "ipa": "kʰua˥˩ pʰiŋ˧˥ tʰaɪ˧˥", "syllable_count": 3, "sentences": [{"text": "当代理具备跨平台持续学习能力时，个体数据的隐私边界将面临根本性重构。", "target_word": "跨平台", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这款软件是跨平台的，手机和电脑上都能用。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司想开发一个跨平台的应用程序。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为这个游戏跨平台，所以朋友用手机也能和我玩。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨平台开发能节省很多时间和成本。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工具支持跨平台运行，系统不同也没问题。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学过一种跨平台的编程语言。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个浏览器是跨平台的，苹果和安卓都能装。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让更多人用上，团队选择了跨平台方案。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个聊天软件不跨平台，只能在苹果手机上用。", "target_word": "跨平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "软件或硬件可在不同操作系统或平台上运行而无需修改", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20035, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨平台", "is_correct": true, "explanation": "正确。“跨平台”修饰“持续学习能力”，指能力可在多个平台上运行，与句意相合。"}, {"text": "静态", "is_correct": false, "explanation": "语义：“静态”指不变动，与“持续学习”的含义相矛盾。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：“一次性”指只进行一次，与“持续”相矛盾。"}, {"text": "免费", "is_correct": false, "explanation": "搭配：“免费”修饰物品或服务，不修饰“能力”。"}], "explanations": {"跨平台": "正确。“跨平台”修饰“持续学习能力”，指能力可在多个平台上运行，与句意相合。", "静态": "语义：“静态”指不变动，与“持续学习”的含义相矛盾。", "一次性": "语义：“一次性”指只进行一次，与“持续”相矛盾。", "免费": "搭配：“免费”修饰物品或服务，不修饰“能力”。"}, "sentence_index": 0, "correct_answer": "跨平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跨平台上了火车，差点错过。", "explanation": "这里指穿过站台，与软件、硬件的运行环境无关，不是“跨平台”的意思。"}, {"text": "他跨平台向我借了钱，还没还。", "explanation": "这里应该用〈直接〉。跨平台只指软件或硬件的运行环境，不能用来形容借钱的方式。"}, {"text": "这个问题很跨平台，大家都不太懂。", "explanation": "这里应该用〈复杂〉。跨平台只说软件或硬件的运行环境，不用来形容问题的难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20035, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨平台", "is_correct": true, "explanation": "正确。“学过一种跨平台的编程语言”指这种语言能在不同操作系统上运行。"}, {"text": "手写", "is_correct": false, "explanation": "搭配：“手写”修饰文字或字迹，不修饰编程语言。"}, {"text": "感性", "is_correct": false, "explanation": "语义：“感性”指凭感觉、情感的，与编程语言的理性规则相矛盾。"}, {"text": "有声", "is_correct": false, "explanation": "搭配：“有声”多指书籍、影视等带声音的作品，不用于编程语言。"}], "explanations": {"跨平台": "正确。“学过一种跨平台的编程语言”指这种语言能在不同操作系统上运行。", "手写": "搭配：“手写”修饰文字或字迹，不修饰编程语言。", "感性": "语义：“感性”指凭感觉、情感的，与编程语言的理性规则相矛盾。", "有声": "搭配：“有声”多指书籍、影视等带声音的作品，不用于编程语言。"}, "sentence_index": 6, "correct_answer": "跨平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块面包跨平台，早餐和晚餐都能吃。", "explanation": "跨平台只用于软件或硬件的运行环境，不用来形容食物。"}, {"text": "这门课跨平台，学生要学好几门专业。", "explanation": "这里应该用〈跨学科〉。跨平台指软件或硬件在不同平台上运行，不用来说课程涉及多个学科。"}, {"text": "这把椅子跨平台，坐上去很舒服。", "explanation": "这里表示“舒适”的意思，应该用〈舒适〉。跨平台只指软件或硬件的运行范围，不能用来形容椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个播放器支持跨平台了使用，手机电脑都行。", "corrected_sentence": "这个播放器支持跨平台使用，手机电脑都行。", "error_description": "错误：“跨平台”是形容词，后面不能直接加动态助词“了”。正确：应写作“跨平台使用”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的产品是跨平台地，手机电脑都行。", "corrected_sentence": "他们的产品是跨平台的。", "error_description": "错误在“跨平台”后的“地”。“地”只用于修饰其后的动词；这里“跨平台”作谓语，后面没有动词，应去掉“地”，写作“是跨平台的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
