INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个代数结构之间保持运算关系的映射。", "primary_collocate": null, "pronunciation": "tóng tài", "ipa": "tʰʊŋ˧˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "在抽象代数中，保持运算的映射被称为两个代数结构之间的同态，它是研究结构对应关系的基本工具。", "target_word": "同态", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "老师讲了什么是群的同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个群之间有一个同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要证明这是同态，先看它保不保持运算。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同态能让我们比较两个不同的数学结构。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，同态是保持结构的映射。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在作业里写错了同态的定义。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个映射不是同态，因为它改变了运算结果。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学代数时，同态是一个很重要的概念。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天讨论了环之间的同态。", "target_word": "同态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "数学中两个对象之间保持结构的对应关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7108d65a-2525-4e71-b1c7-4278ac931cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建材，不能作为数学映射的名称，句子不通。"}, {"text": "同态", "is_correct": true, "explanation": "正确。“两个代数结构之间的同态”指保持运算的映射，与句中的定义相合。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地是地貌，不能指代数结构之间的映射，句子不通。"}, {"text": "老大", "is_correct": false, "explanation": "语域：“老大”是口语称呼，不能作为这种科技语境中的定语。"}], "explanations": {"水泥": "语义：水泥是建材，不能作为数学映射的名称，句子不通。", "同态": "正确。“两个代数结构之间的同态”指保持运算的映射，与句中的定义相合。", "草地": "语义：草地是地貌，不能指代数结构之间的映射，句子不通。", "老大": "语域：“老大”是口语称呼，不能作为这种科技语境中的定语。"}, "sentence_index": 0, "correct_answer": "同态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个数的余数相同，所以它们同态。", "explanation": "此处应用〈同余〉。“同余”指两个整数除以同一个模数后余数相同；“同态”是保持运算的映射，不用于说数的余数关系。"}, {"text": "计算出来，这两个空间的同态相同。", "explanation": "此处应用〈同调〉。“同调”是代数拓扑中区分空间的不变量，“同态”是保持运算的映射，不能用来说空间的不变量相同。"}, {"text": "我爸爸和我叔叔是同态的。", "explanation": "此处应用〈相似〉。“同态”指事物的结构或样子相同，多用于事物，不用于说人与人的亲缘关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "语法：副词“已经”不能作定语修饰“定义”，句子不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语法：副词“偶尔”不能作定语修饰“定义”，句子不通。"}, {"text": "同态", "is_correct": true, "explanation": "正确。“同态的定义”是数学作业的内容，“同态”作定语修饰“定义”。"}, {"text": "悄悄", "is_correct": false, "explanation": "语法：副词“悄悄”不能作定语修饰“定义”，句子不通。"}], "explanations": {"已经": "语法：副词“已经”不能作定语修饰“定义”，句子不通。", "偶尔": "语法：副词“偶尔”不能作定语修饰“定义”，句子不通。", "同态": "正确。“同态的定义”是数学作业的内容，“同态”作定语修饰“定义”。", "悄悄": "语法：副词“悄悄”不能作定语修饰“定义”，句子不通。"}, "sentence_index": 6, "correct_answer": "同态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个群是同态的，即两者之间一一对应，且保持运算。", "explanation": "此处应用〈同构〉。“一一对应”是同构的要求，同态不要求双射。"}, {"text": "这两个图形是同态的，即存在连续的一一对应，且逆映射也连续。", "explanation": "此处应用〈同胚〉。同态是代数中的概念，不涉及连续性；描述图形之间的连续对应要用“同胚”。"}, {"text": "这两个映射是同态的，即能通过连续形变互相变换。", "explanation": "此处应用〈同伦〉。“连续形变”描述的是同伦关系，同态是另一个概念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个映射是一只同态。", "corrected_sentence": "这个映射是一个同态。", "error_description": "量词错误：“同态”是抽象概念，应用“一个”。“只”用于动物、鸟类等，不能修饰“同态”。正确句为“这个映射是一个同态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们证明了这个映射同态。", "corrected_sentence": "我们证明了这个映射是同态。", "error_description": "漏字：“同态”作谓语须由系词“是”引出，缺少“是”。应改为“我们证明了这个映射是同态。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12292ff-a327-4564-a216-88e6b661bfb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
