INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物本身含有的性质、特点或特征。", "primary_collocate": null, "pronunciation": "shǔ xìng", "ipa": "ʂu˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "水的基本属性是透明、没有颜色。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属的属性之一是容易导电。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料有很多特殊的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个物品都有自己的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，老师讲了酸的属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先来看看这个东西有什么属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光的属性既像波，又像粒子。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料的哪些属性使它不容易坏？", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写出这种动物的两个主要属性。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的属性决定了东西的用途。", "target_word": "属性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种属性", "label": "量词"}, {"form": "一个属性", "label": "量词"}, {"form": "物理属性", "label": "复合"}, {"form": "屬性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物本身固有的性质、特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aaf44948-3a19-4076-a2d4-5078f32199aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：水的颜色不能是“透明”，且与后半句“没有颜色”矛盾。"}, {"text": "属性", "is_correct": true, "explanation": "属性指事物本身含有的性质、特点，此处说水的基本性质是透明、没有颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”说的是滋味，不能用“透明”来形容。"}, {"text": "功能", "is_correct": false, "explanation": "搭配：“功能”说的是作用，不说“是透明、没有颜色”。"}], "explanations": {"颜色": "语义：水的颜色不能是“透明”，且与后半句“没有颜色”矛盾。", "属性": "属性指事物本身含有的性质、特点，此处说水的基本性质是透明、没有颜色。", "味道": "语义：“味道”说的是滋味，不能用“透明”来形容。", "功能": "搭配：“功能”说的是作用，不说“是透明、没有颜色”。"}, "sentence_index": 0, "correct_answer": "属性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的属性很开朗。", "explanation": "这里应该用〈性格〉。属性指事物本身的性质，人的脾气品格要用性格。"}, {"text": "这种药的属性很大。", "explanation": "这里应该用〈作用〉。属性指事物固有的性质，药物产生的效果要用作用。"}, {"text": "这件衣服的属性很贵。", "explanation": "这里应该用〈价格〉。属性指事物本身的性质，商品卖多少钱要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外形", "is_correct": false, "explanation": "体貌：“外形”指外表的形状，不指光的波粒性质。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语，不合科学说明的书面语境。"}, {"text": "属性", "is_correct": true, "explanation": "属性指事物本身含有的性质，此处说光兼有波与粒子的性质。"}, {"text": "玩意", "is_correct": false, "explanation": "语域：“玩意”是口语，而且不指光的性质。"}], "explanations": {"外形": "体貌：“外形”指外表的形状，不指光的波粒性质。", "门道": "语域：“门道”是口语，不合科学说明的书面语境。", "属性": "属性指事物本身含有的性质，此处说光兼有波与粒子的性质。", "玩意": "语域：“玩意”是口语，而且不指光的性质。"}, "sentence_index": 6, "correct_answer": "属性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的属性很鲜艳。", "explanation": "这里应该用〈颜色〉。属性指事物本身的性质，花的色彩要用颜色。"}, {"text": "这首歌的属性很动听。", "explanation": "这里应该用〈旋律〉。“属性”指事物本身的性质，歌曲的曲调要用旋律。"}, {"text": "这台机器的属性很强。", "explanation": "这里应该用〈能力〉。属性指事物固有的性质，机器的本领要用能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块石头有一种特殊的属性们。", "corrected_sentence": "这块石头有一种特殊的属性。", "error_description": "“们”只用于指人的名词，“属性”是抽象名词，不能加“们”。错误形式：属性们；正确形式：属性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种金属有一只导电的属性。", "corrected_sentence": "这种金属有一种导电的属性。", "error_description": "“只”用于动物、物件等，不能用来数抽象的“属性”。错误形式：一只导电的属性；正确形式：一种导电的属性。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
