INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "表示截止到某个时间点。", "primary_collocate": null, "pronunciation": "jié zhì", "ipa": "tɕjɛ˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "截至昨天，已经有三百人报名了。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至今年六月，这家店已经开了五年。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至目前，我们还没有收到他的消息。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至下午五点，学生都交了作业。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至周五，图书馆借出了两千本书。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至上个月底，我一共存了一万块钱。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至昨晚，这部电影的票房已经超过一亿元。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至去年，这个城市有八所大学。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截至三月十号，已经有五十人报名了。", "target_word": "截至", "complexity_tier": "T3", "furigana": "jié zhì sān yuè shí hào, yǐ jīng yǒu wǔ shí rén bào míng le.", "sentence_source": "generated"}, {"text": "截至今天早上，雨还没有停。", "target_word": "截至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "截至目前", "label": "固定搭配"}], "register": "书面语", "sense_fingerprint": "截至|介词|截止到某个时间点（常用于统计、通知）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "截至", "is_correct": true, "explanation": "正确：“截至”表示截止到某个时间点，与“昨天”搭配，句意完整。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据或标准，与“昨天”这样的时间点不搭配。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”后面接对象，不能直接接“昨天”这样的时间词。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后面要接受处置的对象，不能接时间词。"}], "explanations": {"截至": "正确：“截至”表示截止到某个时间点，与“昨天”搭配，句意完整。", "按照": "语义：“按照”表示依据或标准，与“昨天”这样的时间点不搭配。", "对": "搭配：“对”后面接对象，不能直接接“昨天”这样的时间词。", "把": "配价：“把”后面要接受处置的对象，不能接时间词。"}, "sentence_index": 0, "correct_answer": "截至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "截至三天，大家一直在打扫教室。", "explanation": "这里应该用〈持续〉。截至只接某个时间点，不能表示一段时间。"}, {"text": "截至健康，我每天都跑步。", "explanation": "这里应该用〈为了〉。截至接时间点，不能表示目的；“为了健康”才表示目的。"}, {"text": "截至我，已经有三百人报名了。", "explanation": "这里应该用〈至于〉。至于用于引出话题，截至只接时间点，不能接人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "截至", "is_correct": true, "explanation": "正确：“截至”表示截止到某个时间点，与“昨晚”搭配，句意完整。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后面要接受处置的对象，不能接时间词。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，与“昨晚”这样的时间不搭配。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替他人做事，与票房的统计时间不搭配。"}], "explanations": {"截至": "正确：“截至”表示截止到某个时间点，与“昨晚”搭配，句意完整。", "把": "配价：“把”后面要接受处置的对象，不能接时间词。", "向": "语义：“向”表示方向或对象，与“昨晚”这样的时间不搭配。", "替": "语义：“替”表示代替他人做事，与票房的统计时间不搭配。"}, "sentence_index": 6, "correct_answer": "截至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "截至桌子，大家都坐好了。", "explanation": "这里应该用〈围着〉。截至只接时间点，不能接物品；表示位置要说“围着桌子”。"}, {"text": "截至一个小时，他一直在等公交车。", "explanation": "这里应该用〈持续〉。截至只接某个时间点，不能表示一段时间。"}, {"text": "截至晴天，我们就去爬山。", "explanation": "这里应该用〈如果〉。截至接的是时间点，“晴天”是条件，不能用截至来引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "截至在上周，我们班已经有五个人请假了。", "corrected_sentence": "截至上周，我们班已经有五个人请假了。", "error_description": "多余成分：“截至”是介词，后面直接接时间词，不能加“在”，应说“截至上周，我们班已经有……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "截至了今晚，大家都把作业交上来了。", "corrected_sentence": "截至今晚，大家都把作业交上来了。", "error_description": "时态标记错误：“截至”是介词，后面不能加“了”，应说“截至今晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
