INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "彼此关联；互相牵连。", "primary_collocate": null, "pronunciation": "xiāng guān", "ipa": "ɕiɑŋ˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "请把相关的材料交给老师。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟和肺病密切相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读的书都和历史相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想查一些相关的资料。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题与天气相关。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相关部门已经开始调查这件事。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习成绩和睡觉时间相关吗？", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我相关的情况。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多相关的图片。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有相关的新闻，你去看看。", "target_word": "相关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相关", "label": "否定"}, {"form": "相关性", "label": "复合"}, {"form": "相关部门", "label": "复合"}, {"form": "相關", "label": "繁体"}], "register": "书面", "sense_fingerprint": "彼此之间有关联、互相牵连", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aaf44948-3a19-4076-a2d4-5078f32199aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：材料没有甜味，“甜的材料”说不通。"}, {"text": "相关", "is_correct": true, "explanation": "相关作形容词，表示与任务彼此有关联，修饰“材料”正确。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容人或动物的性格，不用来形容材料。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：“暴躁”形容人的脾气，材料不能有脾气。"}], "explanations": {"甜": "语义：材料没有甜味，“甜的材料”说不通。", "相关": "相关作形容词，表示与任务彼此有关联，修饰“材料”正确。", "活泼": "语义：“活泼”形容人或动物的性格，不用来形容材料。", "暴躁": "语义：“暴躁”形容人的脾气，材料不能有脾气。"}, "sentence_index": 0, "correct_answer": "相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩相关得很好。", "explanation": "这里应该用〈相处〉。“相关”只说彼此有联系，人与人一起生活、往来要用相处。"}, {"text": "他很相关我，常常帮我做事。", "explanation": "这里应该用〈关心〉。“相关”说事物彼此有联系，人对人的挂念要用关心。"}, {"text": "他的鼻子很相关，闻得出很远的味道。", "explanation": "这里应该用〈灵〉。“相关”说事物彼此有联系，形容感官敏锐要用“灵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高", "is_correct": false, "explanation": "搭配：“高”说高低，时间要说长短，不说“时间高”。"}, {"text": "溜", "is_correct": false, "explanation": "语域：“溜”是口语，不合书面的问句。"}, {"text": "相关", "is_correct": true, "explanation": "相关表示两者有联系，此处问成绩与睡眠时间是否有关联。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说物体的厚度，不能用来说成绩和时间的关系。"}], "explanations": {"高": "搭配：“高”说高低，时间要说长短，不说“时间高”。", "溜": "语域：“溜”是口语，不合书面的问句。", "相关": "相关表示两者有联系，此处问成绩与睡眠时间是否有关联。", "厚": "语义：“厚”说物体的厚度，不能用来说成绩和时间的关系。"}, "sentence_index": 6, "correct_answer": "相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣相关得很暖和。", "explanation": "这里应该用〈保暖〉。“相关”只说彼此有联系，衣物的暖和程度要用“保暖”。"}, {"text": "两条河在这里相关了。", "explanation": "这里应该用〈相遇〉。“相关”只说彼此有联系，两条河汇到一处要用相遇。"}, {"text": "我们早已相关。", "explanation": "这里应该用〈相识〉。“相关”说事物有联系，早就认识的人要用相识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事和我没相关。", "corrected_sentence": "这件事和我不相关。", "error_description": "否定形容词“相关”要用“不”，说“不相关”。错误形式：没相关；正确形式：不相关。“没”一般用于动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两件事的情况地相关。", "corrected_sentence": "两件事的情况很相关。", "error_description": "修饰形容词“相关”的程度副词应用“很”，“地”是结构助词，不能直接放在形容词前。错误形式：地相关；正确形式：很相关。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc3610e4-7664-41da-9a0a-efa7ca591793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
