INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指心理状态良好，没有心理疾病，情绪稳定、能适应环境。", "primary_collocate": null, "pronunciation": "xīn lǐ jiàn kāng", "ipa": "ɕin˥ li˨˩˦ tɕjɛn˥˩ kʰaŋ˥", "syllable_count": 4, "sentences": [{"text": "他每天写日记，帮助自己保持心理健康。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校很重视学生的心理健康。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动对心理健康有好处。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近压力很大，心理健康出了问题。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡好觉有助于保持心理健康。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常和孩子聊天，关心他们的心理健康。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理健康和身体健康一样重要。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请医生给员工讲心理健康的知识。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母要多关注孩子的心理健康。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间玩手机会影响心理健康。", "target_word": "心理健康", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理健康教育", "label": "复合"}, {"form": "心理健康问题", "label": "复合"}], "register": "中性", "sense_fingerprint": "心理状态良好、没有心理疾病、情绪稳定并能适应环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心理健康", "is_correct": true, "explanation": "正确：“保持心理健康”指维持良好的心理状态，符合句意。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“保持水果”搭配不通，水果不是可以被“保持”的状态。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "语义：“蚂蚁”是动物，不能作为“保持”的对象，句意不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“钢琴”是乐器，不能与“保持”搭配作为自己的目标。"}], "explanations": {"心理健康": "正确：“保持心理健康”指维持良好的心理状态，符合句意。", "水果": "语义：“保持水果”搭配不通，水果不是可以被“保持”的状态。", "蚂蚁": "语义：“蚂蚁”是动物，不能作为“保持”的对象，句意不通。", "钢琴": "搭配：“钢琴”是乐器，不能与“保持”搭配作为自己的目标。"}, "sentence_index": 0, "correct_answer": "心理健康"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的是心理健康。", "explanation": "这里应该用〈心理学〉。“学的是”后接学科，心理健康指心理状态，不是学科名称。"}, {"text": "医生诊断他有严重的心理健康，需要治疗。", "explanation": "这里应该用〈心理障碍〉。心理健康指良好的心理状态，有病症要说心理障碍，不能说成“有心理健康”。"}, {"text": "他心理健康地跑完了马拉松。", "explanation": "这里应该用〈顺利〉。心理健康是名词，指心理状态，不能用“地”修饰动作；跑完马拉松应说“顺利地跑完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心理健康", "is_correct": true, "explanation": "正确：“心理健康”与“身体健康”并列，符合“一样重要”的句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：“汽油”与“身体健康”并列说“一样重要”，句意不通。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：“蜡烛”不能与“身体健康”并列，说它们“一样重要”没有意义。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“一样重要”要求主语是抽象事物或与健康相关的概念，“钢笔”是具体工具，不能这样用。"}], "explanations": {"心理健康": "正确：“心理健康”与“身体健康”并列，符合“一样重要”的句意。", "汽油": "语义：“汽油”与“身体健康”并列说“一样重要”，句意不通。", "蜡烛": "语义：“蜡烛”不能与“身体健康”并列，说它们“一样重要”没有意义。", "钢笔": "搭配：“一样重要”要求主语是抽象事物或与健康相关的概念，“钢笔”是具体工具，不能这样用。"}, "sentence_index": 6, "correct_answer": "心理健康"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他得了心理健康，需要住院治疗。", "explanation": "这里应该用〈精神病〉。“得了”后接疾病，心理健康指良好的心理状态，不是病名。"}, {"text": "这位运动员心理健康很强，能举起两百公斤。", "explanation": "这里应该用〈身体素质〉。能举起重物说明体能，心理健康不能用来说明力量。"}, {"text": "他去做心理健康，帮助调整情绪。", "explanation": "这里应该用〈心理咨询〉。“做”后接可以进行的活动，心理健康是状态，不能作为“做”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校每年都会检查学生地心理健康。", "corrected_sentence": "学校每年都会检查学生的心理健康。", "error_description": "错误：修饰名词“心理健康”时应用“的”，写成“地”不对。“地”用于修饰动词、形容词，“学生”修饰“心理健康”要用“的”，写作“学生的心理健康”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每天散步，心理健康有好处。", "corrected_sentence": "每天散步，对心理健康有好处。", "error_description": "错误：漏掉了介词“对”。“对心理健康有好处”引出受益对象，少了“对”，句子不成立。正确形式为“对心理健康有好处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
