INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将系统或产品设计成由独立、可互换的模块组成的方式。", "primary_collocate": null, "pronunciation": "mó kuài huà", "ipa": "mo˧˥ kʰuai˥˩ xua˥˩", "syllable_count": 3, "sentences": [{"text": "GitHub数据显示，截至2025年末，相关衍生项目已覆盖教育、心理健康、城市治理等十六个领域，其模块化设计允许多主体在不侵犯核心协议的前提下进行价值创新。", "target_word": "模块化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台电脑采用模块化设计，坏了可以换零件。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化让软件更容易修改。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的新手机用模块化的方法生产。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的模块化建造可以节省时间。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的好处是每个部分都能单独更换。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在研究汽车的模块化。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统的模块化做得很好。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化使大型程序更容易管理。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模块化的家具可以自由组合。", "target_word": "模块化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模块化设计", "label": "复合"}, {"form": "模块化生产", "label": "复合"}, {"form": "模組化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把系统或产品设计成由独立、可互换的模块组成的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模块化", "is_correct": true, "explanation": "正确。原句说“模块化设计”，指把系统设计成可互换的模块组合，符合句中“允许多主体在前提下创新”的语境。"}, {"text": "集中化", "is_correct": false, "explanation": "语义：集中化与“允许多主体参与价值创新”的意思相反，句中强调开放，不能说集中。"}, {"text": "封闭化", "is_correct": false, "explanation": "语义：封闭化会阻止多主体进入，与“允许多主体在不侵犯核心协议的前提下进行创新”相矛盾。"}, {"text": "单一化", "is_correct": false, "explanation": "搭配：“单一化”指事物变得单一，与“多主体进行价值创新”的语境搭配不通。"}], "explanations": {"模块化": "正确。原句说“模块化设计”，指把系统设计成可互换的模块组合，符合句中“允许多主体在前提下创新”的语境。", "集中化": "语义：集中化与“允许多主体参与价值创新”的意思相反，句中强调开放，不能说集中。", "封闭化": "语义：封闭化会阻止多主体进入，与“允许多主体在不侵犯核心协议的前提下进行创新”相矛盾。", "单一化": "搭配：“单一化”指事物变得单一，与“多主体进行价值创新”的语境搭配不通。"}, "sentence_index": 0, "correct_answer": "模块化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格很模块化。", "explanation": "这里把〈模块化〉当成“性格可以拆分、各部分可互换”的意思来形容人，但它只指系统或产品的设计方式。"}, {"text": "这款平板的外壳模块化，屏幕和主机无法拆分。", "explanation": "这里应该用〈一体化〉。模块化指各部分可拆分、可互换，与“无法拆分”相矛盾；合为一体才用一体化。"}, {"text": "这座山的模块化很陡峭。", "explanation": "这里应该用〈陡峭〉。模块化只指系统或产品的设计方式，不能用来形容山的形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模块化", "is_correct": true, "explanation": "正确。“研究汽车的模块化”指研究汽车的模块化设计，符合句意。"}, {"text": "口味", "is_correct": false, "explanation": "语义：汽车没有口味，“研究汽车的口味”在语义上不通。"}, {"text": "感情", "is_correct": false, "explanation": "语义：汽车是无生命的物体，不存在感情，句子不成立。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：“研究”的对象是汽车，“汽车的饮食”不能作为研究对象。"}], "explanations": {"模块化": "正确。“研究汽车的模块化”指研究汽车的模块化设计，符合句意。", "口味": "语义：汽车没有口味，“研究汽车的口味”在语义上不通。", "感情": "语义：汽车是无生命的物体，不存在感情，句子不成立。", "饮食": "搭配：“研究”的对象是汽车，“汽车的饮食”不能作为研究对象。"}, "sentence_index": 6, "correct_answer": "模块化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的模块化很可爱。", "explanation": "这里把〈模块化〉误当成“身体各部件可拆换”的意思来形容猫，但它只指系统或产品的设计方式，不能用于动物。"}, {"text": "这杯咖啡的模块化很浓。", "explanation": "这里把〈模块化〉误当成“味道浓淡”的意思来用，但它只指系统或产品的设计方式，不能形容咖啡。"}, {"text": "这几段代码模块化，改一处就得全部重写。", "explanation": "这里说的是代码互相紧密依赖（耦合）的状态，而模块化指各部分彼此独立、可单独修改，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个团队用模块化地方式设计产品。", "corrected_sentence": "这个团队用模块化的方式设计产品。", "error_description": "错误：“模块化”修饰名词“方式”时要用“的”，写成“地”不对。“地”用于修饰动词，应写作“模块化的方式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队把系统模块化很彻底。", "corrected_sentence": "这个团队把系统模块化得很彻底。", "error_description": "错误：“把系统模块化”后漏了补语标记“得”，应为“模块化得很彻底”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "正确。“禁止”与“允许”是反义词，“公司允许员工在家工作”的反面是“公司禁止员工在家工作”。"}, {"text": "购买", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "思考", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}, {"text": "搬运", "is_correct": false, "explanation": "与“允许”没有反义关系，只是同为动词的干扰项。"}], "correct_answer": "禁止", "explanations": {"禁止": "正确。“禁止”与“允许”是反义词，“公司允许员工在家工作”的反面是“公司禁止员工在家工作”。", "购买": "与“允许”没有反义关系，只是同为动词的干扰项。", "思考": "与“允许”没有反义关系，只是同为动词的干扰项。", "搬运": "与“允许”没有反义关系，只是同为动词的干扰项。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
