INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示同意、许可。", "primary_collocate": null, "pronunciation": "yǔn xǔ", "ipa": "yn˨˩˦ ɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师允许我们在课上用手机。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不允许我晚上出去玩。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸终于允许我养小狗了。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司允许员工在家工作。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不允许他喝酒。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理允许我明天请假。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校允许学生带水进教室。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板允许过我们提前下班。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的父母不允许她一个人去旅行。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师允许了他迟到。", "target_word": "允许", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "允许了", "label": "体标（了）"}, {"form": "允许过", "label": "体标（过）"}, {"form": "不允许", "label": "否定形式"}, {"form": "允許", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有权的人表示同意，让别人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "允许", "is_correct": true, "explanation": "正确。“老师允许我们在课上用手机”表示老师准许学生做某事，符合句意。"}, {"text": "承认", "is_correct": false, "explanation": "语义：“承认”的对象是事实，不能用来表示准许学生做某事。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”后接的是人或事，不能带“我们在课上用手机”这个兼语结构。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”表示拦住，句意是老师不让我们在课上用手机，与“允许”的准许义相反。"}], "explanations": {"允许": "正确。“老师允许我们在课上用手机”表示老师准许学生做某事，符合句意。", "承认": "语义：“承认”的对象是事实，不能用来表示准许学生做某事。", "感谢": "配价：“感谢”后接的是人或事，不能带“我们在课上用手机”这个兼语结构。", "阻止": "语义：“阻止”表示拦住，句意是老师不让我们在课上用手机，与“允许”的准许义相反。"}, "sentence_index": 0, "correct_answer": "允许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我允许他的建议。", "explanation": "这里应该用〈同意〉。“允许”表示准许某人做某事，不能直接以“建议”为宾语。"}, {"text": "我允许这本书。", "explanation": "这里把〈允许〉误当成“同意、接受某物”的意思，但它后面只能接可以做的动作，不能以“这本书”这样的物作宾语。"}, {"text": "一场大雨允许我们回家。", "explanation": "这里把〈允许〉误当成“使某事可能发生”的意思，但它只表示有权决定的人或机构准许，“大雨”不能这样作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "允许", "is_correct": true, "explanation": "正确。“学校允许学生带水进教室”表示学校准许学生做某事，符合句意。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：学校抱怨学生带水进教室，与“允许”表示准许的意思相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示取笑，不能表示准许学生带水进教室。"}, {"text": "同情", "is_correct": false, "explanation": "搭配：“同情”的对象是人的遭遇，不能接“带水进教室”这样的行为。"}], "explanations": {"允许": "正确。“学校允许学生带水进教室”表示学校准许学生做某事，符合句意。", "抱怨": "语义：学校抱怨学生带水进教室，与“允许”表示准许的意思相反。", "嘲笑": "语义：“嘲笑”表示取笑，不能表示准许学生带水进教室。", "同情": "搭配：“同情”的对象是人的遭遇，不能接“带水进教室”这样的行为。"}, "sentence_index": 6, "correct_answer": "允许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板允许了我们的眼泪。", "explanation": "这里把〈允许〉误当成“容纳、接受某种情绪”的意思，但它只能表示准许别人做某件事，不能用于“眼泪”。"}, {"text": "妈妈允许我感冒。", "explanation": "这里把〈允许〉误当成“任由某种状况发生”的意思，但它只表示准许别人做某件事，不能准许身体生病。"}, {"text": "我们允许了他的粗鲁，希望他改正。", "explanation": "这里应该用〈容忍〉。允许表示准许做某事，对不好的行为勉强接受要用容忍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校不允许了学生在教室里吃东西。", "corrected_sentence": "学校不允许学生在教室里吃东西。", "error_description": "错误：“了”不能紧跟在否定形式“不允许”之后，应去掉“了”，写作“学校不允许学生在教室里吃东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理允许了了我们提前走。", "corrected_sentence": "经理允许了我们提前走。", "error_description": "错误：“了”重复出现，“允许”后只能用一个“了”，应写作“经理允许了我们提前走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
