INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20051, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物中主要的、起决定作用的部分。", "primary_collocate": null, "pronunciation": "zhǔ tǐ", "ipa": "ʈʂu˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座楼的主体已经完工了。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的主体是用钢做的。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的主体分为三个部分。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业是这个地区经济的主体。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的主体盖好了，现在只差装修。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的主体是第二章到第五章。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收入的主体来自工资。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔的主体是石头，上面是木头。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "销售是公司业务的主体。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的主体是铁做的，很重。", "target_word": "主体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主体性", "label": "复合词"}, {"form": "主體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物里最主要、起决定作用的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "“主体”指楼的主要结构，与“已经完工”搭配，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“完工”用于工程或建筑，不能说楼的颜色完工。"}, {"text": "作者", "is_correct": false, "explanation": "语义：楼的作者是人，不是楼的组成部分，不能说“完工”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：楼没有味道，“味道”不能与“完工”搭配。"}], "explanations": {"主体": "“主体”指楼的主要结构，与“已经完工”搭配，符合语境。", "颜色": "搭配：“完工”用于工程或建筑，不能说楼的颜色完工。", "作者": "语义：楼的作者是人，不是楼的组成部分，不能说“完工”。", "味道": "搭配：楼没有味道，“味道”不能与“完工”搭配。"}, "sentence_index": 0, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的主体是他。", "explanation": "这里应该用〈主人〉。“主体”指事物中主要的部分，不指所有者，说房子的所有人要用“主人”。"}, {"text": "他的主体很健康，每天都锻炼。", "explanation": "这里应该用〈身体〉。“主体”指事物中主要的部分，不指人的身体，形容人的身体健康要用“身体”。"}, {"text": "这次会议的主体是老王。", "explanation": "这里应该用〈主席〉。“主体”指事物的主要部分，不指担任职务的人，主持会议的人要说“主席”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "“主体”指收入中的主要部分，与“来自工资”相符，符合语境。"}, {"text": "性格", "is_correct": false, "explanation": "语义：收入是钱，没有性格，“性格”不能指收入的构成。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不能说收入的体重。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”用于人，不能说收入的年龄。"}], "explanations": {"主体": "“主体”指收入中的主要部分，与“来自工资”相符，符合语境。", "性格": "语义：收入是钱，没有性格，“性格”不能指收入的构成。", "体重": "搭配：“体重”指人或动物的重量，不能说收入的体重。", "年龄": "搭配：“年龄”用于人，不能说收入的年龄。"}, "sentence_index": 6, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的主体是一位老人。", "explanation": "这里应该用〈主角〉。“主体”指事物的主要部分，指故事中的主要人物要说“主角”。"}, {"text": "这场晚会的主体是小王。", "explanation": "这里应该用〈主持人〉。“主体”不指担任节目主持的人，晚会的主持人要说“主持人”。"}, {"text": "这台机器的主体是一位工人。", "explanation": "这里应该用〈操作工〉。“主体”指机器的主要部分，不指操作机器的人，操作机器的人要说“操作工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座大桥的一座主体已经建好了。", "corrected_sentence": "这座大桥的主体已经建好了。", "error_description": "量词错误。“座”只用于整座建筑或桥梁，“主体”指其中的主要部分，不能用“座”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个雕塑的主体青铜做的。", "corrected_sentence": "这个雕塑的主体是青铜做的。", "error_description": "错误：漏掉了系词“是”。“主体”作主语后，谓语需要“是”，应写作“这个雕塑的主体是青铜做的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "萧条", "is_correct": true, "explanation": "“萧条”与“繁荣”互为反义，指经济或事业不景气。"}, {"text": "清晰", "is_correct": false, "explanation": "与“繁荣”无反义关系，“清晰”指清楚明白，不表示经济状况。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“繁荣”无反义关系，“宽阔”指空间面积大，不表示经济状况。"}, {"text": "柔软", "is_correct": false, "explanation": "与“繁荣”无反义关系，“柔软”指质地不硬，不表示经济状况。"}], "correct_answer": "萧条", "explanations": {"萧条": "“萧条”与“繁荣”互为反义，指经济或事业不景气。", "清晰": "与“繁荣”无反义关系，“清晰”指清楚明白，不表示经济状况。", "宽阔": "与“繁荣”无反义关系，“宽阔”指空间面积大，不表示经济状况。", "柔软": "与“繁荣”无反义关系，“柔软”指质地不硬，不表示经济状况。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "萧条", "is_correct": true, "explanation": "“萧条”与“繁荣”互为反义，指经济或文化事业不景气。"}, {"text": "陈旧", "is_correct": false, "explanation": "与“繁荣”无反义关系，“陈旧”指东西过时，不表示经济或文化状况。"}, {"text": "细小", "is_correct": false, "explanation": "与“繁荣”无反义关系，“细小”指体积或数量小，不表示经济或文化状况。"}, {"text": "深沉", "is_correct": false, "explanation": "与“繁荣”无反义关系，“深沉”指感情或思想含蓄，不表示经济或文化状况。"}], "correct_answer": "萧条", "explanations": {"萧条": "“萧条”与“繁荣”互为反义，指经济或文化事业不景气。", "陈旧": "与“繁荣”无反义关系，“陈旧”指东西过时，不表示经济或文化状况。", "细小": "与“繁荣”无反义关系，“细小”指体积或数量小，不表示经济或文化状况。", "深沉": "与“繁荣”无反义关系，“深沉”指感情或思想含蓄，不表示经济或文化状况。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容经济或事业蓬勃发展，兴旺发达。", "primary_collocate": null, "pronunciation": "fán róng", "ipa": "fan˧˥ ʐʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个城市的繁荣吸引了很多年轻人。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的经济越来越繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唐朝是中国历史上很繁荣的时代。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场繁荣了，人们的生活也好了。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家繁荣，人民才能过上好日子。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条商业街非常繁荣，每天都有很多人。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化繁荣需要自由的环境。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望自己的家乡早日繁荣起来。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港口带来了贸易，小镇变得繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的文化和经济都很繁荣。", "target_word": "繁荣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "繁荣昌盛", "label": "复合词"}, {"form": "繁榮", "label": "繁体"}], "register": "书面", "sense_fingerprint": "经济、文化或事业蓬勃发展、兴旺发达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7b9a3fd-5ea1-4373-b394-1f2d643d1e41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
